window.LESSONS = [
  {
    id: 1,
    title: "第1课 · 易经的门钥匙：阴阳与八卦",
    subtitle: "曾仕强说：易经不是算命书，是改命书",
    review: "同学你好！欢迎来到『每天一卦·易经小课堂』。从今天起，我们每天学一点易经，用曾仕强爷爷讲的方法，把老祖宗的智慧变成你生活里用得上的本事。今天是第一课，我们先认识易经的『地基』：阴阳和八卦。上节课还没有，所以这一节，我们先从『易经到底是啥』聊起。",
    blocks: [
      { t: "h", s: "一、先破个误会：《易经》不是算命书" },
      { t: "p", s: "先问你一个问题：你觉得《易经》是一本算命书吗？" },
      { t: "p", s: "很多人以为是。但曾仕强教授说：易经不是算命书，是『改命书』。" },
      { t: "p", s: "它不告诉你未来一定怎样，而是教你看清现在的道理，自己做出好选择。" },
      { t: "p", s: "《易经》的『易』字，老祖宗总结了三个意思，叫『易有三义』。" },
      { t: "p", s: "第一是『变易』：世界上唯一不变的事，就是一切都在变。" },
      { t: "p", s: "你每天都在长高、在学新东西，连身体里的细胞，每七天就全部换一遍。" },
      { t: "p", s: "第二是『不易』：虽然万物都在变，但变的规律不变。" },
      { t: "p", s: "比方说，四季一定会轮回，种瓜得瓜、种豆得豆，这个理儿不会变。" },
      { t: "p", s: "第三是『简易』：再复杂的道理，也能用最简单的话说清楚。" },
      { t: "p", s: "曾仕强常说：大道至简。把复杂的事看简单，你就入门了。" },
      { t: "p", s: "记住这三句话：变易、不易、简易。它们是打开易经的钥匙。" },

      { t: "h", s: "二、阴阳：一对谁也离不开谁的好搭档" },
      { t: "p", s: "易经最核心的两个字，叫『阴阳』。" },
      { t: "p", s: "阴阳不是死对头，而是一对好搭档，谁也离不开谁。" },
      { t: "p", s: "给你举几个生活里的例子：白天是阳，晚上是阴；夏天是阳，冬天是阴。" },
      { t: "p", s: "男同学是阳，女同学是阴；你伸出手，手背是阳，手心是阴。" },
      { t: "p", s: "就连手机也有阴阳：充电是阳，用电是阴。" },
      { t: "p", s: "最妙的是：阳里藏着阴，阴里藏着阳。" },
      { t: "diagram", key: "taiji", caption: "这是太极图：一黑一白两条鱼抱成一圈，黑鱼里有白点，白鱼里有黑点。它想告诉你——顺境里藏着危险，逆境里也藏着机会。" },
      { t: "p", s: "你看这张太极图：黑鱼里有白点，白鱼里有黑点。" },
      { t: "p", s: "意思是：顺境里藏着危险，逆境里也藏着机会。" },
      { t: "p", s: "曾仕强说得好：走到最低谷，只要不放弃，转机就来了——这叫『否极泰来』。" },
      { t: "p", s: "所以遇到难题别慌，告诉自己：阴到极点，阳就来了。" },

      { t: "h", s: "三、八卦：八个会说话的符号" },
      { t: "p", s: "光有阴阳两个符号还不够。老祖宗把阴阳三三两两一组合，变出了八个基本符号，叫『八卦』。" },
      { t: "p", s: "每一个卦，由三条线组成。整条的叫阳爻（yáo），中间断开的叫阴爻。" },
      { t: "p", s: "八卦分别叫：乾、坤、震、艮、离、坎、兑、巽（xùn）。" },
      { t: "p", s: "先送你一句祖传口诀，背会它就记住了八个卦的样子：" },
      { t: "mnemonic", title: "八卦形状口诀", items: [
        "乾三连：三条线连在一起。",
        "坤六断：三条线都断开，变成六小段。",
        "震仰盂：像一只仰着口的盆。",
        "艮覆碗：像一只扣着的碗。",
        "离中虚：上下实线，中间空。",
        "坎中满：上下虚线，中间实。",
        "兑上缺：最上面那条线有缺口。",
        "巽下断：最下面那条线断开。"
      ]},
      { t: "p", s: "八卦还代表八种自然现象，最好记的一句：乾天坤地，震雷巽风，坎水离火，艮山兑泽。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：八个卦围成一圈。最上面是乾（天），然后顺时针是兑（泽）、离（火）、震（雷）、巽（风）、坎（水）、艮（山）、坤（地）。每个卦下面标了它代表的“自然现象”。" },
      { t: "p", s: "古人还把八卦当成一家人：乾是爸爸，坤是妈妈，剩下六个是他们的儿女。" },
      { t: "p", s: "震是长子，巽是长女，坎是二儿子，离是二女儿，艮是小儿子，兑是小女儿。" },
      { t: "p", s: "把八卦想成『一家八口』，你就再也忘不掉啦。" },

      { t: "h", s: "四、生活案例：乾卦教刚进新环境的你" },
      { t: "case", title: "潜龙勿用", s: "乾卦是八卦里最刚健的一卦，代表『天』，教我们『自强不息』。乾卦有六条爻，第一条叫『潜龙勿用』。意思是：你还是一条潜伏在水底的龙，先别急着飞出来显摆。曾仕强常拿来提醒刚上初中、刚进新环境的小朋友：先悄悄观察、悄悄积累。就像你转学第一天，别急着当风云人物，先看懂规矩、交到朋友、把功课稳住。龙潜得越深，将来才飞得越高。这就是乾卦送你的第一句人生忠告。" },

      { t: "h", s: "五、记忆妙招（曾仕强也用的三招）" },
      { t: "mnemonic", title: "三招记牢今天的内容", items: [
        "口诀法：把『乾三连坤六断』那八句抄在便利贴，贴书桌，每天念一遍。",
        "画图法：拿张纸，自己画一遍太极图和八个卦，画一遍胜过读十遍。",
        "故事法：把八卦想成一家八口，给每家编一句口头禅，像看动画片一样记。"
      ]},
      { t: "p", s: "曾仕强说：每个人的心里都有一部易经。你用的越多，它越灵。" },

      { t: "show64" },
      { t: "quiz", questions: [
        { type: "choice", q: "《易经》的『易』有哪三层意思？", options: ["变易、不易、简易", "阴阳、五行、八卦", "天、地、人", "乾、坤、屯"], answer: 0, explain: "易有三义：变易（万物在变）、不易（规律不变）、简易（大道至简）。" },
        { type: "choice", q: "哪句口诀对应『中间实线、上下虚线』的卦？", options: ["离中虚", "坎中满", "兑上缺", "坤六断"], answer: 1, explain: "坎中满：坎卦中间一条实线，上下两条虚线，像水流不断。" },
        { type: "choice", q: "乾卦第一爻『潜龙勿用』，对刚进新环境的你，意思是？", options: ["赶紧表现自己", "先低调观察积累", "什么都不做", "马上当领导"], answer: 1, explain: "潜龙勿用不是不用你，是让你先潜下来，了解环境、学本事，将来才飞得高。" },
        { type: "say", q: "请用阴阳解释『手机充电和用电』，并说说为什么『阳里藏阴』。", model: "充电是阳（能量进来、变强），用电是阴（能量出去）。阳里藏阴：手机满电（阳）时，其实正悄悄老化、电量在流失（阴）；没电（阴）时，只要充上电，转机就来了（阳）。所以顺境别得意忘形，逆境也别放弃。" }
      ]}
    ]
  },
  {
    id: 2,
    title: "第2课 · 八卦叠罗汉：两个三画卦拼出六十四卦",
    subtitle: "曾仕强说：六十四卦，就是人生的六十四种剧本",
    review: "上节课我们拿到了打开《易经》的三把钥匙：『易有三义』——变易（啥都在变）、不易（变的规律不变）、简易（再复杂也能说简单）；还认识了阴阳这对谁也离不开谁的好搭档，阳里藏阴、阴里藏阳，那张太极图就是它们的『全家福』；接着又学会了八个基本符号『八卦』，把它们想成『乾爸爸、坤妈妈加上六个儿女』的一家人，还记住了乾卦第一爻『潜龙勿用』——刚进新环境，先低调观察、悄悄积累本事。今天，咱们玩一个八卦的『叠罗汉』游戏，看看这八个卦怎么一组合，就变出了六十四卦。",
    blocks: [
      { t: "h", s: "一、八卦叠罗汉：三画卦叠成六画卦" },
      { t: "p", s: "上节课的八个卦，每一个都是由『三条线』组成的，叫三画卦。" },
      { t: "p", s: "老祖宗很会玩组合：把一个三画卦放在上面，再叠一个三画卦在下面，上下一拼，就变成了有『六条线』的六画卦。" },
      { t: "p", s: "上面那个卦，可以随便从八个里挑；下面那个，也可以随便从八个里挑。" },
      { t: "p", s: "八个挑上面、八个挑下面，8乘8等于64——没错，六十四卦就是这么来的！" },
      { t: "p", s: "你第1课点过的『六十四卦全图』，其实就是这64种上下组合，整整齐齐排成的一大张表。" },

      { t: "h", s: "二、上卦和下卦：一个管外面，一个管自己" },
      { t: "p", s: "叠出来的六画卦，上面三爻叫『上卦』，也叫『外卦』，代表你周围的环境、别人、外部条件。" },
      { t: "p", s: "下面三爻叫『下卦』，也叫『内卦』，代表你自己、你的内心和你能控制的部分。" },
      { t: "p", s: "曾仕强常提醒：看一件事，先看下卦（自己这边稳不稳），再看上卦（外面环境顺不顺）。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：乾、兑、离、震、巽、坎、艮、坤八个卦围成一圈。记住——这八个里的任意一个，都能去当『上卦』，也能去当『下卦』；上、下各来一个，一拼就是一卦，八八六十四，一张大表就拼满了。" },
      { t: "p", s: "下面这张八卦图里，任何一个卦都能当一次『上』、一次『下』，八八六十四种拼法，就是六十四卦的来历。" },

      { t: "h", s: "三、六十四卦 = 人生的六十四种剧本" },
      { t: "p", s: "你可能会问：拼出64个卦，然后呢？" },
      { t: "p", s: "曾仕强说得好：这六十四卦，不是用来算你明天中不中奖的，而是『宇宙人生的六十四种情境』。" },
      { t: "p", s: "考试前紧张，对应某一卦；跟好朋友闹别扭，对应某一卦；考了第一名、全家高兴，也对应某一卦。" },
      { t: "p", s: "每一卦都像一集小短剧，告诉你：你现在处在什么处境，该怎样调整自己。" },
      { t: "p", s: "举个例子：第11卦叫『泰卦』，是地在上、天在下。天之气往下降，地之气往上升，上下通气，就叫『天地交泰』——形容事情顺、关系好。" },
      { t: "p", s: "反过来，第12卦叫『否（pǐ）卦』，天在上、地在下，各走各的路、谁也不理谁，气就不通了，事情就卡住。所以老话才讲『否极泰来』：坏到极点，转机就来了。" },

      { t: "h", s: "四、生活案例：用『上下卦』看一次考试" },
      { t: "case", title: "我考砸了，是哪一卦？", s: "用周易的思维拆一下：下卦是你自己——有没有认真复习、心态稳不稳、睡没睡好；上卦是环境——题难不难、老师严不严、运气好不好。上卦你管不了，下卦你管得了。所以与其考完就抱怨『题太难、老师针对我』（这是上卦，怪也没用），不如先把『下卦』这半边稳住：平时踏实学、考前睡好觉、进考场不慌神。曾仕强讲『反身修德』——把自己这块修好了，外卦再差，整体也坏不到哪儿去。下次成绩往上走，往往就是从你把下卦稳住开始的。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住六十四卦的来路", items: [
        "乘法口诀法：八个卦，上、下各来一次，8×8=64，像背九九表一样记住这个数。",
        "上下定位法：上卦看环境（外），下卦看自己（内）；看事先盯自己这半边，再管外面。",
        "剧本法：把六十四卦想成64集连续剧，每天遇到的事，都能对号入座找一集看看。"
      ]},
      { t: "p", s: "曾仕强说：六十四卦不是让你认命，而是让你看清处境、把能改的改好。" },

      { t: "quiz", questions: [
        { type: "choice", q: "六十四卦是怎么来的？", options: ["八卦两两相加自动变成一卦", "八个三画卦上下各取一个组合，8×8=64", "六十四卦是随便编出来凑数的", "只有乾、坤两卦能互相组合"], answer: 1, explain: "每个三画卦都能当上卦也能当下卦，八种上配八种下，8×8=64 种组合。" },
        { type: "choice", q: "在六画卦里，『下卦（内卦）』代表什么？", options: ["周围的环境和别人", "你自己、内心、你能控制的部分", "当天的天气和运气", "老师和父母的态度"], answer: 1, explain: "下卦是内卦，代表你自己这一边；上卦（外卦）才是外面的环境。" },
        { type: "choice", q: "曾仕强说六十四卦更像什么？", options: ["算命师给的命运结果", "人生的六十四种情境、六十四本小剧本", "六十四道数学题", "六十四个星座"], answer: 1, explain: "六十四卦是宇宙人生的六十四种处境，每一卦教你怎么调整自己，不是算你命。" },
        { type: "say", q: "请用『上卦看环境、下卦看自己』的思路，说说你最近遇到的一件烦心事：哪部分是你能控制的，哪部分控制不了？", model: "比如我这次小组作业被队友拖了后腿（上卦/环境，我控制不了队友）。但我能控制的是自己的下卦：按时完成我那一份、提前跟队友沟通进度、实在不行主动找老师协调。先把『下卦』稳住，少抱怨环境，事情就不会太糟。这正是曾仕强说的先看自己、再谈改变外面。" }
      ]}
    ]
  },
  {
    id: 3,
    title: "第3课 · 乾卦六条龙：一个人的成长六部曲",
    subtitle: "曾仕强说：人生，就是阶段性的调整",
    review: "上节课我们玩了八卦的『叠罗汉』——把任意两个三画卦上下一拼，8乘8变出六十四卦，这就是人生的六十四种剧本。我们还学会了一双『透视眼』：看一件事，下卦（内卦）是你能控制的自己，上卦（外卦）是你管不了的环境；考试考砸了别光怨题难（上卦），先把『下卦』稳住、反身修德。我们还认识了泰卦（天地交泰、事情顺）和否卦（天地不交、卡住了），记住了『否极泰来』。今天，我们钻进六十四卦里的第一卦——乾卦，看看它用六条龙，把一个人的成长分成了哪六个阶段。",
    blocks: [
      { t: "h", s: "一、先学一个本事：一个卦怎么读" },
      { t: "p", s: "上节课拼出了六十四卦。那你可能会问：卦拼出来了，里面密密麻麻的字，我该怎么读？" },
      { t: "p", s: "简单说，每个卦有两层说明书。第一层叫卦辞，是给整卦的一句话总结，告诉你这一卦大概是什么处境。" },
      { t: "p", s: "第二层叫爻辞，是给每一根线（每一爻）的悄悄话，告诉你这根线所在的位置，该怎么做。" },
      { t: "p", s: "读爻有个规矩：从下往上数，第一爻叫初，然后二、三、四、五，最上面那根叫上。" },
      { t: "p", s: "光看位置还不够，还要看它是阴是阳：阳爻（整条线）叫九，阴爻（断开的线）叫六。" },
      { t: "p", s: "所以最底下那根阳线，就读作初九；往上第二根阳线叫九二；最顶上的阳线叫上九。阴线就相应读成初六、六二、上六。" },
      { t: "p", s: "记住这个读法，你就能看懂任何一卦在说什么了。" },

      { t: "h", s: "二、乾卦六条龙：人生六个阶段" },
      { t: "p", s: "乾卦是六十四卦的第一卦，代表天，六根线全是阳爻，刚健得不得了。" },
      { t: "p", s: "曾仕强把乾卦的六根阳爻，看成同一条龙在人生六个阶段的不同样子，用六个字概括，从下往上是：潜、现、惕、跃、飞、亢。" },
      { t: "p", s: "第一条龙，初九，潜龙勿用：刚进新环境，先潜伏下来观察、积累，别急着显摆（这个我们在第1课就见过了）。" },
      { t: "p", s: "第二条龙，九二，见龙在田，利见大人：看准机会露一手，但要让人欢迎你，不是唯我独尊。" },
      { t: "p", s: "第三条龙，九三，君子终日乾乾，夕惕若厉：白天拼命干，晚上还得反省，因为这个位置不上不下，最容易招人嫉妒。" },
      { t: "p", s: "第四条龙，九四，或跃在渊：这是可上可下的转折点。跃过去就飞龙在天，跃不过至少退回深渊保命——所以出手前先想好退路。" },
      { t: "p", s: "第五条龙，九五，飞龙在天：人生最鼎盛的时候。但曾仕强提醒，到了顶更要礼贤下士，把功劳让给伙伴，别一人独揽。" },
      { t: "p", s: "第六条龙，上九，亢龙有悔：物极必反，刚到极点就会折断。到了顶峰要懂得收手、功成身退，不然就会后悔。" },
      { t: "diagram", key: "taiji", caption: "乾卦六爻虽然全是阳，但上九『亢龙有悔』告诉你：阳到极点要回头。就像这张太极图——白鱼（阳）太旺时，要记得里面那颗黑点（阴），刚中带柔，才不会折断。逞强到底，反而会摔得很惨。" },
      { t: "p", s: "乾卦还有一句特别的话，叫用九：见群龙无首，吉。" },
      { t: "p", s: "别被字面吓到：这里群龙无首不是没领导、乱糟糟，而是说——哪怕你本事大如龙，处在不同阶段也要换不同做法，不固守一套。" },
      { t: "p", s: "一句话总结：人生，就是阶段性的调整。" },

      { t: "h", s: "三、生活案例：刚当上小组长的你" },
      { t: "case", title: "我是新官，怎么用乾卦？", s: "你刚被任命为小组长，这正对应九二『见龙在田』——先别急着摆官威，把活儿干漂亮、让组员服气（利见大人）。干了一阵子到了九三，要更拼，但晚上得想想今天是不是得罪谁了。等到有个大项目机会（九四『或跃在渊』），先想清楚搞砸了怎么办，再决定跳不跳。真当上负责人（九五『飞龙在天』），把功劳分给伙伴，别一人独吞。曾仕强特别提醒：走到顶（上九）要知道收，该交棒就交棒，不然『亢龙有悔』。同一条龙，不同阶段做法完全不同，这就是乾卦教你的阶段性调整。" },

      { t: "h", s: "四、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住乾卦六龙", items: [
        "六字口诀法：潜、现、惕、跃、飞、亢——顺着从下往上的顺序背成潜现惕跃飞亢，比记六条爻辞轻松多了。",
        "读爻定位法：从下往上数（初、二、三、四、五、上），阳爻叫九、阴爻叫六；看到初九就知道是最底下那根阳线。",
        "楼梯比喻法：把六爻想成六层楼梯，一层层往上爬；爬到顶（上九）别得意，记得亢龙有悔要回头。"
      ]},
      { t: "p", s: "曾仕强说：乾卦不是教人永远往前冲，而是教人像天一样持久刚健，又懂得什么时候该退一步。" },

      { t: "quiz", questions: [
        { type: "choice", q: "乾卦的六根爻，为什么都用龙来打比方？", options: ["龙多变、难缠又神通广大，正合自强不息的人生", "因为龙是动物里个头最大的", "因为乾卦代表地", "因为龙只会飞不会游"], answer: 0, explain: "乾卦大象天行健，君子以自强不息，龙变化多端、神通广大又最难掌控，正好用来比喻一个自强不息的人在不同阶段的处境。" },
        { type: "choice", q: "在易经里，一个卦最底下那一根阳爻，读作什么？", options: ["上九", "初六", "初九", "九一"], answer: 2, explain: "读爻从下往上数，第一爻叫初；阳爻叫九，所以最底下的阳线是初九。阴线才读成初六。" },
        { type: "choice", q: "亢龙有悔给处在人生顶峰的我们，最重要的提醒是？", options: ["要更加倍地往前冲", "物极必反，要懂得知止、功成身退", "什么都不用管了", "赶紧换一份工作"], answer: 1, explain: "上九阳到极点就会折断，曾仕强提醒到了顶峰要知止，该交棒交棒、该退休退休，否则亢龙有悔。" },
        { type: "say", q: "请用人生就是阶段性的调整这句话，说说你现在处在乾卦六龙里的哪一条龙？接下来你最该注意什么？", model: "比如我现在像九二见龙在田——刚在新环境露了点本事，接下来最该注意的是利见大人：把成绩归功于老师和同学的帮助，别显得唯我独尊，让人愿意继续带我、挺我。等机会再大一点（九四或跃在渊），我会先想好退路再决定要不要拼。总之不同阶段用不同做法，不一套走到底。" }
      ]}
    ]
  },
  {
    id: 4,
    title: "第4课 · 坤卦：厚德载物的配合智慧",
    subtitle: "曾仕强说：乾是创造，坤是配合，配合得当才是最高智慧",
    review: "上节课我们钻进了六十四卦的第一卦——乾卦，看它用六条龙，把一个人的成长分成六个阶段：潜龙勿用（刚进环境先潜伏积累）、见龙在田（露一手但要让人欢迎）、终日乾乾（白天拼命晚上反省）、或跃在渊（可上可下想好退路）、飞龙在天（鼎盛时礼贤下士）、亢龙有悔（到顶要懂收手）。我们还学了『用九：群龙无首』——不同阶段换不同做法，人生就是阶段性的调整。乾卦六根线全是阳，刚健得不得了，教我们『天行健，君子以自强不息』。可是，光有天、光有龙，万物能长出来吗？不能。今天，我们请出和乾卦配成一对儿的——坤卦，看看这位『大地妈妈』，藏着怎样的配合智慧。",
    blocks: [
      { t: "h", s: "一、乾的搭档来了：坤卦到底是什么" },
      { t: "p", s: "乾卦六根线全是阳爻，叫纯阳卦。如果这六根阳线一下子全翻成阴线，就变成纯阴卦——坤卦。" },
      { t: "p", s: "乾和坤，互为『错卦』：你把我每一根线反过来，我就变成你。一张一弛，刚好配成一对。" },
      { t: "p", s: "乾是创造的、带头冲的、像爸爸；坤是配合的、承载的、像妈妈。曾仕强说：乾是创造，坤是配合，配合得当才是最高智慧。" },
      { t: "p", s: "乾卦用龙打比方（天上飞），坤卦用马打比方（地上跑）。为什么用马不用牛？因为牛是瞎顺从，叫它干啥都干；马不一样，马忠贞，但有自己的原则——该跟的才跟，不该跟的根本不理。" },
      { t: "p", s: "所以坤卦卦辞说『利牝马之贞』：要像母马一样，柔顺但有原则。坤卦最出名的一句话，叫『地势坤，君子以厚德载物』——大地不说话，却托着山、托着楼、托着你我，什么重担都接得住。" },
      { t: "p", s: "人也该学大地：肚量宽一点，能容人容事。这，就是坤卦教你的第一件事。" },

      { t: "h", s: "二、坤卦的六条线，藏着六句悄悄话" },
      { t: "p", s: "乾卦有六条龙，坤卦也有六句悄悄话。顺着从下往上读，分别是：履霜、直方大、含章、括囊、黄裳、龙战。" },
      { t: "p", s: "初六，履霜坚冰至：脚底下踩到薄霜，就要想到寒冬快来了。意思是见微知著——小毛病早改，别等结成坚冰就难弄了。" },
      { t: "p", s: "这句跟乾卦的『潜龙勿用』是一对儿：地位低、人微言轻时，都别急着多嘴，先多听多学。" },
      { t: "p", s: "六二，直方大：做人正直（直）、立场坚定（方）、格局宽广（大），这样不用刻意学套路，到哪儿都顺。" },
      { t: "p", s: "六三，含章可贞：你肚子里有才华，先别急着显摆，像含着一颗糖慢慢品。藏得住锋芒的人，别人反而越看越欣赏，像宝藏一样挖不完。" },
      { t: "p", s: "六四，括囊：把口袋扎紧，少说话。处在敏感位置，谨言慎行最保险——不惹事，也不怕事。" },
      { t: "p", s: "六五，黄裳元吉：穿素净的黄色下衣，大吉。意思是到了高处，反而要低身段、不张扬，谦逊才稳。" },
      { t: "p", s: "上六，龙战于野：阴柔走到极点，也会生出逞强争斗的心，像地龙想跟天龙抢天，两败俱伤。曾仕强提醒：坤道是配合，别越位去当主角，守住本分最平安。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：坤（妈妈）在最底下，和乾（爸爸）上下相对，正好一对儿。坤代表地、代表配合与承载。记住——乾爸爸负责带头创造，坤妈妈负责配合承载，缺了谁都不行。曾仕强说这就是『乾坤配』：一个在前引，一个在后跟，事情才做得成。" },
      { t: "p", s: "你看这张八卦图：坤（妈妈）在最底下，和乾（爸爸）上下相对，刚好一对儿。乾负责带头创造，坤负责配合承载，缺了谁都不行。" },

      { t: "h", s: "三、生活案例：小组作业，我该当乾还是当坤" },
      { t: "case", title: "我是组员，怎么用坤道？", s: "这次大项目，组长已经定好了（他当乾，发号施令），你当组员（坤，全力执行）。曾仕强讲『乾坤配』：没有领导，再强的执行力没方向；没人执行，再好的领导也落空。所以你别硬抢风头当主角（那会『龙战于野』），而是学母马——组长方向对，你全力配合、把活干漂亮；组长要是让你干不合理的，你也别盲从（马有原则）。平时把『含章可贞』用上：本事藏一点、不抢功，组员关系反而更顺。这就是坤道的配合智慧：成全别人，也成全整个团队。" },

      { t: "h", s: "四、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住坤卦", items: [
        "龙马对照法：乾用龙（天上飞、带头），坤用马（地上跑、配合）；记不住就想想『龙马精神』——一个在前引，一个在后跟。",
        "六字顺口溜：履霜、直方、含章、括囊、黄裳、龙战——从下往上连成一句，比背六句爻辞轻松。",
        "妈妈比喻法：把坤想成『大地妈妈』，她不抢镜、不抱怨，默默把家撑起来；遇到事先想『这事我该配合还是该出头』。"
      ]},
      { t: "p", s: "曾仕强说：孤阴不生，独阳不长。乾和坤，谁也离不了谁。读懂了乾坤，你就拿到了打开《易经》的两把钥匙。" },

      { t: "quiz", questions: [
        { type: "choice", q: "坤卦为什么用『马』打比方，而不用『牛』？", options: ["马比牛更能干活", "牛是瞎顺从，马柔顺但有原则、不盲从", "因为马跑得比牛快", "因为坤代表天"], answer: 1, explain: "牛叫它干啥都干，有点盲从；马忠贞却坚守原则，该跟的才跟、不该跟的根本不理。所以坤卦用马，提醒我们配合不等于盲从。" },
        { type: "choice", q: "初六『履霜坚冰至』给地位还低、人微言轻的我们，最重要的提醒是？", options: ["赶紧表现自己", "见微知著，小毛病早改，先多听多学少抢话", "什么都不用管", "马上去当领导"], answer: 1, explain: "踩到霜就想到寒冬，小问题早处理。这和乾卦『潜龙勿用』是一对：地位低时别急着多嘴，先吸收经验。" },
        { type: "choice", q: "上六『龙战于野』对处在配合位置的我们，意味着什么？", options: ["要更狠地争第一", "坤道是配合，别越位抢主角，守住本分", "赶紧离开团队", "什么都不做等别人喂"], answer: 1, explain: "阴柔越位去跟阳刚争，两败俱伤。坤道讲配合与承载，守住本分、不抢主角位，才平安。" },
        { type: "say", q: "请用『乾坤配』说说你最近一次和别人合作：谁是乾（带头）、谁是坤（配合）？你配合得当吗？哪里还可以更好？", model: "比如上次做手抄报，小明当乾（定主题、分活），我当坤（负责画画、配合）。我配合得还行，但有时他想改方案我有点不高兴、抢着反驳，这就有点『龙战于野』了。以后我该学母马：方向对就全力跟，有不同意见私下好好说，不公开顶撞。把『含章可贞』用上，少抢功、多成全，团队反而更顺。" }
      ]}
    ]
  },
  {
    id: 5,
    title: "第5课 · 谦卦：山躲进地底下的谦虚智慧",
    subtitle: "曾仕强说：谦卦是六十四卦里唯一六爻皆吉的卦",
    review: "上节课我们请出了坤卦——大地妈妈，厚德载物、配合承载。她教我们『利牝马之贞』：柔顺但有原则，像母马，该跟的才跟、不该跟的根本不理；还给了我们六句悄悄话：履霜（见微知著、小毛病早改）、直方大（正直坚定格局宽）、含章（藏住锋芒别抢功）、括囊（敏感位置少说话）、黄裳（到了高处反而要低身段）、龙战（别越位去抢主角位）。最后我们学到『乾坤配』：乾爸爸带头创造，坤妈妈配合承载，一个人是领导力、一个人是执行力，谁也离不了谁。今天，我们要认识一个跟坤关系特别深的卦——谦卦。它把『地』放到上面、把『山』藏到下面，用一幅反着来的画，告诉我们什么叫真正的谦虚。",
    blocks: [
      { t: "h", s: "一、谦卦长啥样：一座山，躲进了地底下" },
      { t: "p", s: "上节课我们认识了坤卦，大地妈妈，厚德载物、配合承载。今天来认识一个跟坤很有关系的卦——谦卦，它是六十四卦里的第15卦。" },
      { t: "p", s: "谦卦的画法是：上面三爻是坤（地），下面三爻是艮（山），合起来叫『地山谦』。" },
      { t: "p", s: "你平常抬头看，山不都是高高站在地上的吗？可这个卦偏偏反着来——山不往上冒，反倒躲到地底下去了。" },
      { t: "p", s: "山本来有资格高高地立着，它却主动把位置让出来、蹲到最低处。这就是『谦』字最形象的画面：有本事，但不张扬。" },
      { t: "p", s: "所以《易经》给谦卦写了一句象传：『地中有山，谦。』——大地里面藏着一座山，外面看着平平的，里面其实很有料。" },

      { t: "h", s: "二、六爻皆吉：六十四卦里唯一的『全优卦』" },
      { t: "p", s: "曾仕强爷爷讲《易经》时，最爱拿谦卦打比方。他说：六十四卦没有绝对的好坏，但大多会给你几句警告；唯独谦卦是个例外——六条爻辞，条条都好，叫『六爻皆吉』。" },
      { t: "p", s: "你看别的好听卦名，里面往往藏着提醒；难听的卦名，反而给你鼓励。可谦卦连一条坏话都没有，从头吉到尾。" },
      { t: "p", s: "谦卦的卦辞只有几个字：『谦，亨，君子有终。』意思是：谦虚的人，路子走得通（亨），而且能坚持到底、有好下场（君子有终）。" },
      { t: "p", s: "它的彖传更妙：『谦尊而光，卑而不可逾。』翻译过来就是——你越谦虚，地位越高反而越发光；你处在低位，别人也越过不了你。" },
      { t: "p", s: "还有一句：『天道亏盈而益谦，人道恶盈而好谦。』老天爷专门减掉满的、补给谦的；人也是一样，讨厌自满的人，喜欢谦让的人。" },
      { t: "diagram", key: "taiji", caption: "这是太极图：谦卦六个爻里只有一条阳爻（九三），其余五条都是阴爻，就像一颗白点藏在黑鱼里。阳（本事）藏在阴（低调）之中——有实力却不显摆，正是太极图想说的阴阳互含。所以谦虚不是没本事，是本事藏得好。" },
      { t: "p", s: "记住这张太极图的道理：谦卦把唯一的阳爻（本事）藏在五个阴爻（低调）当中，就像白点藏在黑鱼里。" },
      { t: "p", s: "外柔内刚、内高外低——这才是真正的谦虚，不是没底气，是底气藏得好。" },

      { t: "h", s: "三、生活案例：考了第一名，该怎么用谦卦" },
      { t: "case", title: "我考了第一，要不要嘚瑟？", s: "假设你这次考了全班第一，同学都来恭喜。这时候最该用谦卦。曾仕强讲：谦虚有个大前提——你得真有实力。你考第一，说明你有本事（山还是山），但别像有些同学那样到处显摆、看不起人（那叫『满招损』）。学那座躲进地底的山：嘴上说『运气好、题目刚好复习到』，转头继续踏实学。这叫『谦尊而光』——你越不飘，大家越服你、越愿意帮你。反过来，一考好就飘，下次多半摔跟头。谦卦的九三爻说『劳谦，君子有终』：一边努力干活、一边保持谦逊，才能笑到最后。" },

      { t: "h", s: "四、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住谦卦", items: [
        "画面法：默念『地山谦』三个字——山躲到地底下，把高位让出来，这就是谦虚的样子，比死背卦画好记。",
        "六字诀：谦亨有终、六爻皆吉——记住谦卦是唯一全优卦，卦辞说『谦虚能走得通、还能坚持到底』。",
        "对比法：把谦卦和太极图放一起想——阳（本事）藏在阴（低调）里；有实力不显摆才是真谦虚，没本事那叫无能。"
      ]},
      { t: "p", s: "曾仕强说：一个人不管多厉害，只要能保持谦虚、对人礼让、心胸宽一点、别动不动计较，对自己就非常有利。" },

      { t: "quiz", questions: [
        { type: "choice", q: "谦卦的卦象是『地山谦』，它想告诉我们什么？", options: ["山应该高高地站在地上", "有本事的山主动蹲到地底下、把高位让出来，就是谦虚", "地和山谁也不理谁", "山比地更重要"], answer: 1, explain: "谦卦上坤（地）下艮（山），山本该高立，却躲进地底，象征有实力却不张扬的谦虚。" },
        { type: "choice", q: "曾仕强说谦卦在六十四卦里特别在哪？", options: ["它是唯一卦名难听的", "它是唯一『六爻皆吉』、条条都好的卦", "它全是阳爻", "它专门用来算考试"], answer: 1, explain: "别的卦多多少少有警告，唯独谦卦六条爻辞全吉，所以曾仕强特别推崇它。" },
        { type: "choice", q: "『谦尊而光，卑而不可逾』对越成功越谦虚的我们，意思是？", options: ["越谦虚越没人理", "你越谦虚，地位越高反而越发光，别人也越过不了你", "低位就该认怂", "成功就要赶紧炫耀"], answer: 1, explain: "谦虚让人地位越高越光辉，即便处在低位也无人能轻易超越，这是谦德的力量。" },
        { type: "say", q: "请用『山躲进地底』的画面，说说你身边一个真正谦虚的人（或你自己一次谦虚的经历）：他/她有实力却怎么不张扬的？", model: "比如我们班长数学次次前三，可别人夸他，他总说『这次运气好、同桌帮了我』，平时还主动给同学讲题。他就像谦卦里那座山——本事是真有（山还是山），但不显摆、把风头让给别人（躲进地底）。结果大家都服他、有什么事都找他商量。这就是『谦尊而光』：越不飘，越让人尊重。" }
      ]}
    ]
  },
  {
    id: 6,
    title: "第6课 · 蒙卦：山水蒙与怎么当一个好学生",
    subtitle: "曾仕强说：不是老师来求你学，是你来求老师",
    review: "上节课我们认识了谦卦——地山谦。一座本来高高在的山，主动蹲到地底下去，把高位让出来，教我们什么叫真正的谦虚：有本事，但不张扬。我们还记住了谦卦是六十四卦里唯一一个『六爻皆吉』的卦，卦辞说『谦，亨，君子有终』——谦虚的人路子走得通，还能坚持到底；更妙的是『谦尊而光，卑而不可逾』：你越谦虚，地位越高反而越发光，别人也越过不了你。那次考了第一名别嘚瑟的例子，你还记得吧？今天，我们顺着卦序往前挪一小步，来到第四卦——蒙卦。它跟上节课一样也牵扯到『山』，但这次山跑到上面、水跑到下面，而且专门讲一件事：怎么当一个会学习、会请教的好学生。",
    blocks: [
      { t: "h", s: "一、蒙卦长啥样：山底下藏着一汪水" },
      { t: "p", s: "上节课的谦卦是地山谦，山躲到地底下；今天的蒙卦反过来了——山跑到上面，水跑到下面，叫山水蒙。" },
      { t: "p", s: "蒙卦的画法是：上面三爻是艮（山），下面三爻是坎（水），合起来就是山水蒙。" },
      { t: "p", s: "你走到大山里头，是不是常看见山泉水？水从石头缝里渗出来，叮叮咚咚往下流，可你看不见山后面那个水源在哪儿。" },
      { t: "p", s: "曾仕强说：这就叫蒙——人本来是有潜力、有智慧的，但被一层东西蒙住了，就像山把水源挡在背后，看不见却一直在。" },
      { t: "p", s: "小孩子刚出生懵懵懂懂，叫童蒙；大人如果固执己见、不肯学，其实也是蒙。所以蒙卦不是骂人笨，而是说：每个人都有还没被打开的潜力，需要启蒙。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上卦是艮（山，小儿子），下卦是坎（水，二儿子）。两个『儿子』上下一叠，就成了山水蒙。你看山把水的源头挡在后面，正像我们没被打开的潜力被一层懵懂蒙住——这也呼应了第1课那『一家八口』：乾爸爸坤妈妈生的儿子们，自己也能叠出新卦来。" },
      { t: "p", s: "记住：蒙卦的『蒙』，不是笨，是还没被启发。山（艮）把水（坎）的源头挡住，潜力看得见出口、却看不清来路——这就等着你去把它引出来。" },

      { t: "h", s: "二、教育的基本原理：不是老师求你，是你求老师" },
      { t: "p", s: "蒙卦的卦辞有一句特别有名：匪我求童蒙，童蒙求我。翻成大白话就是——不是老师跑来求你『你快好好学习吧』，而是你要主动来问、来求学，老师才把答案给你。" },
      { t: "p", s: "曾仕强特别强调：教化不能强加。你一直追着孩子喂，他越听越烦、越听越不想学；反过来，学生自己想问、想学，老师一讲他就通。" },
      { t: "p", s: "所以孔子有教无类，但讲究自行束脩以上——不是在乎那点学费，是看你有没诚心。连一点点学费都不肯交，说明你没真心想学，那教了也白教。" },
      { t: "p", s: "还有半句：初筮告，再三渎，渎则不告。第一次真心发问，老师就给答案；可你要是一而再、再而三地试探、不诚心，像在考老师玩，那老师就该闭嘴不讲了——不是小气，是你的心不诚，讲了你也听不进去。" },

      { t: "h", s: "三、生活案例：怎么用蒙卦当一个好学生" },
      { t: "case", title: "我不懂，该怎么问老师？", s: "假设你数学课上一道大题卡住了，下课后想问老师。用蒙卦的思路就对了：第一，主动去问（童蒙求我）——别等老师来催，你带着问题凑过去，老师才乐意讲。第二，第一次问就认真听、问到点子上（初筮告）——把『这一步为什么这么写』问清楚，别一上来就说『老师这题我不会』然后发呆。第三，问完别反复试探、把老师当搜索引擎使（再三渎，渎则不告）——同一个知识点换个花样又来问，说明你没用心，老师自然不想多讲。曾仕强常说：一个人主动学习才进步，老被人喂，一生都倒霉。把蒙卦用起来，你就是老师眼里会问问题的好学生。" },

      { t: "h", s: "四、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住蒙卦", items: [
        "画面法：默念山水蒙三个字——山在上挡住水，水从山里渗出来流走，就像潜力被蒙住、等着被启发，比死背卦画好记。",
        "主动法：记住匪我求童蒙，童蒙求我——学习是我要去求老师，不是老师来求我；主动提问的人，进步最快。",
        "终身法：山外有山，学到一座山后面还有更高的山，所以活到老、学到老，蒙卦的山永远提醒你别停下。"
      ]},
      { t: "p", s: "曾仕强说：人非生而知之者，谁没困惑？蒙卦告诉我们——生来蒙昧很正常，关键是你要主动把那层蒙揭开。" },

      { t: "quiz", questions: [
        { type: "choice", q: "蒙卦的卦象山水蒙是怎么叠出来的？", options: ["上艮（山）下坎（水）", "上坎（水）下艮（山）", "上乾下坤", "上坤下艮"], answer: 0, explain: "蒙卦上卦是艮（山）、下卦是坎（水），所以叫山水蒙；艮把坎的源头挡在背后，象征潜力被蒙住。" },
        { type: "choice", q: "卦辞『匪我求童蒙，童蒙求我』讲的是什么道理？", options: ["老师要天天上门催你学", "教化不能强加，要学生主动来求教，老师才给答案", "学生不能问老师", "学费越贵学得越好"], answer: 1, explain: "蒙卦的教化原理是：不是老师求学生，而是学生主动求教；主动学习的人才会进步，强灌只会让人厌烦。" },
        { type: "choice", q: "『初筮告，再三渎，渎则不告』对提问的我们意味着？", options: ["第一次问就给答案，反复不诚心试探就不讲了", "问几次都讲", "从不给答案", "只给一半答案"], answer: 0, explain: "第一次真心发问就给答案；若一而再地试探、心不诚，老师就该停讲，因为讲了你也听不进去。" },
        { type: "say", q: "请用『童蒙求我』说说你最近一次请教别人（老师、家长或同学）的经历：你是主动去问的，还是等对方来教的？下次怎么做得更像会学的人？", model: "比如上周物理的浮力题我卡了半小时，是自己抱着本子去办公室问老师的（童蒙求我——主动求教，不是等老师来发现）。我问的时候直接说『这一步为什么用排开水的体积』，老师一点就通（初筮告）。下次我会在问之前先自己把思路写下来、标出到底卡在哪，这样问得更准，也不会反复试探惹老师烦。把蒙卦用起来，我就是会主动揭蒙的学生。" }
      ]}
    ]
  },
  {
    id: 7,
    title: "第7课 · 讼卦：天水讼与怎么不把架吵大",
    subtitle: "曾仕强说：最好是不讼，退一步比争到底聪明",
    review: "上节课我们认识了蒙卦——山水蒙。一座山压在水上头，把水源挡在背后，就像我们还没被打开的潜力被一层懵懂蒙住；于是老祖宗说「匪我求童蒙，童蒙求我」——学习不是老师来求你，是你主动去求教，老师才把答案给你；还告诉我们「初筮告，再三渎，渎则不告」——第一次诚心问就认真答，反复试探不诚心就不讲了。蒙卦还提醒我们：山外有山，活到老学到老。今天，我们要顺着卦序往前走一步，来到第六卦——讼卦。它跟蒙卦一样也牵扯「水」，但这次水跑到下面、天跑到上面，而且专门讲一件事：人和人闹矛盾了，怎么不把架吵大、不把小事闹成官司。",
    blocks: [
      { t: "h", s: "一、讼卦长啥样：天在水上头" },
      { t: "p", s: "上节课的蒙卦是山水蒙（上艮下坎）。今天的讼卦，水换到了下面，上面换成了天，叫「天水讼」。" },
      { t: "p", s: "讼卦的画法是：上面三爻是乾（天），下面三爻是坎（水），合起来就是天水讼。它是六十四卦里的第6卦。" },
      { t: "p", s: "你抬头看，天一个劲儿往上升；你低头看，水一个劲儿往低处流。一个往上、一个往下，背道而驰、各走各的路，谁也不理谁。" },
      { t: "p", s: "老祖宗说：这就像两个人吵起来——你往东说、我往西说，各说各话、谁也劝不住。这个画面，就叫「讼」，也就是争讼、打官司。" },
      { t: "p", s: "讼卦的大象传写得最形象：「天与水违行，讼。」方向反了，矛盾就生出来了。" },
      { t: "p", s: "它还跟第5课的需卦是一对儿（互为综卦）。需卦是水天需——云在天上还没下雨，教我们耐心等；讼卦是天水讼——天把水甩在下头、各奔东西，矛盾就爆发了。所以：需要等待，闹起来就讼。" },
      { t: "diagram", key: "taiji", caption: "这是太极图：讼卦告诉我们「最好不讼」——即便白鱼（争执、争强）再旺，也要记得里头那颗黑点（退让、和为贵）。阳（争）里藏着阴（让），争到头不如退一步，这正是太极图阴阳互含的道理：硬碰硬会两败俱伤，留一点余地给彼此，转机才来。" },
      { t: "p", s: "记住这张太极图的道理：讼卦虽然讲争，但核心精神是「不讼」——就像白鱼再大，里面那颗黑点提醒你：能退一步，就别硬扛。" },

      { t: "h", s: "二、讼卦讲什么：争讼，但最好不争" },
      { t: "p", s: "讼卦的卦辞是：「有孚，窒，惕，中吉，终凶。利见大人，不利涉大川。」" },
      { t: "p", s: "翻译一下：你心里确实有道理（有孚），但争起来就会憋屈、路被堵死（窒）；所以得时刻警惕（惕），中途若妥善化解还能小吉（中吉），可要是硬拼到底，一定两败俱伤（终凶）。" },
      { t: "p", s: "曾仕强爷爷把讼卦读得最透。他说：讼卦的中心思想，是研究「不要诉讼」。孔子也讲「必也使无讼乎」——我宁可法官领工资没案子办，也不愿你家打官司。" },
      { t: "p", s: "讼卦还有一句超实用的提醒：「君子以作事谋始」。做任何事，一开始就先把规矩、边界说清楚，能避免九成的纠纷。" },
      { t: "p", s: "还有「利见大人」：真闹起来了，别自己硬杠，去找一个公正的长辈、老师来调解，比两个人吵强百倍。「不利涉大川」则说：这时候别再搞大动作、别冒险强争，先止血再说。" },

      { t: "h", s: "三、生活案例：跟同学闹别扭，怎么用讼卦" },
      { t: "case", title: "他凭什么不理我？", s: "假设你借给同桌一支笔，他弄丢了还嘴硬不认，你俩当场就要吵起来。用讼卦的思路：第一，别恋战（初六「不永所事」）——刚起口角，先把火压下去，及时闭嘴反而吉祥，硬吵只会越闹越凶。第二，能退则退（九二「不克讼，归而逋」）——如果理在你、但对方人多势众或正上头，先退一步保全自己，不算怂，叫「识时务」。第三，找大人调解（「利见大人」）——让班主任或一个俩人都服的同学来评理，比你们各说各话强。第四，最重要的，「作事谋始」——下次借东西前先说好「弄丢了要赔」，规则写在前头，纠纷根本不会发生。曾仕强说：争讼没有赢家，就算你嘴上赢了，也输了关系。退一步，海阔天空。" },

      { t: "h", s: "四、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住讼卦", items: [
        "画面法：默念「天水讼」三个字——天往上、水往下，背道而驰就是讼；跟需卦（云在天上等）放一起想，一个等、一个闹，差一个字，差十万八千里。",
        "中心句：讼卦的中心是「不讼」，记住孔子的话「必也使无讼乎」——最好不打官司，退一步比争到底聪明。",
        "预防法：记住「作事谋始」——做任何事先把规矩、边界说清，能防住九成纠纷；真闹起来就「利见大人」，找公正长辈调解，别自己硬扛。"
      ]},
      { t: "p", s: "曾仕强说：一个巴掌拍不响。凡是会吵起来的，两边都有不对。所以别急着证明「我对你错」，先想想怎么把事化解掉——这才是讼卦教你的真本事。" },

      { t: "quiz", questions: [
        { type: "choice", q: "讼卦的卦象「天水讼」是怎么叠出来的？", options: ["上乾（天）下坎（水）", "上坎（水）下乾（天）", "上坤下艮", "上艮下坎"], answer: 0, explain: "讼卦上卦是乾（天）、下卦是坎（水），天往上、水往下，背道而驰，所以叫天水讼。" },
        { type: "choice", q: "曾仕强说讼卦的中心思想是什么？", options: ["教你怎么打赢官司", "研究不要诉讼，最好化解矛盾、不讼", "教你怎么跟人吵架", "讼卦专门用来算财运"], answer: 1, explain: "讼卦中心是「不讼」：孔子讲必也使无讼乎，曾仕强说争讼没有赢家，退一步比争到底聪明。" },
        { type: "choice", q: "「君子以作事谋始」对避免吵架的我们，意思是？", options: ["等吵起来再说", "做任何事先把规矩边界说清，从源头防住纠纷", "先动手再说", "找人帮忙吵架"], answer: 1, explain: "作事谋始：一开始就把规则写清楚，能避免九成纠纷；真闹起来再「利见大人」找长辈调解。" },
        { type: "say", q: "请用「最好不讼」说说你最近一次跟人闹别扭（同学、家人都行）：当时你是怎么处理的？如果重来一次，你会怎么用讼卦退一步、或一开始就「谋始」定好规矩？", model: "比如上周我和妹妹抢遥控器，我硬要换台，她哭着告状，我俩吵了半小时（这叫讼，两败俱伤）。如果重来，我会先「作事谋始」——抢之前就说好「一人看十分钟、轮流换台」，规则写在前头，根本吵不起来。真闹起来我也该学初六「不永所事」，先闭嘴降温，再找妈妈（利见大人）当裁判，而不是非要证明我对。退一步，姐弟关系比赢那一下重要多了。" }
      ]}
    ]
  },
  {
    id: 8,
    title: "第8课 · 师卦：地水师与怎么带好一个团队",
    subtitle: "曾仕强说：师忧比乐，带团队就是带人心",
    review: "上节课我们认识了讼卦——天水讼。天一个劲儿往上升、水一个劲儿往低处流，背道而驰、各说各话，就像两个人吵起来谁也劝不住；于是老祖宗说「天与水违行，讼」。讼卦的中心思想是「不讼」——曾仕强爷爷说争讼没有赢家，孔子也讲「必也使无讼乎」，最好化解矛盾、退一步比争到底聪明。它还教我们两招：一是「作事谋始」，做任何事先把规矩边界说清，能防住九成纠纷；二是「利见大人」，真闹起来了别自己硬扛，找公正的长辈调解。讼卦还跟第5课的需卦互为综卦——需要等待，闹起来就讼。今天，顺着《序卦传》「讼必有众起，故受之以师」，我们来到第七卦——师卦。当口舌之争化解不了、矛盾升级，众人就要站队、形成一股组织力量，这就叫「师」。所以这节课，我们专门讲一件事：怎么带好一个团队、当一个让人服气的领头人。",
    blocks: [
      { t: "h", s: "一、师卦长啥样：水伏在大地底下" },
      { t: "p", s: "上节课的讼卦是天水讼（上乾下坎），天往上、水往下，背道而驰。今天的师卦，水换到了下面、上面换成了地，叫「地水师」。它是六十四卦里的第7卦。" },
      { t: "p", s: "师卦的画法是：上面三爻是坤（地），下面三爻是坎（水），合起来就是地水师。" },
      { t: "p", s: "你想象一下：水本来该到处流，这会儿却乖乖伏在大地底下，像蓄在池塘里——平时看不见、积蓄着力量，关键时刻一涌而出。这就是「师」的画面：一股藏在底下、随时能调动的力量。" },
      { t: "p", s: "为什么讼卦之后是师卦？《序卦传》说得好：「讼必有众起，故受之以师。师者，众也。」吵来吵去化解不了，两边就开始拉人站队，矛盾从「两个人的嘴仗」升级成「一群人的行动」。" },
      { t: "p", s: "曾仕强说：冲突调解不了，必然升级为动用组织力量——这就是师卦。所以「师」=「众」=「兵」，原本指军队；但他一再强调，师卦不是教你爱打仗，而是教你领导的艺术、怎么把一群人组织起来办成事。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上坤（妈妈）下坎（二儿子）叠成地水师。水（坎，兵众）藏在大地（坤，包容）底下蓄势待发，正像领导平时「容民畜众」、把人心蓄养好，真要干事时一呼百应。它也呼应了第1课那「一家八口」：乾爸爸坤妈妈生的儿子们，自己也能叠出新卦来。" },
      { t: "p", s: "记住这张八卦图：上坤（妈妈）下坎（二儿子）叠成地水师。水（坎，兵众）藏在大地（坤，包容）底下蓄势待发，正像领导平时把人心蓄养好，真要干事时一呼百应。" },

      { t: "h", s: "二、师卦讲什么：守正、纪律、用对人" },
      { t: "p", s: "师卦的卦辞只有几个字：「师，贞，丈人吉，无咎。」" },
      { t: "p", s: "头一个字「贞」，是说师出有名、守住正道。你带人干的事得正当、名正言顺，大家才肯跟你走。曾仕强说：师唯一的原则就是贞——你是「师」（带头的人），自己不正，跟着你的人全受害。" },
      { t: "p", s: "「丈人」两个字最妙：不是派个年轻气盛、爱逞能的小伙子去带头，而是用老成持重、德高望重的统帅。经验加德行，缺一不可。" },
      { t: "p", s: "只要「贞」和「丈人」同时到位，即便动用了组织力量，也能「无咎」——不至于出大乱子。" },
      { t: "p", s: "师卦还有一句大象传，点出领导的日常功夫：「地中有水，师；君子以容民畜众。」平时广施恩德、把人才蓄养好，战时才能一呼百应。曾仕强把它用到现代组织：领导平日要注重培养、关怀下属，得人心，团队才有凝聚力。" },
      { t: "p", s: "师卦六条爻，把「带团队」拆成六句大白话，从下往上读是：师出以律、在师中、舆尸、左次、长子帅师、小人勿用。" },
      { t: "p", s: "初六，师出以律，否臧凶：军队一出发，纪律必须先行；纪律松散，必败。曾仕强讲过一个故事：古代将领出征前必严申军纪，违者立斩——听着狠，正是这纪律把乌合之众炼成铁军。纪律不是枷锁，是团队的氧气。" },
      { t: "p", s: "九二，在师中，吉无咎；王三锡命：主帅守在中道、严格执行纪律，君王还三次授权给他（财权、人事权、指挥权）。意思是：用对人就充分信任、把权放够，别掣肘。" },
      { t: "p", s: "六三，师或舆尸，凶：把不对的人放错位置，结果用车运尸体回来——用人不当，必大凶。" },
      { t: "p", s: "六四，师左次，无咎：打不过就主动后撤、休整保存实力，不算输，叫「识时务」。这点跟讼卦「不永所事」一个道理：该退就退。" },
      { t: "p", s: "六五，田有禽，利执言；长子帅师，弟子舆尸，贞凶：让「长子」（正牌、靠谱的统帅）挂帅就吉；让「弟子」（资历浅、靠关系的）代庖就凶。一句话：用对人，成败天壤之别。" },
      { t: "p", s: "上六，大君有命，开国承家，小人勿用：仗打完了论功行赏、分封功臣；但有功却品德差的小人，绝不可委以重任——否则后患无穷。曾仕强提醒：小人勿用，是师卦给所有领导人的最后一道红线。" },

      { t: "h", s: "三、生活案例：当组长，怎么用师卦" },
      { t: "case", title: "我当组长，怎么带人？", s: "假设老师让你当小组长，带五个人做项目。用师卦的思路就顺了：第一，师出以律——组队第一天先把规矩立住（谁负责哪块、周几交、迟到怎么办），纪律先行，别等乱了再骂。第二，丈人——你自己别逞能独断，也别任用只会拍马屁、不干活的人；挑靠谱、稳重的组员挑大梁。第三，九二充分授权——分给别人的活就信任他、给够权限，别天天盯着 micromanage，让人家发挥。第四，六五用对人——让会写的人写、会讲的人讲，别乱点将把活儿塞给不擅长的人（那会「舆尸」）。第五，上六小人勿用——谁有功但爱拆台、抢功、人品差，别给重要位置。曾仕强说得好：带团队不是管人，是带人心。你把规矩立住、把人用对、平时多关心组员，大家自然服你、愿意跟你干。" },

      { t: "h", s: "四、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住师卦", items: [
        "画面法：默念「地水师」三个字——水伏在地的底下蓄势待发，像蓄水池；平时把人心蓄养好（容民畜众），要用时一涌而出，比死背卦画好记。",
        "中心句：师卦核心是「贞+丈人」——师出有名（正）、用老成靠谱的人带、纪律先行；记住「师忧比乐」，带团队是责任、是忧患，不是享福。",
        "纪律法：记住「师出以律」先把规矩立住，再记「小人勿用」——有功无德也绝不给大权；这两句，够你当个让人服气的领头人。"
      ]},
      { t: "p", s: "曾仕强说：师忧比乐。师卦讲的是攻坚、是责任、是忧患；真正的领袖，以正道驭众、以德服人、以心换心。" },

      { t: "quiz", questions: [
        { type: "choice", q: "师卦的卦象「地水师」是怎么叠出来的？", options: ["上坤（地）下坎（水）", "上坎（水）下坤（地）", "上乾下坤", "上艮下坎"], answer: 0, explain: "师卦上卦是坤（地）、下卦是坎（水），地中有水象征水伏地底蓄势待发，也是民众力量汇聚成「众」。" },
        { type: "choice", q: "卦辞「师，贞，丈人吉」里，「丈人」指的是？", options: ["年轻气盛、爱逞能的猛将", "老成持重、德高望重的统帅", "随便拉一个人顶上", "敌人派来的奸细"], answer: 1, explain: "丈人=经验加德行兼备的老成统帅；用血气方刚的小年轻带团队，容易「舆尸」出大事。" },
        { type: "choice", q: "「师出以律，否臧凶」对带小组的我们，最重要的提醒是？", options: ["不用管纪律，随意就行", "一出兵纪律先行，纪律松散必败", "纪律是老板压榨人的工具", "有本事的人不需要规矩"], answer: 1, explain: "师出以律：团队一开始就把规矩立住，无纪律就是一盘散沙；纪律不是枷锁，是团队的氧气。" },
        { type: "say", q: "请用「师出以律」和「用对人」说说你最近一次当领头人（小组作业、班级活动、甚至带弟妹都行）：你立规矩了吗？把活分给对人了吗？下次重来，你会怎么用师卦改进？", model: "比如上次做手抄报我当组长，没先立规矩，结果两人都以为对方写文字，最后漏了一块（这就是没「师出以律」）。用人上我把画画塞给了一个不擅长画画的同学，他熬到半夜还画砸了（差点「舆尸」）。下次我会第一天就说清分工和截止时间（立律），再按特长分配——让字好的写字、画好的画画（用对人），还把拍马屁却不出活的组员只安排打杂、不委重任（小人勿用）。规矩立住、人用对，团队自然顺。" }
      ]}
    ]
  },
  {
    id: 9,
    title: "第9课 · 比卦：水地比与怎么选对伙伴",
    subtitle: "曾仕强说：师忧比乐，平时团结比战时硬扛聪明",
    review: "上节课我们认识了师卦——地水师。水乖乖伏在大地底下蓄势待发，像蓄水池一样，平时把人心蓄养好、真要干事一呼百应；于是老祖宗说「地中有水，师；君子以容民畜众」。师卦的中心是「贞+丈人」——师出有名（正）、用老成靠谱的人带、纪律先行（师出以律），还教我们两招带人：用对人（别「舆尸」）、小人勿用（有功无德也绝不给大权）。最后我们还记住了曾仕强那句「师忧比乐」——带团队是责任、是忧患，不是享福。今天，顺着《序卦传》「讼必有众起，故受之以师；师者众也，众必有所比，故受之以比」，我们来到第八卦——比卦。当一群人组织起来之后，接下来最重要的事就是：怎么亲比、怎么团结、怎么选对要跟随的人。所以这节课，我们专门讲一件事：怎么跟对人、跟对团队。",
    blocks: [
      { t: "h", s: "一、比卦长啥样：水贴着大地流" },
      { t: "p", s: "上节课的师卦是地水师（上坤下坎），水在地下憋着。今天的比卦反过来——上面三爻是坎（水），下面三爻是坤（地），叫「水地比」。它是六十四卦里的第8卦。" },
      { t: "p", s: "你想象一下：地上有水，水贴着大地、顺着地势流，水离不开地、地也纳着水——这不就是亲近、依靠的样子吗？" },
      { t: "p", s: "老祖宗说：这就像一群人亲亲密密靠在一起，你帮我、我帮你，谁也离不开谁。这个画面，就叫「比」，也就是亲比、亲近、团结。" },
      { t: "p", s: "比卦的大象传写得最暖：「地上有水，比；先王以建万国，亲诸侯。」先王看了就懂：把大家亲近地团结起来，分封诸侯、守望相助。" },
      { t: "p", s: "它跟上一课的师卦，正好是「综卦」——把师卦上下一翻，就变成比卦。曾仕强说这俩字最能概括区别：「师忧比乐」。" },
      { t: "p", s: "师卦是地中有水，水憋在地下、凝聚得紧，那是打仗时的硬团结（非常时期，大家一条心）；比卦是地上有水，水在地上流、有弹性，那是平时的软团结（志同道合就靠近，话不投机就疏远）。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上坎（二儿子）下坤（妈妈）叠成水地比。水（坎）亲亲密密贴着大地（坤）流，正像一群人互相依靠、谁也离不开谁。它也呼应了第1课那「一家八口」：乾爸爸坤妈妈生的儿子们，自己也能叠出新卦来。" },
      { t: "p", s: "记住这张八卦图：上坎（二儿子）下坤（妈妈）叠成水地比。水（坎）贴着大地（坤）流，正像一群人互相依靠、谁也离不开谁。" },

      { t: "h", s: "二、比卦讲什么：亲比、团结，但得选对人" },
      { t: "p", s: "比卦的卦辞只有几个字：「吉。原筮，元永贞，无咎。不宁方来，后夫凶。」" },
      { t: "p", s: "翻译一下：亲比（团结）是吉祥的；你重新掂量掂量（原筮），只要长久守正（元永贞），就没毛病（无咎）。" },
      { t: "p", s: "「不宁方来，后夫凶」是说：心里不安、主动靠拢过来的人，是好的；可别人都团结好了、你磨磨蹭蹭最后才来（后夫），那就凶——掉队的人，往往最吃亏。" },
      { t: "p", s: "「比」这个字，本义就是亲比、亲近。古代五家人住在一起叫「一比」，所以咱们说「比邻而居」，就是为了互相照应、守望相助。" },
      { t: "p", s: "比卦的样子很特别：五条阴爻、中间一条阳爻（九五），像是全队人一致拥护一个好领袖。但曾仕强提醒：亲比不是谁都跟，得「择善而依附」——选对人才跟。" },
      { t: "p", s: "他讲得最透的一句话是：在中国，只有先把人处好，才能把事情做好。西方人讲「对事不对人」，咱们是以人为中心——事在人为，人处不好，事准砸。" },
      { t: "p", s: "所以整个比卦，都在讲「人跟人的关系」：怎么选对人亲比、怎么让人愿意亲比你。" },

      { t: "h", s: "三、比卦六条线：跟谁亲、怎么跟" },
      { t: "p", s: "比卦六条爻，把「怎么亲比、选谁亲比」拆成六句话，从下往上读是：有孚比之、比之自内、比之匪人、外比之、显比、比之无首。" },
      { t: "p", s: "初六，有孚比之，无咎：靠近一个人、团结在谁身边，最基本的原则是「孚」——发乎内心的真诚。" },
      { t: "p", s: "一个人是真心愿意跟你，你赶都赶不走；你用合同、用规定、用好处去绑，都绑不住。所以真诚，才没有后遗症。" },
      { t: "p", s: "六二，比之自内，贞吉：从自己内部（下卦）出发，衷心拥护你认准的那个领头人；但别被人当枪使、别轻易被挑拨——搞清楚了再表忠心。" },
      { t: "p", s: "六三，比之匪人：最要命的一句——你亲比（交心）给了一个不仁不义的人，选错了对象，注定倒霉。所以下卦先教你：慎选亲比的对象。" },
      { t: "p", s: "六四，外比之，贞吉：不只内部，还要主动去亲附外面（上卦）那位好领导，忠心追随，这样也吉祥。" },
      { t: "p", s: "九五，显比，王用三驱，失前禽：最高明的一句——光明正大地亲比；打个比方，君王打猎只用三面围、放开一面，主动跑掉的禽兽就放它走。" },
      { t: "p", s: "意思是：好的领袖不强求、不硬绑，愿意跟的欢迎、想走的随它去，这叫「以德服人」而不是「以力压人」。" },
      { t: "p", s: "上六，比之无首，凶：亲比来亲比去，却没个核心、没个领头（群龙无首），那就凶——一群人没主心骨，准散架。" },

      { t: "h", s: "四、生活案例：怎么用比卦选朋友、选小组" },
      { t: "case", title: "我该跟谁玩？", s: "假设你刚转学，想找个能一起玩、一起学习的圈子。用比卦的思路就对了：第一，有孚——对人真诚，你真心待人，别人才真愿意靠近你（赶都赶不走）。第二，慎选对象（六三比之匪人）——别为了合群，去跟总逃课、欺负人的「匪人」混，选错人准倒霉；看谁正派、上进，再去亲比。第三，比之自内——先把自己这头的本分做好（学习、礼貌），再衷心融入好团队，别被人当枪使。第四，看领头人（九五显比）——一个小组组长要是「王用三驱」、包容不强求、以德服人，就值得跟；要是专横硬压，趁早换。曾仕强说：在中国，把人处好才能把事做好。用比卦选对伙伴，你不仅玩得开心，学习也有人帮——这就是「比，吉也」。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住比卦", items: [
        "画面法：默念「水地比」三个字——水贴着大地流、谁也离不开谁，就是亲比团结的样子，比死背卦画好记。",
        "中心句：比卦核心是「择善依附」——选对人再跟、真诚（有孚）去靠近，别像六三「比之匪人」选错对象。",
        "乐忧法：记住「师忧比乐」——师是战时硬团结（忧、责任），比是平时软团结（乐、亲附）；想团结人，平时多亲比、别等出事才硬凑。"
      ]},
      { t: "p", s: "曾仕强说：天时不如地利，地利不如人和。一个团队、一个班级，只要人跟人处好了、亲比和谐了，什么事都好办。" },

      { t: "quiz", questions: [
        { type: "choice", q: "比卦的卦象「水地比」是怎么叠出来的？", options: ["上坎（水）下坤（地）", "上坤（地）下坎（水）", "上乾下坤", "上艮下坎"], answer: 0, explain: "比卦上卦是坎（水）、下卦是坤（地），地上有水、水亲地而流，象征亲比团结；把师卦上下一翻就是比卦。" },
        { type: "choice", q: "曾仕强说亲比要「择善而依附」，六三爻辞「比之匪人」提醒我们什么？", options: ["要跟所有人亲近", "亲比了不仁不义的人、选错对象会倒霉，要慎选", "越凶的人越要跟", "不要跟任何人来往"], answer: 1, explain: "比之匪人=交心给不仁不义的人、选错对象必倒霉；比卦先教人慎选亲比的对象，不是谁都跟。" },
        { type: "choice", q: "九五「显比，王用三驱，失前禽」给当领头人的我们，最重要的提醒是？", options: ["用规矩硬绑住每个人", "以德服人、不强求，愿意跟的欢迎、想走的随它去", "把想走的人抓回来", "谁不听话就赶走"], answer: 1, explain: "王用三驱=打猎三面围、开一面，放走主动跑的；比喻好领袖不强求、不硬绑，以德服人而非以力压人。" },
        { type: "say", q: "请用「择善依附」和「有孚比之」说说你最近一次选朋友或选小组：你选对人了吗？你是真诚靠近别人的，还是凑合混日子？如果重来，你会怎么用比卦选对伙伴？", model: "比如上学期我为了不落单，跟几个总逃课、说脏话的同学混（这就有点「比之匪人」——选错了对象）。我也不是真心想学他们，只是凑合，结果成绩掉了、还被老师找。如果重来，我会先「有孚」——用真诚待人，再去亲比那些正派、上进的同学（择善依附）；看谁爱学习、守规矩，再主动靠近。一个小组长要是「王用三驱」、包容不强求，我就愿意跟。把比卦用上，我既能交到真朋友，学习也有伴，这才叫「比，吉也」。" }
      ]}
    ]
  },
  {
    id: 10,
    title: "第10课 · 小畜卦：风行天上，一点点攒出大本事",
    subtitle: "曾仕强说：积小成大，别急于求成",
    review: "上节课我们认识了比卦——水地比。水贴着大地流、谁也离不开谁，就是亲比团结；于是老祖宗说「地上有水，比」。《序卦传》讲「师者众也，众必有所比，故受之以比」，比卦跟师卦是综卦，曾仕强用「师忧比乐」一句话点透：师是战时硬团结（忧、责任），比是平时软团结（乐、亲附）。比卦还教我们「有孚比之」——靠真诚去靠近人，别像六三「比之匪人」选错对象，也教领头人「显比，王用三驱」、以德服人不强求。我们还记住：在中国，把人处好才能把事做好。今天，顺着《序卦传》「比必有所畜，故受之以小畜」，我们来到第九卦——小畜卦。比卦讲完怎么跟对人、团结好伙伴，接下来最重要的事就是：把这一群人的力量，一点一滴攒起来、蓄起来。所以这节课，我们专门讲一件事：怎么积小成大、厚积薄发。",
    blocks: [
      { t: "h", s: "一、小畜长啥样：风在天上跑，云聚了还没下雨" },
      { t: "p", s: "上节课的比卦是水地比（上坎下坤）。今天的小畜卦，上面换成了巽（风），下面还是乾（天），叫「风天小畜」。它是六十四卦里的第9卦。" },
      { t: "p", s: "你抬头看天：风呼呼地在天上吹，云一层层聚起来，可雨还没落下来。这个「云聚雨未落」的画面，就是小畜。" },
      { t: "p", s: "老祖宗说：这就像你攒东西的阶段——力气、本事、钱、人脉，都还在一点点往里蓄，还没到「满出来、能大用」的时候。" },
      { t: "p", s: "「畜」这个字，在这里读音同「蓄」，就是蓄养、积累的意思。小畜，就是「小小的积蓄」。" },
      { t: "p", s: "曾仕强爷爷讲：小畜卦最妙的地方，是它告诉你——别急，先攒着。云还不够厚，硬要下雨，下不下来；人还不够强，硬要干大事，干不成。" },
      { t: "diagram", key: "taiji", caption: "这是太极图：小畜卦六条线里有五条是阳爻（满满的努力），只有中间那一条是阴爻（一点点克制）。就像这张太极图——白鱼（阳，你的干劲）很大，但里面那颗黑点（阴，懂得节制、不冒进）虽小，却最要紧。没有那一点克制，干劲太猛反而翻车。所以小畜的真谛：满腔热血里，留一小份冷静。" },
      { t: "p", s: "记住这张太极图的道理：小畜卦五阳夹一阴，就像白鱼里那颗小小的黑点——努力要够多，但那一点「懂得等、懂得收」的克制，反而让你走得更远。" },

      { t: "h", s: "二、小畜讲什么：积小成大，懿文德" },
      { t: "p", s: "小畜的卦辞只有几个字：「亨。密云不雨，自我西郊。」" },
      { t: "p", s: "「亨」是说：只要你老老实实攒，路子是通的；「密云不雨」是画面——云密密地聚在西边的郊外，可雨还没下，意思是：积蓄阶段，力量还不够大，急不得。" },
      { t: "p", s: "小畜的大象传写得最暖：「风行天上，小畜；君子以懿文德。」「懿」是美好，「文德」是你内在的品德和本事。" },
      { t: "p", s: "翻译过来：风在天上吹、雨还没落，君子就趁这时候，悄悄把内在的修养、本事攒厚——等云厚了，自然下雨；等本事够了，自然成事。" },
      { t: "p", s: "曾仕强说：现在很多人太着急，恨不得今天学明天就变现。小畜卦偏要你反着来——该「畜」（蓄）的时候，就安心畜，别急于求成、别冒进。" },
      { t: "p", s: "他还讲过一个生活化的道理：你每天存一块钱、背五个单词、练十分钟字，看着不起眼，可一年下来就是365块、1825个词、600小时——这就是「小畜」的力量：积小成大。" },
      { t: "p", s: "所以小畜不是「小气」，是「小小的、持续的积累」。" },

      { t: "h", s: "三、小畜六条线：怎么一点点攒，又不翻车" },
      { t: "p", s: "小畜六条爻，把「怎么积蓄、别冒进」拆成六句话，从下往上读是：复自道、牵复、舆说辐、有孚血去、富以其邻、既雨既处。" },
      { t: "p", s: "初九，复自道，何其咎：回到你自己的正道上，一点点来、走正路，哪会有毛病？→ 攒东西，先从「走正路、做对的事」开始。" },
      { t: "p", s: "九二，牵复，吉：有人拉着你、你也拉着他，一起回到正道，互相带动，比一个人攒更好。→ 找个同伴一起攒，比如和同学约好每天背单词。" },
      { t: "p", s: "九三，舆说辐：这是一句警告。车子跑太快，辐条（连接轮轴的细木条）都震脱了，车散架。→ 想一下子冲太猛、急于求成，反而前功尽弃，别冒进。" },
      { t: "p", s: "六四，有孚，血去惕出：凭着真诚、再保持警惕，就能避开伤害、化险为夷。→ 积蓄阶段也容易被人骗、被透支，真诚加小心最稳。" },
      { t: "p", s: "九五，富以其邻：自己攒富了（有积蓄、有本事），也带着邻居一起富。→ 自己进步了，拉同伴一把，大家好才是好。" },
      { t: "p", s: "上九，既雨既处：雨终于下了，该停就停。→ 积蓄够了就行动、也该收手，别贪多、别停不下来。" },

      { t: "h", s: "四、生活案例：怎么用「小畜」攒出英语听力" },
      { t: "case", title: "我英语烂，怎么逆袭？", s: "假设你英语听力很差，想半年内追上。用小畜卦的思路就对了：第一，复自道——别想着报个神奇速成班一步登天，先回到正道：每天老老实实听15分钟、背10个词，走正路。第二，牵复——拉个同学组队，互相打卡、谁偷懒另一个督促，比孤军奋战稳。第三，最要命的舆说辐——别一上来就每天听3小时、逼自己泛听精听全上，结果两周就倦怠放弃，车散架。小畜教你「密云不雨」：慢慢蓄，别猛冲。第四，有孚血去——找资源别轻信「保过」广告，警惕骗局。第五，富以其邻——你听力上来了，把方法分享给队友。第六，既雨既处——水平够了就转去练口语，别囤一堆课永不毕业。曾仕强说：积小成大，别急于求成。把小畜用上，半年后你回头一看，早就不是当初那个听不懂的你。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住小畜卦", items: [
        "画面法：默念「风天小畜」四个字——风在天上吹、云聚雨未落，就是「还在攒、急不得」的样子，比死背卦画好记。",
        "中心句：小畜核心是「积小成大、懿文德」——每天存一点、修养内功，云厚了自然下雨，别急于求成。",
        "警示法：记住「舆说辐」——车跑太快辐条会脱、事干太猛会垮；想冲太猛时，先停下想一想，这就是小畜给你的刹车。"
      ]},
      { t: "p", s: "曾仕强说：人生就像小畜卦，大部分时候都在「蓄」——蓄本事、蓄人品、蓄人脉。蓄得足，才有后面的「既雨既处」，该你施展时，一展就成。" },

      { t: "quiz", questions: [
        { type: "choice", q: "小畜卦的卦象「风天小畜」是怎么叠出来的？", options: ["上巽（风）下乾（天）", "上乾下巽", "上坤下乾", "上坎下坤"], answer: 0, explain: "小畜上卦巽（风）、下卦乾（天），风行天上、密云不雨，是小小的积蓄阶段。" },
        { type: "choice", q: "卦辞「密云不雨」和「君子以懿文德」想告诉我们什么？", options: ["雨快下了赶紧跑", "积蓄阶段力量还不够，先悄悄修养内功、积小成大", "别存钱", "风太大要躲起来"], answer: 1, explain: "云聚雨未落＝还在蓄；懿文德＝趁这时修养品德本事，等积蓄够了自然成事，别急于求成。" },
        { type: "choice", q: "九三「舆说辐」对想速成的我们，最重要的提醒是？", options: ["车越快越好", "急于冒进反而前功尽弃（车散架），要循序渐进", "别坐车", "辐条越多越厉害"], answer: 1, explain: "舆说辐＝车子跑太快辐条震脱、散架，比喻急于求成、猛冲会翻车；小畜教你慢慢蓄。" },
        { type: "say", q: "请用「积小成大」说说你最近在攒的一件事（背单词、存零钱、练字都行）：你每天攒多少？打算怎么避免「舆说辐」式的急于求成？", model: "比如我最近在攒零钱买一本喜欢的书，每天往罐子里放5块，一个月就有150。我用小畜的思路：不急着一次性问爸妈要钱买（那会「舆说辐」式地爽完就没了），而是慢慢蓄，同时把数学错题本也每天整理两道（懿文德——攒真本事）。等攒够了，书也买了、错题也清了，这就是积小成大。想冲太猛时我就提醒自己：密云不雨，云厚了自然下。" }
      ]}
    ]
  },
  {
    id: 11,
    title: "第11课 · 履卦：天泽履与怎么在规矩里走好路",
    subtitle: "曾仕强说：履卦是处世第一关，踩着老虎尾巴也能不被咬",
    review: "上节课我们认识了小畜卦——风天小畜。风在天上吹、云一层层聚起来可雨还没落下来，就像你攒东西的阶段——力气、本事、钱、人脉还在一点点往里蓄，没到『满出来、能大用』的时候；于是老祖宗说『密云不雨』。小畜卦教我们『积小成大、懿文德』——每天存一点、修养内功，别急于求成，也给了我们一句刹车警句『舆说辐』（车跑太快辐条震脱、散架）。我们还记住『既雨既处』——积蓄够了就行动、也该收手。最后顺着《序卦传》『物畜然后有礼，故受之以履』——东西攒够了，接下来就要懂『礼』（分寸、规矩、怎么跟人相处）。所以今天，我们来到第十卦——履卦。它专门讲一件事：攒够了本事，怎么在规矩和礼法之下，踏踏实实把路走稳、走好。",
    blocks: [
      { t: "h", s: "一、履卦长啥样：天在上，泽在下" },
      { t: "p", s: "上节课的小畜是风天小畜（上巽下乾）。今天的履卦，上面还是乾（天），下面换成了兑（泽），叫「天泽履」。它是六十四卦里的第10卦。" },
      { t: "p", s: "你抬头看天，高高在上、刚健有力；低头看脚下，是沼泽、湖泊，平和又喜悦。天在上、泽在下，位阶清清楚楚，谁也不僭越，这就是「履」的画面。" },
      { t: "p", s: "「履」这个字，本义就是鞋子、走路——穿鞋踩在地上走，引申为「践行、履行、处世的步子」。" },
      { t: "p", s: "小畜卦是「攒」的阶段（云还没下雨），履卦就是「走」的阶段（攒够了，该下地迈步了）。" },
      { t: "p", s: "老祖宗给履卦写了句大象传：「上天下泽，履；君子以辨上下，定民志。」翻译过来：看天在上、泽在下，君子就明白要先辨明上下尊卑、把规矩定清楚，大家才安心走路。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上乾（爸爸）下兑（小女儿）叠成天泽履。天（乾，刚健）高高在上，泽（兑，和悦）安安静静在底下，位阶分明、各安其位，正像一家人——爸爸撑起家、小女儿和悦相处，谁也不抢谁的位置。它也呼应了第1课那「一家八口」：乾爸爸坤妈妈生的儿女们，自己也能叠出新卦来。" },
      { t: "p", s: "记住这张八卦图：上乾（爸爸）下兑（小女儿）叠成天泽履。天在上、泽在下，秩序清楚，正像你走路要先看清哪儿是道、哪儿是沟。" },

      { t: "h", s: "二、履卦讲什么：礼，和踩老虎尾巴而不被咬" },
      { t: "p", s: "履卦的卦辞只有六个字，却吓人又好记：「履虎尾，不咥人，亨。」" },
      { t: "p", s: "字面意思：你跟在老虎屁股后头走，不小心踩到了它的尾巴；可老虎没回头咬你，最后还亨通。听着荒唐，其实是老祖宗最妙的一句比喻。" },
      { t: "p", s: "「虎」是谁？是比你强的人、你的上司、规矩、甚至整个环境里的危险。你躲不开、又必须靠近（就像伴君如伴虎），那就得踩准节奏、用对方法。" },
      { t: "p", s: "曾仕强爷爷把履卦叫做「处世第一关」。他说：履，通「礼」。你攒够了本事（小畜），接下来能不能走得顺，全看你懂不懂「礼」——这个礼，不是客套话，是分寸、是规矩、是跟人相处最优的距离。" },
      { t: "p", s: "履卦最深的智慧叫「履危而安」：你像走在薄冰上、像踩着虎尾，处处是险，但因为你小心合礼，反而平平安安。" },
      { t: "p", s: "所以方法是「以柔克刚」——内心保持和悦（兑），对外行动刚健守正（乾），外柔内刚，老虎就不咬你。曾仕强还特别提醒「过犹不及」：履卦不是叫你胆小到啥也不敢做、啥也不敢说，缩成宅男；太小心会丧失生存能力。该历练还得历练，在礼的圈子里走，就是安全的。" },

      { t: "h", s: "三、履卦六条线：踩虎尾的六个步子" },
      { t: "p", s: "履卦六条爻，把「怎么在险境里走稳」拆成六句，从下往上读是：素履、履道坦坦、眇能视跛能履、履虎尾愬愬、夬履、视履考祥。" },
      { t: "p", s: "初九，素履，往无咎：穿一双朴素干净的鞋走路，低调、本分，不炫技不越位，就没什么毛病。→ 刚进新环境，先踏实把基本流程踩熟，别急着显摆。" },
      { t: "p", s: "九二，履道坦坦，幽人贞吉：走在正道上，哪怕暂时不得志（像隐居的幽人），也终归吉祥。→ 守规矩、不抄近道，短期慢点，长远走得稳。" },
      { t: "p", s: "六三，眇能视，跛能履，履虎尾咥人，凶：眼睛半瞎还偏要看、腿瘸了还偏要走路，结果踩到虎尾被咬——凶。→ 本事不够、位置太高还硬逞能，必翻车。" },
      { t: "p", s: "九四，履虎尾，愬愬终吉：身处险地（跟在老虎后），心里战战兢兢、满怀敬畏（愬愬），反而化险为夷、终吉。→ 夹在中间时谨慎请示、随时汇报，稳稳过关。" },
      { t: "p", s: "九五，夬履，贞厉：果敢决断地走，虽然走得正，但仍有危险，要兼听。→ 你说了算时别刚愎自用，留条反馈通道。" },
      { t: "p", s: "上九，视履考祥，其旋元吉：事后回看脚步（视履）、总结经验（考祥）、再回头调整（其旋），大吉。→ 干完一件事做复盘，踩过的坑写成经验，下次更顺。" },

      { t: "h", s: "四、生活案例：怎么用履卦当一个「懂事」的新人" },
      { t: "case", title: "我刚转学，怎么不踩雷？", s: "假设你刚转学，新环境里全是「虎」（陌生老师、厉害同学、新规矩）。用履卦的思路就对了：第一，素履——先低调，把基本流程弄熟，别一上来就抢风头（初九）。第二，履道坦坦——走正道，不抄作业、不投机，短期成绩慢点但稳（九二）。第三，最要命的六三——别逞能：明明没把握的比赛别硬揽，不然像跛子走路一样翻车。第四，履虎尾愬愬——跟班主任（你的「虎」）打交道，尊重但不谄媚、有事及时汇报，心怀敬畏反而平安（九四）。第五，夬履——当了班干部要果断，但多听同学意见，别一言堂（九五）。第六，视履考祥——期末回头看看这半年哪儿踩对了、哪儿踩坑了，记下来（上九）。曾仕强说：礼是人际最优的距离。用履卦找准自己的位置、守好分寸，你这个新人不但不被「咬」，还走得踏实又亨通。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住履卦", items: [
        "画面法：默念「天泽履」三个字——天高高在上、泽安安静静在下，位阶分明就是履；再联想「穿鞋走路」，比死背卦画好记。",
        "核心句：履卦核心是「礼」——记住卦辞「履虎尾，不咥人，亨」：踩着老虎尾巴（处处有险），只要合礼守分寸，老虎不咬你、路也通。",
        "慎行法：记住「素履+愬愬」——刚进场低调本分（素履）、身处险地心怀敬畏（愬愬终吉）；再记「过犹不及」，别小心到啥都不敢做。"
      ]},
      { t: "p", s: "曾仕强说：履卦是「实践天道」。你攒的每一分本事（小畜），最后都要靠一步一步、合礼守分的「履」，才能真正走成你的人生。" },

      { t: "quiz", questions: [
        { type: "choice", q: "履卦的卦象「天泽履」是怎么叠出来的？", options: ["上乾（天）下兑（泽）", "上兑（泽）下乾（天）", "上坤下乾", "上巽下乾"], answer: 0, explain: "履卦上卦是乾（天）、下卦是兑（泽），天在上泽在下、位阶分明，所以叫天泽履。" },
        { type: "choice", q: "卦辞「履虎尾，不咥人，亨」里的「虎」，比喻的是什么？", options: ["你的宠物猫", "比你强的人、上司、规矩、环境里的危险", "一只真老虎", "考试成绩"], answer: 1, explain: "履卦的虎指你躲不开又必须靠近的强者、上司、规矩或危险；踩准节奏、合礼守分寸，老虎就不咬你，终能亨通。" },
        { type: "choice", q: "六三「眇能视，跛能履，履虎尾咥人，凶」给爱逞能的我们，最重要的是什么提醒？", options: ["越逞能越厉害", "本事不够还硬踩高位必翻车（凶），要先辨位、别越位", "腿瘸也要多走路", "老虎喜欢被踩尾巴"], answer: 1, explain: "六三说眼瞎腿瘸还偏逞能，踩虎尾被咬——比喻能力不足却居高位乱来必凶；履卦教你先认清自己的位置，别越位逞强。" },
        { type: "say", q: "请用「履虎尾，不咥人」说说你最近一次处在新环境、或面对比你强的人的经历：你是怎么「合礼守分寸、不被咬」的？如果重来，你会怎么用履卦的「素履」和「愬愬（敬畏）」做得更好？", model: "比如上学期我刚进校队，队长（我的「虎」）又严又厉害。我一开始想表现，抢着提建议，结果被怼了（有点「跛能履」逞能）。如果重来，我会先「素履」——低调把基本动作练熟、不抢风头；跟队长沟通时「愬愬」——心怀敬畏、有事先请示、做错了马上改，而不是硬顶。礼是人际最优距离，守好分寸，队长反而愿意带我，我在队里也走得踏实。这就是「履虎尾，不咥人，亨」。" }
      ]}
    ]
  }
  ,
  {
    id: 12,
    title: "第12课 · 泰卦：地天泰与怎么把顺境变长久",
    subtitle: "曾仕强说：泰极否来，处泰虑否才留得住太平",
    review: "上节课我们认识了履卦——天泽履。天高高在上、泽安安静静在下，位阶分明就是『履』；卦辞说『履虎尾，不咥人，亨』——你躲不开又必须靠近的强者、上司、规矩（那头『虎』），只要合礼守分寸，老虎就不咬你、路也通。履卦还教我们六条线：素履（低调本分）、履道坦坦（走正道）、眇能视跛能履（别逞能）、履虎尾愬愬（身处险地心怀敬畏）、夬履（当断则断但要兼听）、视履考祥（事后复盘）。最后我们还记住『过犹不及』——别小心到啥都不敢做。顺着《序卦传》『履而泰，然后安，故受之以泰』，今天，我们来到第11卦——泰卦。它专门讲一件事：人守好礼、走稳路之后，怎么迎来并守住一段『通达安泰』的好时光。",
    blocks: [
      { t: "h", s: "一、泰卦长啥样：天跑到了地的底下" },
      { t: "p", s: "上节课的履卦是天泽履（上乾下兑）。今天的泰卦，上面换成了坤（地），下面还是乾（天），叫『地天泰』。它是六十四卦里的第11卦。" },
      { t: "p", s: "你抬头看，天本该高高在上；可这个卦偏偏反着来——天跑到下面、地升到上面。" },
      { t: "p", s: "老祖宗说：天之气本来要往下降，地之气本来要往上升。地在上、天在下，刚好让天之气往下、地之气往上，上下一通气，万物就通泰了。" },
      { t: "p", s: "这叫『天地交泰』——天地之气交合，生机勃勃，什么都能长、什么都顺。" },
      { t: "p", s: "《序卦传》讲得透：『履而泰，然后安。』你按礼（履）去行事，就能通达，进而平安，于是有了泰卦。丰衣足食、社会安定，就是泰。" },
      { t: "diagram", key: "taiji", caption: "这是太极图：泰卦六条线里，下面三根是阳爻、上面三根是阴爻。就像这张太极图——白鱼（阳，君子的能量）从底下往上生，黑鱼（阴，柔顺的环境）在上面往下降，阴阳上下交合、循环往复，正是『天地交泰』的画面。白里有黑点、黑里有白点，提醒你：通泰里也藏着变坏的因子，顺境别忘形。" },
      { t: "p", s: "记住这张太极图的道理：泰卦下面三根阳、上面三根阴，就像白鱼从下往上、黑鱼从上往下，阴阳一交合就通泰——可白里藏黑点，提醒你顺境里也藏着转机变坏的可能。" },

      { t: "h", s: "二、泰卦讲什么：通达，但别得意忘形" },
      { t: "p", s: "泰卦的卦辞只有六个字：『泰，小往大来，吉，亨。』" },
      { t: "p", s: "『小往大来』是说：小的（付出、阴）往前走，大的（收获、阳）回来——付出小、收获大，这就是『泰』的核心体感。" },
      { t: "p", s: "但『吉、亨』有个大前提：天地交。上下得沟通、内外得循环。曾仕强爷爷把『泰』读成一个字——『通』。" },
      { t: "p", s: "他说：通泰是要『通』才能『泰』，平安是要『平』才会『安』。缺了沟通、交换、循环这三步，泰就悄悄转成否（坏卦）。" },
      { t: "p", s: "泰卦的大象传写得最有担当：『天地交，泰；后以财成天地之道，辅相天地之宜，以左右民。』" },
      { t: "p", s: "翻译过来：领导者（后）用资源、制度去成就天道，顺势补齐短板，让整个系统自己转起来、让大家共享安乐。独乐乐，不如众乐乐。" },
      { t: "p", s: "曾仕强还说：我们拜年说的『三阳开泰』，就出自这里——三个阳爻（初九、九二、九三）在下头，代表这么多君子要同心协力，开出天下太平的局面。" },
      { t: "p", s: "但他立刻补一句最要命的提醒：由泰入否，只是一瞬间，太容易了。所以泰卦最深的智慧叫『泰极否来』——顺到极点，就要警惕变坏，这叫『处泰虑否』。" },

      { t: "h", s: "三、泰卦六条线：从『拔茅茹』到『城复于隍』" },
      { t: "p", s: "泰卦六条爻，把『怎么迎来并守住一段好时光』拆成六句，从下往上读是：拔茅茹、包荒、无平不陂、翩翩、帝乙归妹、城复于隍。" },
      { t: "p", s: "初九，拔茅茹，以其汇，征吉：拔一根茅草，连根带整丛都拔出来——因为它们根系连在一起。比喻志同道合的人要像茅草一样同心协力；这时主动行动，大吉。曾仕强说：君子别标榜自己，要不失己任、同心协力。" },
      { t: "p", s: "九二，包荒，用冯河，不遐遗，朋亡，得尚于中行：胸怀要宽（包容各色人，连有勇无谋的也用），不遗漏远处的、也不结党营私（朋亡），就能得中道之助。曾仕强提醒：朋亡=别拉小团体搞内斗，君子一内斗就变小人。" },
      { t: "p", s: "九三，无平不陂，无往不复，艰贞无咎：没有永远的平地（总有坡），没有只去不回（循环往复）。曾仕强讲得最狠：无平不陂=世上只有『合理的不公平』，别老求绝对公平；无往不复=你得意时千万别松懈，否则泰马上变否。保持艰难中的正道（艰贞），才无咎。" },
      { t: "p", s: "六四，翩翩，不富以其邻，不戒以孚：连原本对立的小人，看到这股向上的正气，都像小鸟一样飞下来主动靠近，不靠掠夺邻居、以诚信服人。曾仕强说：真诚能把人对面感化过来。" },
      { t: "p", s: "六五，帝乙归妹，以祉元吉：高层（帝乙）把妹妹嫁出去联姻，巩固联盟、福祉共享，大吉。曾仕强讲：给曾经走歪的人一条『逆取顺守』的路，选贤举人，大家才好。" },
      { t: "p", s: "上六，城复于隍，勿用师，自邑告命：城墙倒塌、护城河淤塞，象征泰极否来、盛极而衰；这时别动武硬来（勿用师），要回根据地发新政、自我革新（自邑告命）。曾仕强说：守成不易，君子的责任只有四个字——修己安人。" },

      { t: "h", s: "四、生活案例：怎么用泰卦守住一段好日子" },
      { t: "case", title: "我考好了、朋友也处得顺，怎么留住？", s: "假设你最近考试顺了、和新朋友也处得特别好，正处在一团『泰』里。用泰卦的思路就对了：第一，拔茅茹——把志同道合的朋友拉一个小圈，同心协力搞学习，别单打独斗（初九）。第二，包荒——包容朋友的小缺点，别一有摩擦就绝交；也别拉小团体排挤别人（朋亡）（九二）。第三，无平不陂——别以为会一直顺，成绩好时更谦虚、提早留后路，别得意忘形（九三）。第四，不戒以孚——对曾经闹别扭的同学，用真诚慢慢感化他，别硬杠（六四）。第五，城复于隍——发现这段好关系开始冷淡（盛极而衰的信号），别急着吵架（勿用师），而是主动约一次活动、发条诚恳的信息去挽回（自邑告命）。曾仕强说：处泰虑否。顺境里就想着怎么守住，太平才留得久。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住泰卦", items: [
        "画面法：默念『地天泰』三个字——天跑到地底下、上下通气，就是通达安泰；联想『天地交泰』，比死背卦画好记。",
        "核心句：泰卦核心是『通』——卦辞『小往大来，吉亨』：付出小、收获大，上下沟通才通泰；记住『三阳开泰』，是君子同心开太平。",
        "警句法：记住『泰极否来』+『处泰虑否』——顺境最容易一瞬间变坏，得意时更要警惕、留后路，别松懈。"
      ]},
      { t: "p", s: "曾仕强说：通泰是要『通』才能『泰』，平安是要『平』才会『安』。你把每一天都沟通好了、把人处顺了，好日子才留得住。" },

      { t: "quiz", questions: [
        { type: "choice", q: "泰卦的卦象『地天泰』是怎么叠出来的？", options: ["上坤（地）下乾（天）", "上乾（天）下坤（地）", "上乾下兑", "上坎下坤"], answer: 0, explain: "泰卦上卦是坤（地）、下卦是乾（天），天在下地在上，天地之气上下交合，所以叫地天泰。" },
        { type: "choice", q: "卦辞『小往大来，吉，亨』里，『泰』的核心体感是什么？", options: ["付出小、收获大", "什么都不用做", "越大越好", "越小越好"], answer: 0, explain: "泰=通：小（付出）前往、大（收获）回来，付出小收获大；但前提是天地交（上下沟通、内外循环）。" },
        { type: "choice", q: "上六『城复于隍，勿用师』给处在顺境顶点的我们，最重要的提醒是？", options: ["赶紧动武扩张", "泰极否来、盛极而衰时别硬扛动武，应回归本心自我革新（处泰虑否）", "什么都不管", "把墙拆了"], answer: 1, explain: "城墙倒回护城沟，象征盛极而衰；勿用师=别动武硬来，自邑告命=回归本心发新政自我革新。曾仕强提醒处泰虑否。" },
        { type: "say", q: "请用『处泰虑否』说说你最近一段顺心的日子（考好了、交到好朋友、某个项目顺利都行）：你当时有没有警惕『顺境会变』？如果重来，你会怎么用泰卦『拔茅茹（拉志同道合的人）』和『无往不复（留后路、别松懈）』把这段好状态守住更久？", model: "比如上学期我和小A、小B组了学习搭子，期中考试三人全进前二十，正是一段『泰』。可我当时太飘，觉得会一直顺，还因为一点小事跟小B闹别扭、没去挽回（没用『城复于隍』的挽回），结果期末他们俩合伙进步、我却掉了。如果重来，我会用『拔茅茹』——把搭子圈拉得更紧、定期互相打气；用『无往不复』——提醒自己顺境会反转，成绩好时更谦虚、提前补弱科留后路。处泰虑否，把好日子主动守下去，而不是等它溜走才后悔。" }
      ]}
    ]
  }
  ,
  {
    id: 13,
    title: "第13课 · 否卦：天地否与怎么在逆境里沉住气",
    subtitle: "曾仕强说：否极泰来，坏到极点转机就来了",
    review: "上节课我们认识了泰卦——地天泰。天本该高高在上，这卦却让天跑到地底下、地升到天上头，上下一通气，万物通泰；于是老祖宗说『天地交泰』。《序卦传》讲『履而泰，然后安』，你按礼（履）行事就能通达平安。泰卦教我们『小往大来，吉亨』——付出小、收获大；还给了我们六条线：拔茅茹（同心协力）、包荒（包容不结党）、无平不陂（没有永远的平地，得意别松懈）、翩翩（以诚感化）、帝乙归妹（逆取顺守）、城复于隍（盛极而衰，别动武，回归本心自我革新）。最重要的是曾仕强那句『泰极否来，处泰虑否』——顺到极点就要警惕变坏。今天，顺着《序卦传》『物不可以终通，故受之以否』，我们来到第12卦——否卦。它正好是泰卦的镜子：泰是把天翻到地下换来通，否是让天回到天上、各走各路，变成闭塞不通。所以这节课，我们专门讲一件事：当一段好日子走到头、处处不顺的时候，怎么在逆境里沉住气、熬到转机。",
    blocks: [
      { t: "h", s: "一、否卦长啥样：天回到了天上，地回到了地下" },
      { t: "p", s: "上节课的泰卦是地天泰（上坤下乾）。今天的否卦，天回到了上面、地回到了下面，叫『天地否』。它是六十四卦里的第12卦。" },
      { t: "p", s: "你抬头看，天本来就在上、还一个劲儿往上飘；低头看，地本来就在下、还一个劲儿往下沉。天之气往上、地之气往下，各走各的路、谁也不理谁。" },
      { t: "p", s: "这就跟泰卦反过来了。泰卦是天在下、地在上，上下一交合就通泰；否卦是天在上、地在下，上下一隔开，气就不通了——这个『不通』，就叫否（pǐ）。" },
      { t: "p", s: "老祖宗说：天地不交，万物就不生长；上情下不达、下情上不通，整个系统就卡住了。所以否卦象征的，是一段『闭塞、不顺、小人得势』的逆境。" },
      { t: "p", s: "曾仕强爷爷还特别讲过一个字谜：『否』这个字，上面一个『不』，下面一张『口』——我有嘴巴，想讲一句话，但想一想还是不讲，这就叫否。" },
      { t: "p", s: "中国人跟外国人不一样，不是想讲就讲，会先想『你听不听得进去』『讲了有没有用』『讲了会不会伤关系』；发现讲不通，干脆就不讲了。下情上不去、上令下不达，就是否。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上乾（爸爸）下坤（妈妈）叠成天地否。天（乾）高高在上、地（坤）安安静静在下，跟泰卦刚好调了个个儿——泰是坤在上、乾在下（天地交），否是乾在上、坤在下（天地不交）。它也呼应了第1课那『一家八口』：乾爸爸坤妈妈上下一换位置，就从通泰变成了闭塞。" },
      { t: "p", s: "记住这张八卦图：上乾（爸爸）下坤（妈妈）叠成天地否。乾回到天上、坤回到地下，上下不交、气不通，正像你走路踩进了一段处处不顺的逆境。" },

      { t: "h", s: "二、否卦讲什么：闭塞，但你得沉住气" },
      { t: "p", s: "否卦的卦辞是：『否之匪人，不利君子贞，大往小来。』" },
      { t: "p", s: "『大往小来』正好是泰卦『小往大来』的反面：大的（收获、阳）往外走，小的（付出、阴）往里来——付出大、收获小，这就是『否』的体感。" },
      { t: "p", s: "但『不利君子贞』不是叫你别守正道，而是说：在这么闭塞的环境里，你越想堂堂正正往前冲，越容易碰壁。曾仕强说：否卦跟泰卦是『错卦又是综卦』——把否卦上下一翻（交卦），就变成泰卦。否中有泰、泰中有否，几乎分不开。" },
      { t: "p", s: "否卦的大象传写得最警醒：『天地不交，否；君子以俭德辟难，不可荣以禄。』" },
      { t: "p", s: "翻译过来：天地不交、闭塞不通的时候，君子要把自己的才华和德行『收起来』（俭德），用来躲避灾祸；这时候如果有人给你高官厚禄，千万别接——因为那多半是拉你下水、利用你。" },
      { t: "p", s: "『俭德』不是生活上省钱，而是收敛、隐藏。把你的理想、锋芒、本事暂时收一收，不显山不露水，免得被小人嫉妒、被环境针对。这是一种高级的自我保护。" },
      { t: "p", s: "曾仕强说：处否的关键，就一个字——忍。忍不是认怂，是『以退为进』：宁可变糊涂、装笨，不自守不出头，等时机。" },

      { t: "h", s: "三、否卦六条线：从『退守』到『否极泰来』" },
      { t: "p", s: "否卦六条爻，把『怎么熬过一段闭塞期』拆成六句，从下往上读是：拔茅茹、包承、包羞、有命、休否、倾否。" },
      { t: "p", s: "初六，拔茅茹，以其汇，贞吉，亨：跟泰卦初九一样也是拔茅草连根起，说明不管保泰还是去否，都得同心协力。但处境不同——泰卦是大家同心往上冲，否卦是大家同心『往下退守』：不争名利、不求表现，宁装糊涂。方向要对（贞），才吉亨。" },
      { t: "p", s: "六二，包承，小人吉，大人否，亨：小人去包容、奉承上面的人，这对小人吉利；君子（大人）却要坦然接受这个闭塞的现实（否亨），不同流合污，内心照样亨通。→ 别人巴结逢迎你别眼红，守住自己。" },
      { t: "p", s: "六三，包羞：小人得势却德不配位，迟早自取其辱（包羞）。→ 君子这时候更要明哲保身，看着他们胡闹，知道他们迟早翻车，自己千万别掺和。" },
      { t: "p", s: "九四，有命，无咎，畴离祉：转机来了！『有命』是天命、时机到了。这时可以行动了，但要顺应规律（有命）、联合志同道合的人（畴离祉）一起努力，才能无咎、接近福佑。→ 熬到拐点，别一个人蛮干，拉伙伴。" },
      { t: "p", s: "九五，休否，大人吉。其亡其亡，系于苞桑：否塞将要停止（休否），君子大展宏图的时机到了；但『其亡其亡，系于苞桑』=时刻警惕会不会灭亡，像系在苞桑（坚韧的根）上一样，危而不倾。→ 转机来了也别飘，居安思危。" },
      { t: "p", s: "上九，倾否，先否后喜：把否运彻底倾覆，先经历闭塞、后迎来欢喜——这就是『否极泰来』。→ 坏到极点，转机就来了。" },

      { t: "h", s: "四、生活案例：怎么用否卦熬过一段低谷" },
      { t: "case", title: "我成绩掉了、朋友也疏远了，怎么办？", s: "假设你这学期成绩掉了一截、连最好的朋友也因为误会疏远了你，正处在一团『否』里。用否卦的思路就对了：第一，拔茅茹——别急着一个人硬扛，找一两个真心朋友（或家人）同心退守、互相打气，不争风头（初六）。第二，包承、包羞——看着那些爱显摆、拉帮结派的同学，你别眼红也别去巴结逢迎，更别同流合污；他们德不配位迟早翻车，你守好自己的本分（六二、六三）。第三，俭德辟难——这时候别到处张扬、别抢着出风头，把锋芒收一收、低调把弱科补起来，避开无谓的麻烦（大象传）。第四，有命——等到期末复习节奏对了、误会解开（时机到），再联合朋友一起冲，别蛮干（九四）。第五，倾否——熬过这段，关系回暖、成绩回升，先否后喜（上九）。曾仕强说：否极泰来。逆境里沉住气、守住正道、低调修身，转机一来，你就又通泰了。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住否卦", items: [
        "画面法：默念『天地否』三个字——天回到天上、地回到地下，上下不交就是否；跟泰卦（地天泰）放一起想，一个交、一个不交，差一个字差一个世界。",
        "核心句：否卦核心是『俭德辟难』——逆境里把才华锋芒收起来躲避灾祸，有人给好处也别接（不可荣以禄）；记住『否中有泰』，坏里藏着转机。",
        "盼头法：记住『倾否，先否后喜』——否极泰来，坏到极点转机就来了；像泰卦『处泰虑否』反过来，逆境里更要沉住气、别放弃。"
      ]},
      { t: "p", s: "曾仕强说：顺境之后必有逆境，这是天理。处否不是认输，是『以退为进』——把这一段闭塞期，变成你修身蓄力的好时候。" },

      { t: "quiz", questions: [
        { type: "choice", q: "否卦的卦象『天地否』是怎么叠出来的？", options: ["上乾（天）下坤（地）", "上坤（地）下乾（天）", "上乾下兑", "上坎下坤"], answer: 0, explain: "否卦上卦乾（天）、下卦坤（地），天往上地往下、上下不交，所以叫天地否；把泰卦上下一翻就得到否卦。" },
        { type: "choice", q: "大象传『君子以俭德辟难，不可荣以禄』给身处逆境的我们，意思是？", options: ["生活上省钱过日子", "收敛才华锋芒躲避灾祸、逆境里有人给好处也别轻易接", "赶紧去争高官厚禄", "什么都不管等死"], answer: 1, explain: "俭德=收敛隐藏，不是省钱；处闭塞期要把本事收一收避祸，此时送上门的荣华多是陷阱，所以不可荣以禄。" },
        { type: "choice", q: "上九『倾否，先否后喜』和『否极泰来』给我们最大的提醒是？", options: ["坏会一直坏下去", "坏到极点转机就来了，逆境里要沉住气守正道", "顺境才要小心", "不用努力转机也会来"], answer: 1, explain: "倾否=倾覆否运，先经历闭塞后迎来欢喜；否极泰来提醒逆境里沉住气、守正待机，转机自然会来。" },
        { type: "say", q: "请用『俭德辟难』和『否极泰来』说说你最近一段不顺的日子（考砸、吵架、被误会都行）：当时你是怎么『收敛、低调、不硬扛』的？如果重来，你会怎么用否卦沉住气、等转机？", model: "比如上个月我和小B因为误会闹翻，那阵子干啥都不顺（一团『否』）。我当时有点想去找别的圈子巴结、证明自己，结果更尴尬。如果重来，我会用『俭德辟难』——不急着表现、不硬扛、把锋芒收一收，先低调把误会冷一冷；同时『拔茅茹』找一两个真朋友吐吐槽、稳住心态。相信『否极泰来』，不放弃、不硬碰，等误会解开（有命，时机到）再主动跟小B说开。逆境里沉住气、守好本分，转机一来，关系又通泰了。" }
      ]}
    ]
  },
  {
    id: 14,
    title: "第14课 · 同人卦：天火同人，打破孤立与人同心",
    subtitle: "曾仕强说：走出小我，求同存异，才是天下大同",
    review: "上节课我们认识了否卦——天地否。天高高在上、地安安静静在下，上下不交、气不通，就是一段处处不顺的逆境；于是老祖宗说『天地不交，否』。《序卦传》讲『物不可以终通，故受之以否』，顺到极点就要警惕变坏。否卦教我们『俭德辟难，不可荣以禄』——逆境里把才华锋芒收起来躲避灾祸，有人给好处也别轻易接；还给了我们六条线：拔茅茹（同心退守）、包承（不同流合污）、包羞（明哲保身）、有命（转机联合志士）、休否（居安思危）、倾否（先否后喜·否极泰来）。最重要的是曾仕强那句『否中有泰、以退为进』——坏到极点转机就来了。今天，顺着《序卦传》『物不可以终否，故受之以同人』，我们来到第13卦——同人卦。否卦是天地不交、人人各自孤立；同人卦正好要打破这种孤立：当你在逆境里憋久了，自然会想——与其一个人硬扛，不如走出门去，跟别人同心同德、一起把事做成。所以这节课，我们专门讲一件事：怎么走出小我，与人和同。",
    blocks: [
      { t: "h", s: "一、同人长啥样：天在上、火在下，火苗往上跟天一个方向" },
      { t: "p", s: "上节课的否卦是天地否（上乾下坤）。今天的同人卦，上面是乾（天），下面换成了离（火），叫『天火同人』。它是六十四卦里的第13卦。" },
      { t: "p", s: "你抬头看天：天高高在上、无边无际、没有私心；低头看火：火苗总是往上窜、往光明处走。天和火，一个在上一个在下，可它们的『心』是朝同一个方向的——都往外、往上、向着光明。" },
      { t: "p", s: "老祖宗说：天的无私，加上火的向上，两股劲儿合到一块儿，就叫『同人』。『同人』就是——跟别人同心同德、和和睦睦一起干。" },
      { t: "p", s: "乾是刚健（天天往上走、不停歇），离是光明（火把黑暗照亮）；刚健加光明，像一群人既有干劲又有方向，自然能齐心。" },
      { t: "p", s: "曾仕强爷爷讲：同人卦最关键的一点，是火苗虽小，但它『同于天』——不跟天争高低，而是顺着天的方向一起往上。人也是一样：不老想着压过别人，而是跟大家同一个目标，这就叫同人。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上乾（爸爸）下离（二女儿）叠成天火同人。乾爸爸高高在上、没有私心；离二女儿举着火把往上照。火苗的方向跟天一样——都朝上、都向外。它也呼应了第1课那『一家八口』：乾爸爸和离二女儿一上一下，火顺着天，就是『同人』。你再把第13课的否卦（上乾下坤、天地不交）摆旁边一比：否是天地各走各路、谁也不理谁；同人是天火同心、一起向上——一个孤立闭塞，一个团结向上，差的就是『同』这一个字。" },
      { t: "p", s: "记住这张八卦图：上乾（爸爸）下离（二女儿）叠成天火同人。火苗顺着天的方向往上，正像你走出小我、跟别人拧成一股绳的样子。" },

      { t: "h", s: "二、同人讲什么：走出小我，与天下人同心" },
      { t: "p", s: "同人卦的卦辞是：『同人于野，亨。利涉大川，利君子贞。』" },
      { t: "p", s: "『同人于野』的『野』，是旷野、野外——没有围墙、没有亲疏远近的分别。意思是：在公开、没有私心的地方跟人和同，才亨通。曾仕强说：同人不是在家里完成的（家里那是家人卦），你在家靠亲情，出了门就得靠『公心』。" },
      { t: "p", s: "『利涉大川』是说：同心的人能一起渡过大江大河——也就是能合力干成大事、闯过难关。『利君子贞』是说：这种同心，对守正道的君子最有利。" },
      { t: "p", s: "同人的大象传写得最开阔：『天与火，同人；君子以类族辨物。』天和火都向上向外，君子看了就懂：物以类聚、人以群分，要把不同的人按类别看清楚（类族辨物），求同存异、彼此包容。" },
      { t: "p", s: "曾仕强讲过一个核心道理：同人不是要大家都一模一样——那既不可能，也没必要。人和人成长环境、想法都不一样，所以我们的方向是『求同存异，大同而小异』。" },
      { t: "p", s: "孔子早就提出『世界大同』的理想，用现在的话说就是地球村。同人卦就是大同世界的雏形：大家尽量朝同一个目标努力，由近及远、由亲到疏，一步步把一视同仁推广出去。" },
      { t: "p", s: "曾仕强还点破一句最实在的话：『唯君子为能通天下之志』——只有把成见放下、把私人恩怨摆一边、多为公共利益着想的人（君子），才能真正把大家团结起来。" },

      { t: "h", s: "三、同人六条线：从『出门』到『大同』" },
      { t: "p", s: "同人六条爻，把『怎么从一个人，变成一群同心人』拆成六句，从下往上读是：同人于门、同人于宗、伏戎于莽、乘其墉、先号咷而后笑、同人于郊。" },
      { t: "p", s: "初九，同人于门，无咎：门是家跟外面的交界。你走出家门，主动去跟外人打交道、化私为公，就不会有麻烦。曾仕强说：出门同人第一件事，就是把『私心』换成『公心』——为了大家好而出面，不是去走亲戚拉关系。" },
      { t: "p", s: "六二，同人于宗，吝：只跟同宗族、小圈子的人同心，太狭隘，会留下遗憾。→ 别搞小团体、别任人唯亲；跟一小撮人抱团，反而招麻烦；跟天下人同心才亨通。" },
      { t: "p", s: "九三，伏戎于莽，升其高陵，三岁不兴：因为跟别人不同心，就埋伏在草丛里、登高偷偷窥探，三年都不敢动。→ 心胸狭隘、老跟人对着干，反而把自己困死，寸步难行。" },
      { t: "p", s: "九四，乘其墉，弗克攻，吉：你登上城墙、占尽上风，本来能攻下去，却克制住没攻——吉。→ 起冲突、想翻脸时，能忍住、不撕破脸，化敌为友，反而得吉。" },
      { t: "p", s: "九五，同人，先号咷而后笑，大师克相遇：求同心的路上先大哭一场、后来放声大笑，大军终于会师。→ 同心不是一帆风顺，要经历误会、磨合（先哭后笑），熬过去才真正团结成大事。" },
      { t: "p", s: "上九，同人于郊，无悔：在郊野与人和同，虽没到『天下大同』那么圆满，但也不后悔。→ 求同不必强求完全一致，求大同、存小异，各让一步，就已经很好。" },

      { t: "h", s: "四、生活案例：怎么用同人卦搞定小组作业" },
      { t: "case", title: "小组作业大家不合，怎么拧成一股绳？", s: "假设老师分了四人小组做PPT，可你们四个谁也不服谁：有人想偷懒、有人爱抢功、有人闷头不说话，正卡在一团『否』里。用同人卦的思路就对了：第一，同人于门——别各干各的，先开个会、把门打开，大家把想法摊开说（初九）。第二，千万别同人于宗——别只拉跟你好的那一个组小圈子排挤别人，那样小组必散（六二）。第三，类族辨物——看清每个人特长：谁PPT厉害、谁资料找得全、谁口才好，按特长分工，求同存异（大象传）。第四，乘其墉弗克攻——有人偷懒或唱反调，你火大了也别当众撕破脸，先忍住、私下沟通，化敌为友（九四）。第五，先号咷而后笑——磨合期肯定吵架、想放弃（先哭），但熬过几次、分工顺了，最后演示成功大家一起笑（九五）。曾仕强说：走出小我、求同存异，才能万众一心。用同人卦带小组，你不是去当官，是去把大家的目标拧成一股绳——这，才是真正的领导力。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住同人卦", items: [
        "画面法：默念『天火同人』四个字——天高高在上、火苗往上窜，两股劲儿朝一个方向，就是『同心』；跟否卦（天地各走各路）放一起想，一个孤、一个同，差一个字差一个世界。",
        "核心句：同人核心是『同人于野·求同存异』——走出小我、化私为公，不要求大家都一样，能同的尽量同、不同的彼此包容，由近及远推广到大同。",
        "行动法：记住初九『同人于门』和九四『乘其墉弗克攻』——先敞开门主动靠近别人，起冲突时忍住不翻脸、化敌为友；这就是把『同人』从口号变成每天的行动。"
      ]},
      { t: "p", s: "曾仕强说：同人卦是『大同世界的雏形』。你每主动靠近一个不一样的人、每忍住一次争吵去沟通，就是在亲手铺一块通往天下大同的砖。" },

      { t: "quiz", questions: [
        { type: "choice", q: "同人卦的卦象『天火同人』是怎么叠出来的？", options: ["上乾（天）下离（火）", "上离下乾", "上乾下坤", "上坎下离"], answer: 0, explain: "同人上卦乾（天）、下卦离（火），天无私、火向上，两股劲儿同朝一个方向，所以叫天火同人。" },
        { type: "choice", q: "卦辞『同人于野，亨』和『君子以类族辨物』想告诉我们什么？", options: ["只在家里跟亲人同心", "走出小我、在公开无私处与人和同，求同存异、彼此包容", "要让大家完全一样", "火大了要躲开"], answer: 1, explain: "于野＝在旷野无私处与人和同才亨通；类族辨物＝分辨类别、求同存异彼此包容，由近及远推广到大同。" },
        { type: "choice", q: "九四『乘其墉，弗克攻，吉』给起冲突的我们，最重要的提醒是？", options: ["占上风就狠狠攻下去", "忍住不翻脸、化敌为友反而得吉", "赶紧逃跑", "城墙越高越好"], answer: 1, explain: "乘其墉弗克攻＝登城占上风却克制不攻，吉；比喻冲突时能忍住、不撕破脸、化敌为友，才是同人智慧。" },
        { type: "say", q: "请用『同人于门』和『求同存异』说说你最近一次跟人闹别扭（同学、队友、家人都行）：当时你是怎么『关起门来自己人玩』或『非要别人跟你一样』的？如果重来，你会怎么用同人卦走出小我、跟大家同心？", model: "比如上周我跟小C组队做手抄报，我嫌他字丑想把他踢了、只拉跟我好的小D（这就是『同人于宗』——搞小圈子）。结果小C赌气不干，进度卡住。如果重来，我会用『同人于门』——先敞开门，把三个人的活摊开分：我排版、小C画插图（他画画其实不差）、小D写字，各用所长（类族辨物）。他画法跟我想的不一样，我也不强行改（求同存异），最后成品反而更丰富。同人卦教会我：走出小我、不要求一模一样，把大家拧成一股绳，事才成。" }
      ]}
    ]
  },
  {
    id: 15,
    title: "第15课 · 大有卦：火天大有，同人之后大获所有",
    subtitle: "曾仕强说：为富要仁，富而有礼、富而能仁",
    review: "上节课我们认识了同人卦——天火同人。上面是乾（天）、下面是离（火），天无私、火向上，两股劲儿朝同一个方向，就是『与人同心』。卦辞『同人于野，亨』教我们走出小我、在公开无私的地方与人和同；大象传『君子以类族辨物』教我们分辨类别、求同存异；六爻给我们六句：同人于门（敞开门化私为公）、同人于宗（搞小圈子则吝）、伏戎于莽（心胸狭隘困死自己）、乘其墉弗克攻（冲突时忍住化敌为友）、先号咷而后笑（磨合后才团结）、同人于郊（求大同存小异）。最重要的是曾仕强那句『唯君子为能通天下之志』——放下成见、多为公益着想，才能把大家拧成一股绳。今天，顺着《序卦传》『与人同者，物必归焉，故受之以大有』，我们来到第14卦——大有卦。同人是『与人同心』，大有的人是『同心之后，大获所有』：你跟人一条心，资源、财富、名望自然都汇聚到你这儿。所以这节课，我们专门讲一件事：有了大收获之后，怎么接得住、守得稳。",
    blocks: [
      { t: "h", s: "一、大有长啥样：火在天上，离（火）在上、乾（天）在下" },
      { t: "p", s: "上节课的同人卦是天火同人（上乾下离）。今天的卦把上下调了个头：上面换成离（火），下面还是乾（天），叫『火天大有』。它是六十四卦里的第14卦。" },
      { t: "p", s: "你抬头看：天上挂着一轮烈日（离就是火），光芒普照大地，没有一片角落照不到——火在天上，就是『大有』的画面：光明充足、万物丰足。" },
      { t: "p", s: "老祖宗说：离是光明（把黑暗照亮），乾是刚健（天天向上、不停歇）；火的光明，照在天的刚健之上，一片辉煌、什么都丰盛，就叫大有。" },
      { t: "p", s: "曾仕强爷爷讲：大有就是『大拥、大获』——大丰收、大拥有。它是继同人之后的自然结果：你先跟人同心（同人），大家齐心协力，资源、财富、人脉自然向你汇聚，这就成了大有。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上离（二女儿）下乾（爸爸）叠成火天大有。离二女儿举着火把高高举到天上，乾爸爸刚健打底。火在天上，普照万物，就是大有。它呼应第1课那『一家八口』：离二女儿和乾爸爸一上一下。你再把上节课的同人卦（上乾下离、天火同人）摆旁边一比：同人是火在底下、天在上头——火苗顺着天往上，是『与人同心』；大有的火跑到了天顶上——光芒铺天盖地，是『同心之后大获所有』。一个同人、一个大有，上下一翻就是一家人。" },
      { t: "p", s: "记住这张八卦图：上离（二女儿）下乾（爸爸）叠成火天大有。火举到天上、光芒四射，正像你跟人同心之后，收获滚滚而来的样子。" },

      { t: "h", s: "二、为什么同人之后是大有：先聚人，后成事" },
      { t: "p", s: "《序卦传》把话说得很透：『与人同者，物必归焉，故受之以大有。』你找到志同道合的人（同人），大家一条心，东西、机会、名望就都归到你这儿了，所以同人之后紧跟着大有。" },
      { t: "p", s: "曾仕强点得更明白：先聚人，后成事；人找对了，钱自然来。你一个人本事再大，也大不过一群同心人。" },
      { t: "p", s: "大有卦的卦辞只有两个字：『元亨。』元是源头正道，亨是持续畅通。曾仕强提醒：真正的大丰收，必须源正、路正，否则来得快、去得更快。" },
      { t: "p", s: "彖传讲得更细：六五（唯一的阴爻）以柔顺之德坐在最尊贵的君位上，上下五条阳爻都来呼应它——一个柔的人，为什么能拥有五个刚强者？靠的是诚信和胸怀：你信得过人，人才愿意跟你；你容得下人，人才愿意帮你。" },
      { t: "p", s: "所以大有不是『我一个人抢来的』，是『大家同心、把好处都托付给你』的结果。" },

      { t: "h", s: "三、大有教我们什么：为富要仁（遏恶扬善，顺天休命）" },
      { t: "p", s: "大象传给了最有名的一句：『火在天上，大有；君子以遏恶扬善，顺天休命。』" },
      { t: "p", s: "『遏恶扬善』——收获期最怕蛀虫：你钱多了、势大了，心里的恶念会跟着冒出来（以前没能力做坏事，现在有了）。所以要遏制恶念、发扬善良。扬善不是到处吹牛，是力所能及帮别人一把。" },
      { t: "p", s: "『顺天休命』——休是美好，命是使命。顺着天理良心，完成人这一辈子『人之所以为人』的美好使命，而不是读了易经只想自己得好处。" },
      { t: "p", s: "曾仕强说：真正的大有需要两个条件——『富而有礼』和『富而能仁』。穷的时候对人客气容易，富了容易目中无人（富而无礼）；富了还能把别人当人、把多出来的分享出去（富而能仁），这才叫福慧双全。" },
      { t: "p", s: "他还说：小富是你自己赚的，可以不分享；大富很多是老天给的，老天只是通过你之手分给大家——你不分，老天就让你遭殃。没有钱的人不分享不遭殃，有钱人不分享一定遭殃。" },

      { t: "h", s: "四、大有六条线：从『不惹祸』到『天来帮』" },
      { t: "p", s: "大有六条爻，把『有了大收获之后怎么办』拆成六句，从下往上读是：无交害、大车以载、公用亨于天子、匪其彭、厥孚交如、自天祐之。" },
      { t: "p", s: "初九，无交害，匪咎，艰则无咎：刚有点收获、根基还没稳，别急着跟人攀关系、卷进是非；更要『艰则无咎』——记住当初艰难的日子，居安思危，才不会招祸。" },
      { t: "p", s: "九二，大车以载，有攸往，无咎：你的才能和德行像一辆大车，装得下这份大收获，稳稳往前走，就不会翻车。" },
      { t: "p", s: "九三，公用亨于天子，小人弗克：有功劳要懂得回馈、把成就归于集体（像王公向天子献礼）；小人德薄位尊、只想自己捞，反而害了自己、守不住。" },
      { t: "p", s: "九四，匪其彭，无咎：彭是盛大、膨胀。事业声势大了，别自我膨胀、到处炫耀；富而能谦、盛而不骄，清醒自持，就平安。" },
      { t: "p", s: "六五，厥孚交如，威如，吉：以诚信待人（厥孚交如），又保有威严分寸（威如），恩威并施，人心凝聚，吉。" },
      { t: "p", s: "上九，自天祐之，吉无不利：一路守正、积德行善，连老天都来帮你，是全卦最吉的一爻——但前提是前面几爻都做对了。" },

      { t: "h", s: "五、生活案例：怎么用大有卦对待突然的大收获" },
      { t: "case", title: "比赛拿了大奖，怎么不飘？", s: "假设你们班参加辩论赛拿了全校第一，奖金加奖状，正是一波『大有』。怎么用大有卦接住这份收获？第一，初九『无交害』——别一获奖就到处显摆、惹人嫉妒，也别急着跟人攀关系换好处，先稳住。第二，『艰则无咎』——记住备赛时熬的夜、查的资料，居安思危，别觉得『我天生厉害』。第三，九二『大车以载』——你确有实力托住这份荣誉，那就大方往前走，带队再战。第四，九三『公用亨于天子』——上台领奖时把功劳分给队友和指导老师，别一人独吞，大家才服你。第五，九四『匪其彭』——朋友圈别连发十天奖状、别见人就吹，富而能谦，同学才还愿意跟你玩。第六，六五『厥孚交如，威如』——对低年级同学既诚恳帮忙、又保持该有的榜样分寸，恩威并施。曾仕强说：大有之后最危险的不是得不到，是得到了守不住。用大有卦接住荣誉，你不是去炫耀，是去『为富要仁』——把这份光，分一点给身边人。" },

      { t: "h", s: "六、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住大有卦", items: [
        "画面法：默念『火天大有』——天上挂着一个大太阳（离火），光芒铺满大地，就是『什么都丰足』；跟同人卦（天火同人）放一起想，一个火在下（同心）、一个火在上（大获），上下一翻，差一个字差一个世界。",
        "核心句：大有核心是『为富要仁·遏恶扬善』——富了别飘、别做坏事（遏恶），有能力就帮人一把（扬善），顺着天理良心完成美好使命（顺天休命）。",
        "行动法：记住九四『匪其彭』和上九『自天祐之』——有了收获别自我膨胀、低调守住（匪其彭）；守住正道、积德行善，老天自然来帮你（自天祐之）。"
      ]},
      { t: "p", s: "曾仕强说：大有是『同人的最佳效果』。你每多团结一个人、每多守一次正道，老天就多塞给你一份——但你接得住吗？那要看你是不是为富要仁。" },

      { t: "quiz", questions: [
        { type: "choice", q: "大有卦的卦象『火天大有』是怎么叠出来的？", options: ["上离（火）下乾（天）", "上乾下离", "上坤下乾", "上离下坤"], answer: 0, explain: "大有上卦离（火）、下卦乾（天），火在天上普照万物，所以叫火天大有；与同人（上乾下离）互为综卦，上下一翻。" },
        { type: "choice", q: "《序卦传》为什么说『同人之后是大有』？", options: ["同人打架赢了抢钱", "与人和同心之后，资源人脉自然汇聚归你", "同人之后必倒霉", "大有比同人更高级"], answer: 1, explain: "『与人同者，物必归焉，故受之以大有』——先聚人、后成事，同心之后大获所有。" },
        { type: "choice", q: "九四『匪其彭，无咎』给大收获之后的我们，最重要的提醒是？", options: ["越有越要炫耀", "别自我膨胀、低调守住才平安", "赶紧花光", "装更多钱"], answer: 1, explain: "匪其彭＝不自我膨胀、不张扬，盛而不骄、富而能谦，清醒自持才无咎。" },
        { type: "say", q: "请用『为富要仁』和『匪其彭』说说你最近一次『突然多了点什么』（零花钱、夸奖、奖品、粉丝都行）：当时你有没有飘？如果重来，你会怎么用大有卦守住这份收获？", model: "比如上个月我抖音发了条视频突然涨了300粉，我当时飘了——连发三条『看我多厉害』，还把评论区不同意见的人怼了（这就是没做到匪其彭，自我膨胀）。结果那批新粉取关了一半。如果重来，我会用大有卦：初九『艰则无咎』——记住之前没人看时怎么熬过来的，别飘；九四『匪其彭』——不显摆、不怼人，低调把内容做好；六五『厥孚交如』——真诚回评论、把新粉当朋友而不是粉丝数。曾仕强说为富要仁：涨粉是大有，但守住它靠的是仁——对人多一点善意，老天（算法加人心）才继续帮你（自天祐之）。" }
      ]}
    ]
  },
  {
    id: 16,
    title: "第16课 · 豫卦：雷地豫，安乐中别忘了预备",
    subtitle: "曾仕强说：乐而有节，奖在当下、备在未来",
    review: "上节课我们认识了大有卦——火天大有。上面是离（火）、下面是乾（天），火在天上光芒普照，就是大获所有。卦辞「元亨」教我们源正路正；大象传「君子以遏恶扬善，顺天休命」教我们富了别做坏事、有能力就帮人一把；六爻给我们六句：无交害（不惹是非、艰则无咎）、大车以载（才德托得住）、公用亨于天子（功劳归集体）、匪其彭（别膨胀）、厥孚交如（恩威并施）、自天祐之（守正得天助，全卦最吉）。最重要的是曾仕强那句「为富要仁、福慧双全」——大收获之后最危险的不是得不到，是得到了守不住。今天，顺着《序卦传》「有大而能谦必豫，故受之以豫」，我们来到第16卦——豫卦。大有是「大获所有」，老祖宗说：有了大收获还能谦逊（谦卦我们之前学过），人就安乐了，所以豫卦紧跟着大有。豫不是让你躺平享乐，而是教你：在安乐里，也要有预备、居安思危。",
    blocks: [
      { t: "h", s: "一、豫长啥样：春雷一炸，雷在地面上、地在底下顺" },
      { t: "p", s: "上节课的大有卦是火天大有（上离下乾）。今天的豫卦，上面换成了震（雷），下面换成了坤（地），叫「雷地豫」。它是六十四卦里的第16卦。" },
      { t: "p", s: "你闭眼想：大地安安静静躺着，突然「轰隆」一声春雷炸响，把睡了一个冬天的万物全震醒了——冻了那么久，终于能舒展、能欢腾了。这股「舒展、欢腾、生机勃勃」的劲儿，就是豫。" },
      { t: "p", s: "老祖宗说：震是雷、也是动（家里的长子，老大一出场就热闹）；坤是地、也是顺（母亲，安安静静承载一切）。雷在地面上轰、地在底下顺，雷一动、地一顺，万物都跟着高兴，就叫豫。" },
      { t: "p", s: "曾仕强爷爷讲：豫这个字，本来是「大象」慢慢走、悠然自得的样子，后来引申成「欢乐、安逸、预备」。它有两层意思——一层是乐，一层是「预备」：你要安乐，先得有准备。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上震（长子）下坤（母亲）叠成雷地豫。震长子一出场就「轰隆」热闹，坤母亲在底下安静承载，雷一动地一顺，万物都醒了、都乐了。它呼应第1课那「一家八口」：震长子和坤母亲一上一下。你再把上节课的大有卦（上离下乾、火在天上）摆旁边一比：大有是「光芒普照、大获所有」；豫是「春雷一响、万物欢腾」——一个讲丰收、一个讲丰收之后舒坦地乐。但豫卦的乐，可不像你想的那么简单，它藏着一根警示的弦。" },
      { t: "p", s: "记住这张八卦图：上震（长子）下坤（母亲）叠成雷地豫。雷在地面上炸响、地把顺劲接住，正像你松一口气、舒展着乐的样子——但别忘了，雷一停，你得接着准备。" },

      { t: "h", s: "二、豫讲什么：乐要有节，备着防乐极生悲" },
      { t: "p", s: "豫的卦辞是：「豫，利建侯行师。」「建侯」是封赏有功的诸侯，「行师」是整军备战。曾仕强点得妙：奖和备要同步——先奖功臣鼓舞人心（乐），再整军防下一仗（备），才能既鼓舞又不失控。" },
      { t: "p", s: "大象传最有名：「雷出地奋，豫；先王以作乐崇德，殷荐之上帝，以配祖考。」雷声一响大地振奋，先王就奏乐、推崇德行，把功劳配上价值观和制度——说白了：激励必须配德行、配规矩，否则就是放纵。" },
      { t: "p", s: "曾仕强把豫卦叫「团队激励与风险预演的总指南」：真正的悦豫，不是狂欢，是「奖在当下、备在未来」——让人在快乐里也保持警醒。" },
      { t: "p", s: "彖传最后赞叹一句：「豫之时义大矣哉！」——豫的「时机」最要紧：该乐时乐、该备时备，不合时宜的乐，只有坏处没有好处。" },
      { t: "p", s: "还有个冷知识：谦卦和豫卦是综卦（上下一颠倒）。谦卦六爻全吉，豫卦却多凶多悔——老祖宗在提醒：收着锋芒（谦）容易做好，一放松享乐（豫）就危险，生于忧患、死于安乐。" },

      { t: "h", s: "三、豫六条线：从「飘了」到「醒过来」（豫律六拍）" },
      { t: "p", s: "豫六条爻，把「怎么在乐里不翻车」拆成六句，从下往上读是：鸣豫、介于石、盱豫、由豫、贞疾、冥豫。" },
      { t: "p", s: "初六，鸣豫，凶：刚有点小成绩就到处嚷嚷「我赢啦」、高调庆功，凶。曾仕强说：生于忧患、死于安乐——你让人知道你太爱玩乐，别人就利用你的喜好拿捏你，处境凶险。" },
      { t: "p", s: "六二，介于石，不终日，贞吉：像石头一样硬、稳得住，乐一下就收，不整天嘻嘻哈哈，吉。曾仕强妙喻：一个人的修养就是开关——没客人时轻松说笑很自然，客人一来就全神贯注；该认真认真、该放松放松，就贞吉。" },
      { t: "p", s: "六三，盱豫，悔；迟有悔：盱是瞪大眼献媚拍马屁。靠讨好上面来求乐，一定后悔；早点悔还有救，晚了悔之晚矣。曾仕强一句大实话：在中国靠拍马屁没好下场，上面只是利用你一阵就把你踢了。" },
      { t: "p", s: "九四（卦主），由豫，大有得；勿疑，朋盍簪：由正道而乐，大得人心；别多疑，朋友像用簪子扎头发一样聚到一块儿。曾仕强强调：你是九四就要照顾方方面面的人（不止一个人），大有得＝大家都得着，才叫由豫。" },
      { t: "p", s: "六五，贞疾，恒不死：居安思危，长期保持一点点「小病痛」式的警惕，反而不会「猝死」。好比每月做次灾备演练，团队抗风险力强。" },
      { t: "p", s: "上六，冥豫，成有渝，无咎：玩到昏天黑地（冥豫），但只要下决心改（有渝），就无咎。人健忘，一阵子看你改了，就不算大事——给迷途知返的人留后路。" },

      { t: "h", s: "四、生活案例：怎么用豫卦对待考完试的放松" },
      { t: "case", title: "期末考完，怎么放松不翻车？", s: "假设期末终于考完，你正是一波「豫」——彻底松了。怎么用豫卦接住这份乐？第一，初六「鸣豫，凶」——别一出考场就满世界喊「我稳了、我飘了」，更别把玩乐喜好全暴露，招人拿捏、也招自己松懈（生于忧患死于安乐）。第二，六二「介于石，不终日」——玩一两天可以，但别整天躺平刷手机，该收就收，开关要灵。第三，六三「盱豫」——别为了合群去拍马屁、跟风瞎玩，迟早后悔。第四，九四「由豫，大有得」——约上三五好友正经放松（打球、爬山），大家都有所得，才是真乐，不是一个人闷玩。第五，六五「贞疾，恒不死」——放松归放松，留一根弦：假期作业、下学期预习，稍微惦记点，别彻底断联。第六，上六「冥豫成有渝」——万一真玩过头了（熬夜打游戏半个月），赶紧痛改，改了就无咎。曾仕强说：豫不是叫你别乐，是叫你「乐而有节、奖在当下备在未来」。用豫卦放松，你不是去放纵，是去「顺以动」——该乐时痛快乐，该收时利落收。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住豫卦", items: [
        "画面法：默念「雷地豫」——春雷一炸、大地万物都舒展欢腾，就是「安乐」；跟大有卦（火天大有·丰收）放一起想，一个丰收、一个丰收后舒坦地乐，差一个字差一个境界。",
        "核心句：豫核心是「乐而有节·居安思危」——该乐痛快乐（奖在当下），但别飘、别放纵，松口气也要留一根弦（备在未来），顺以动才吉。",
        "行动法：记住初六「鸣豫凶」和六二「介于石」——一有小成绩别乱嚷嚷（防飘）；像石头一样稳、开关灵活，该认真认真该乐乐，这就是把豫从口号变成本事。"
      ]},
      { t: "p", s: "曾仕强说：豫卦是「安乐中的警醒」。你每在顺境里多留一根弦、每在乐里守住一次正，就是在亲手把「生于忧患死于安乐」这句老话，过成自己的日子。" },

      { t: "quiz", questions: [
        { type: "choice", q: "豫卦的卦象「雷地豫」是怎么叠出来的？", options: ["上震（雷）下坤（地）", "上坤下震", "上离下乾", "上乾下坤"], answer: 0, explain: "豫上卦震（雷、长子）、下卦坤（地、母亲），雷出地奋、万物欢腾，所以叫雷地豫；与谦卦互为综卦。" },
        { type: "choice", q: "卦辞「豫，利建侯行师」和大象「先王以作乐崇德」想告诉我们什么？", options: ["有了大收获就彻底躺平享乐", "奖功臣（乐）与整军备战（备）要同步，激励必须配德行制度，否则就是放纵", "雷越大越吉利", "别听先王的规矩"], answer: 1, explain: "建侯行师＝奖与备同步；作乐崇德＝激励要配上价值观和制度，否则乐就变成放纵，乐极生悲。" },
        { type: "choice", q: "初六「鸣豫，凶」和六二「介于石，不终日，贞吉」给放松的我们，最重要的提醒是？", options: ["一有小成绩就乱嚷嚷、整天玩乐则凶；像石头稳、该收就收才吉", "越嚷嚷越吉利", "整天躺平才吉", "别认真做事"], answer: 0, explain: "鸣豫凶＝一有小成绩就高调、暴露在玩乐里易招祸（生于忧患死于安乐）；介于石＝稳得住、开关灵活、该收就收才贞吉。" },
        { type: "say", q: "请用「鸣豫凶」和「介于石」说说你最近一次放松或玩乐（放假、考完、中奖都行）：当时你有没有「飘」或乱嚷嚷？如果重来，你会怎么用豫卦既痛快乐、又守住不翻车？", model: "比如上学期末考完，我连发五条朋友圈「终于解放啦哈哈哈」，还跟人吹「这学期我根本没复习也稳了」（这就是鸣豫——一有小成绩就高调，还暴露自己爱玩）。结果假期彻底摆烂，作业一字没动，开学被老师点名。如果重来，我会用豫卦：初六鸣豫凶——考完乐一下就好，别满世界嚷、别把底牌亮光；六二介于石——玩两天就收，开关灵活，该预习时预习；六五贞疾——放松也不彻底断联，留根弦惦记作业。曾仕强说乐而有节：痛快乐、利落收，才是雷地豫的真本事。" }
      ]}
    ]
  }
  ,
  {
    id: 17,
    title: "第17课 · 随卦：泽雷随，随遇而安与择善而从",
    subtitle: "曾仕强说：随不是盲从，随的是正道，随遇而安才走得远",
    review: "上节课我们认识了豫卦——雷地豫。上面是震（雷）、下面是坤（地），春雷一炸、万物都舒展欢腾，就是安乐。卦辞「豫，利建侯行师」教我们奖功臣（乐）与整军备战（备）要同步；大象传「先王以作乐崇德」教我们激励必须配德行制度，否则就变成放纵；六爻给我们六句：鸣豫（刚乐就高调则凶）、介于石（像石头稳、该收就收）、盱豫（拍马屁后悔）、由豫（正道而乐大得人心）、贞疾（居安思危）、冥豫（迷途知返）。最重要的是曾仕强那句「乐而有节、奖在当下备在未来」——安乐里也要留一根弦，生于忧患死于安乐。今天，顺着《序卦传》「豫必有随，故受之以随」，我们来到第17卦——随卦。豫卦把士气点燃了、大家乐了，接下来怎么办？老祖宗说：得「随机应变」，让个人和组织都跟得上节奏。所以这节课，我们专门讲一件事：怎么在变化里随遇而安，又不被变化带着走偏。",
    blocks: [
      { t: "h", s: "一、随长啥样：雷在泽底下，泽水跟着雷动" },
      { t: "p", s: "上节课的豫卦是雷地豫（上震下坤）。今天的随卦，把上下换了一换：上面换成兑（泽），下面还是震（雷），叫「泽雷随」。它是六十四卦里的第17卦。" },
      { t: "p", s: "你想象一片大湖（兑就是泽），冬天水面结着冰，湖底却藏着闷雷——「轰隆」一声，整片湖水都跟着波动、跟着动。雷在底下动，泽在上面跟着应，这就叫随。" },
      { t: "p", s: "老祖宗说：兑是悦、也是说（家里的少女，小女儿，爱说爱笑）；震是动、也是雷（家里的长子，大儿子，一出场就热闹）。下面长子一动，上面小女儿就心悦诚服地配合——动而说（悦），所以叫随。" },
      { t: "p", s: "曾仕强爷爷讲：随就是「随遇而安、随缘、随顺」。人生要有弹性，能屈能伸——像湖水一样，雷一来我跟着动，雷停了我稳得住，不僵、不硬拧。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上兑（小女儿）下震（长子）叠成泽雷随。兑小女儿在上面笑盈盈，震大儿子在底下「轰隆」一动，泽水就跟着波动。它呼应第1课那「一家八口」：兑小女儿和震长子一上一下。你再把上节课的豫卦（上震下坤、雷地豫）摆旁边一比：豫是雷在地面上、地把顺劲接住，是「安乐」；随是雷跑到泽底下了、泽水跟着雷动，是「跟着节奏变」。一个讲乐、一个讲变，差的就是这个「随」字。" },
      { t: "p", s: "记住这张八卦图：上兑（小女儿）下震（长子）叠成泽雷随。底下雷一动、上面泽就跟着应，正像你在外面跟着对的节奏走、又不失自己本分的样子。" },

      { t: "h", s: "二、随讲什么：随遇而安，但随的是正道不是盲从" },
      { t: "p", s: "随卦的卦辞是：「随，元亨，利贞，无咎。」比乾卦的「元亨利贞」多了一个「无咎」——曾仕强说，这不是说随卦本身就大吉，而是提醒你：要做到「元亨利贞」全对，才「无咎」；只要你随错了方向，照样有麻烦。" },
      { t: "p", s: "彖传把话说透了：「随，刚来而下柔，动而说，随。大亨贞，无咎，而天下随时，随时之义大矣哉！」天下的现象随时在变，所以你得跟着时势做合理的调整——这就是「随时」。" },
      { t: "p", s: "大象传最有画面感：「泽中有雷，随；君子以向晦入宴息。」天一黑就休息，天一亮再干活。曾仕强点得妙：时机和节奏，比力度和速度更重要——该动时动、该停时停，别蛮干。" },
      { t: "p", s: "可「随」最容易被误会成「别人怎样我就怎样」。曾仕强一句话点破：随是随遇而安，但随的是正道，不是随波逐流。你可以弹性变通，但原则不能丢；你可以跟着节奏走，但方向得是正的。" },
      { t: "p", s: "他还讲过一个扎心的道理：随卦里被领导的人（下面的爻）其实有风险——你跟错了人，就跟着倒霉。所以「随」的头等大事，是选对要跟的人、跟对的方向。" },

      { t: "h", s: "三、随六条线：从「出门找对人」到「用制度留人」（随势六诀）" },
      { t: "p", s: "随卦六条爻，把「怎么随、跟谁随、随到什么程度」拆成六句，曾仕强叫它「随势六诀」，从下往上读是：官有渝、系小子、系丈夫、随有获、孚于嘉、拘系之。" },
      { t: "p", s: "初九，官有渝，贞吉；出门交有功：社会像官场一样起起伏伏（有渝＝有变化），但你别跟着投机取巧。守住原则、为大家服务、不添乱，就吉（从正吉）；然后「出门交有功」——出去找个值得追随的人，找对了你一辈子轻松。曾仕强提醒刚出校门的年轻人：学校学的真本事别丢，但别一上来就硬搬，衡量状况做调整，目的是找到可追随的对象。" },
      { t: "p", s: "六二，系小子，失丈夫：小子是不成熟的人（图短期好处），丈夫是成熟的人（看长远大势）。你拉拢一个，一定丢掉另一个——人没办法样样都要。曾仕强说：这叫「弗兼与也」，此时要心正，善择追随的对象，别因为贪小便宜丢了大局。" },
      { t: "p", s: "六三，系丈夫，失小子；随有求得，利居贞：反过来，绑定长期大势、舍弃蝇头小利，反而有所得；但得到了也要守正道，才能善终。→ 眼光放长远，别被眼前小利勾走。" },
      { t: "p", s: "九四，随有获，贞凶；有孚在道，以明，何咎：你跟随中捞到了好处，要是飘了、不守正，就凶；但只要保持诚信、走在正道上、用行动让上面感受到你的本分（有孚在道以明），就化凶为吉。→ 得了好处别忘形，光明磊落最稳。" },
      { t: "p", s: "九五，孚于嘉，吉：用诚信去对待好同事、好伙伴（孚于嘉），大家信任你，上下都愿意跟你，大吉。→ 当领导的，自己走正道、以诚待人，自然有人随。" },
      { t: "p", s: "上六，拘系之，乃从维之；王用亨于西山：用制度（拘系）把人「系」住，再用恩德（维之）去说服，老板才能安心吃饭。曾仕强说：留人不能只靠感情，得利益绑定（制度）加文化绑定（使命）双管齐下，团队才长久相随。" },

      { t: "h", s: "四、生活案例：怎么用随卦选对要跟的人" },
      { t: "case", title: "社团招新，该跟着哪个学长混？", s: "假设开学社团招新，两个学长都来拉你：学长A天天带你吃喝玩乐、说「跟着我轻松拿学分」（这像六二的「小子」——短期爽）；学长B要求严、带你做真项目、常念叨「基础要打牢」（这像六三的「丈夫」——看长远）。用随卦的思路就对了：第一，初九「官有渝，从正吉」——别看哪个热闹就跟哪个，守住你「来大学是学本事」的原则，不添乱、踏实干。第二，六二「系小子失丈夫」——你要是只图轻松跟了A，短期乐，长期把基础荒了（丢了丈夫），凶。第三，六三「系丈夫」——跟B虽然累点，但项目经验、人脉都攒下了，随有求得。第四，九四「有孚在道」——跟B干活拿到了成果，别到处显摆抢功，光明磊落、诚信待人，才无咎。第五，九五「孚于嘉」——你以诚待人，同级也愿意跟你组队。曾仕强说：随不是盲从。用随卦选人，你不是去当跟班，是去「择善而从」——看准对的节奏和值得追的人，弹性跟着走，自己还长本事。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住随卦", items: [
        "画面法：默念「泽雷随」——大湖底下藏着闷雷，雷一动、整片湖水跟着波动，就是「随」；跟豫卦（雷地豫·安乐）放一起想，一个雷在地面（乐）、一个雷在湖底（跟着变），差一个字差一种活法。",
        "核心句：随核心是「随遇而安·择善而从」——人生要弹性、能屈能伸，但随的是正道不是随波逐流；记住「随时之义大矣哉」，跟着时势做合理调整。",
        "行动法：记住初九「出门交有功」和九五「孚于嘉」——出去找个值得追随的人（别盲从）、自己以诚待人，大家自然愿意跟你；这就是把随从口号变成选人用人的本事。"
      ]},
      { t: "p", s: "曾仕强说：随卦是「柔性领导力与顺势管理」的范本。你每在变化里多守一次正、每在跟人时多挑一次对的，就是在亲手把「随遇而安不盲从」这句话，过成自己的日子。" },

      { t: "quiz", questions: [
        { type: "choice", q: "随卦的卦象「泽雷随」是怎么叠出来的？", options: ["上兑（泽）下震（雷）", "上震下兑", "上坤下震", "上离下震"], answer: 0, explain: "随上卦兑（泽、少女）、下卦震（雷、长子），雷在泽中、泽随雷动，所以叫泽雷随；与蛊卦相邻于序卦传。" },
        { type: "choice", q: "卦辞「随，元亨，利贞，无咎」比乾卦多出的「无咎」想提醒我们什么？", options: ["随卦天生大吉没风险", "要做到元亨利贞全对才无咎，随错方向照样有麻烦，随的是正道不是盲从", "随就行了别讲原则", "无咎是多余的"], answer: 1, explain: "多出的无咎＝做到元亨利贞全对才无后遗症；随错方向照样凶，所以随遇而安但要随正道、不随波逐流。" },
        { type: "choice", q: "六二「系小子，失丈夫」和初九「出门交有功」给选人的我们，最重要的提醒是？", options: ["哪个热闹跟哪个、图短期爽", "人不能样样都要，要善择追随对象：舍弃短期小利（小子）、找值得长期追随的人（丈夫），出门找对人才有功", "只跟熟人", "别跟任何人"], answer: 1, explain: "系小子失丈夫＝拉拢一个必丢一个，要心正善择；出门交有功＝出去找可追随的人，找对了一辈子轻松，这就是随的首要是选对人。" },
        { type: "say", q: "请用「出门交有功」和「系丈夫失小子」说说你最近一次「跟人/选队友/追风口」（选社团、组队、追流行都行）：当时你有没有图短期爽而跟错了人？如果重来，你会怎么用随卦择善而从？", model: "比如上学期我追「盲盒」风口，跟着同学天天抽盒、晒隐藏款（这就是系小子——图短期爽、凑热闹），结果钱花了不少、正事没干，还跟爱学习的朋友疏远了（失丈夫）。如果重来，我会用随卦：初九官有渝从正吉——守住「学生以学为主」的原则，不被风口带偏；出门交有功——找真正值得追的榜样，比如那个天天泡图书馆的学长，跟他混才有长进；六三系丈夫——把时间投在长本事上（长期大势），舍弃盲盒这点小利。曾仕强说随不是盲从：选对节奏、跟对人，弹性跟着走，自己还涨本事，这才是泽雷随的真智慧。" }
      ]}
    ]
  },
  {
    id: 18,
    title: "第18课 · 蛊卦：山风蛊，拨乱反正与整治积弊",
    subtitle: "曾仕强说：蛊不是坏卦，是提醒你「有事要收拾」，乱了就整治",
    review: "上节课我们认识了随卦——泽雷随。上面是兑（泽、小女儿），下面是震（雷、长子），雷在泽底一动、整片湖水跟着波动，就是随。卦辞「随，元亨，利贞，无咎」教我们随遇而安但随的是正道不是盲从；大象传「君子以向晦入宴息」教我们该动就动、该停就停，节奏比蛮干重要；六爻给我们六句随势六诀：官有渝从正吉（出门找对值得追随的人）、系小子失丈夫（别图短期爽丢了长远）、系丈夫（绑定大势有所得）、随有获有孚在道（得了好处别忘形）、孚于嘉（以诚待人自然有人随）、拘系之乃从维之（制度加文化留人）。最重要的是曾仕强那句「随时之义大矣哉」——跟着时势做合理调整，才是柔性领导力。今天，顺着《序卦传》「随必有事，故受之以蛊」，我们来到第18卦——蛊卦。随卦教人跟着节奏走，可顺着顺着、迁就久了，最容易松懈生毛病。老祖宗说：这时候别装看不见，得「动手收拾」，把积弊清掉。所以这节课，我们专门讲一件事：怎么面对乱糟糟的烂摊子，拨乱反正。",
    blocks: [
      { t: "h", s: "一、蛊长啥样：山压在风上，风被憋住闷出毛病" },
      { t: "p", s: "上节课的随卦是泽雷随（上兑下震）。今天的蛊卦，又换了一换：上面换成艮（山），下面换成巽（风），叫「山风蛊」。它是六十四卦里的第18卦。顺着《序卦传》的逻辑：随是「以喜随人」——你什么事都顺着别人、顺着习惯，久了一定「必有事」，生出麻烦，所以随后面跟着蛊。" },
      { t: "p", s: "你想象一座大山（艮就是山，家里的少男，小儿子，稳稳的、爱停住不动），压在一阵风（巽就是风，家里的长女，大女儿，爱钻、爱动）上面。风本来想吹、想流动，可被大山死死压住，只能在山底下打转，空气不流通——时间一长，东西就沤坏、生虫。老祖宗管这叫蛊：古人说「皿虫为蛊」，就是器皿放久了、食物腐坏长出虫子。蛊卦，就是拿这个比喻「积弊」——事情堆着没人管，久了就烂。" },
      { t: "p", s: "曾仕强爷爷讲：蛊卦是「变革前的体检与手术」——先刮骨疗毒，再谈新生。任何长期运转的系统（一个家、一个宿舍、你自己的书桌）都会生虫、老化，这是规律，不用大惊小怪，但也绝不能装没看见。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上艮（小儿子）下巽（大女儿）叠成山风蛊。艮小儿子在上面稳稳压住，巽大女儿在底下想钻想动却被止住——风入而止，积弊就来了。它呼应第1课那「一家八口」：艮小儿子和巽大女儿一上一下。你再把上节课的随卦（上兑下震、泽雷随）摆旁边一比：随是雷在泽底、泽水跟着雷波动，是「跟着节奏变」；蛊是风在山底、被山压住动不了，是「憋住了生虫」。一个讲变、一个讲积弊，差的就是这个「蛊」字。" },
      { t: "p", s: "记住这张八卦图：上艮（小儿子）下巽（大女儿）叠成山风蛊。底下风想动却被山压住、闷着，正像你明知道有毛病却一直拖着、越拖越乱的样子。" },

      { t: "h", s: "二、蛊讲什么：积弊久了要整治，拨乱反正" },
      { t: "p", s: "蛊卦的卦辞是：「蛊，元亨，利涉大川；先甲三日，后甲三日。」元亨，是敢动手治就能通；利涉大川，是治好了就能跨过大风险；最妙的是「先甲三日，后甲三日」——曾仕强说这是改革的节奏：甲是新政开始，先甲三日＝动手前想清楚、做铺垫（预热），后甲三日＝落地后盯着、防回潮（巩固），中间才是动刀。切忌脑子一热一刀切。" },
      { t: "p", s: "彖传把话说圆了：「蛊元亨，而天下治也……先甲三日，后甲三日，终则有始，天行也。」意思是：坏事治好了，局面重新亨通；而且有始有终，这才合天道——治完还要守住，别让它再烂回去。" },
      { t: "p", s: "大象传最有画面感：「山下有风，蛊；君子以振民育德。」山下有风本来是自然现象，可君子看到风被山憋住、风气淤塞，就懂了：要振兴教化（振民＝唤醒大家的问题意识、破旧），培育德行（育德＝树立新的价值观、立新）。曾仕强点得透：只惩罚不教育，旧虫没除、新虫又生，所以得两手抓。" },
      { t: "p", s: "曾仕强还提醒一句大实话：腐败、积弊是必然现象，不必大惊小怪，但必须严加防范。蛊不是坏卦，是天地给你发的「系统提醒」：有事要收拾了。整治有三个要点：动机纯正（不为自己捞）、过程讲究（按节奏来）、前后任彼此尊重（不掀老底）。" },

      { t: "h", s: "三、蛊六条线：从「接手烂摊子」到「功成身退」（治蛊六刀）" },
      { t: "p", s: "蛊卦六条爻，全在讲怎么「干蛊」（干＝动手整治）。曾仕强叫它「治蛊六刀」，刀刀见血又刀刀救命。整治分两类：干父之蛊（爸爸留的精神、原则层面的老毛病，偏硬）、干母之蛊（妈妈留的生活、物质层面的老习惯，偏软）。" },
      { t: "p", s: "初六，干父之蛊，有子，考无咎，厉终吉：儿子把父亲留下的弊病整治了，有这样的好儿子，先父也没后遗症，开头艰难但最终吉。小象说「意承考也」——你的用意是继承、发扬先父的遗志，不是全盘否定前任。→ 接手烂摊子第一步：勇于担责，但别一上来就骂上一任。" },
      { t: "p", s: "九二，干母之蛊，不可贞：处理柔性旧习（人情、文化、老流程）不能硬碰硬，要刚柔适宜、以柔克刚。→ 老习惯别一刀切，用培训加激励慢慢化开。" },
      { t: "p", s: "九三，干父之蛊，小有悔，无大咎：刚毅果断除硬性积弊，做事直了点、略有遗憾，但大方向没错、无大祸。→ 原则问题必须坚决改，别因为怕背一点骂名就缩手。" },
      { t: "p", s: "六四，裕父之蛊，往见吝：一味宽容、纵容旧弊继续肥大，往后一定陷进麻烦。→ 这就是养痈遗患，宽容不能用在原则性弊病上，当断不断反受其乱。" },
      { t: "p", s: "六五，干父之蛊，用誉：整治前任旧问题时，心怀宽厚、不抹黑前人，用赞誉加新愿景带动大家，反而收获名望人心。→ 整顿旧事最忌全盘否定前人，顾全情面、客观纠错，上下才服你。" },
      { t: "p", s: "上九，不事王侯，高尚其事：乱象彻底肃清、革新完成，不贪恋权位名利，抽身守正。→ 全卦最高境界：整治只为除弊安民，不是谋自己权位；事成身退，让制度自己转起来，德行圆满。" },

      { t: "h", s: "四、生活案例：宿舍卫生烂摊子，怎么用蛊卦收拾" },
      { t: "case", title: "宿舍卫生烂摊子，怎么用蛊卦收拾？", s: "假设你当上寝室长，接手一间「蛊」了的寝室——地上外卖盒堆成山、值日表形同虚设，这就是积弊。用蛊卦的思路就顺了：第一，初六干父之蛊、意承考——别一上任就骂上一届「你们太差了」，而是先认下「这摊子我接了」，勇于担责，开头累（厉）但终吉。第二，九二干母之蛊不可贞——有个室友就是不爱倒垃圾（妈妈式的生活老习惯），你别硬罚、别当众吼，私下请他喝杯奶茶、定个「谁最后走谁倒」的软规矩，以柔克刚。第三，九三干父之蛊小有悔无大咎——把「卫生差就全班扣分」的硬制度立起来，有人抱怨「至于吗」，你顶住，小有摩擦但无大咎，原则不能松。第四，六四裕父之蛊往见吝——别心软「这次就算了」，纵容一次下次更乱，养痈遗患。第五，六五干父之蛊用誉——谁这周做得好，群里公开表扬加发个小红包（用誉），大家跟着学，不抹黑谁。第六，上九不事王侯高尚其事——等寝室成了标杆，你别赖着寝室长不走、别居功，把值日制度留给他们自己转，功成身退。曾仕强说：蛊不是灾难，是系统给你的自我提醒。敢「先甲三日」想清楚、「甲日」动刀、「后甲三日」巩固，烂摊子就是翻盘机会。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住蛊卦", items: [
        "画面法：默念「山风蛊」——大山压在风上面，风被憋住打转、空气不流通，久了就腐坏生虫，这就是蛊（积弊）。跟随卦（泽雷随·雷在泽底跟着动）放一起想：一个被压住生虫（蛊）、一个跟着节奏变（随），差一个字两种命运。",
        "核心句：蛊核心是「积弊要整治·拨乱反正」——腐败是必然的，别怕但必须治；记住「先甲三日·后甲三日」，改革要预热→动刀→巩固三段走，切忌一刀切。",
        "行动法：记住初六「意承考」（继承不否定、勇于担责）和上九「不事王侯高尚其事」（功成身退）——接手烂摊子先担责不甩锅，收拾干净就退场，把制度留给后人。"
      ]},
      { t: "p", s: "曾仕强说：蛊卦是「变革前的体检与手术」。你每在积弊面前多动手收拾一次、每在整治时多守一次正，就是在亲手把「拨乱反正」这句话，过成自己的日子。" },

      { t: "quiz", questions: [
        { type: "choice", q: "蛊卦的卦象「山风蛊」是怎么叠出来的？", options: ["上艮（山）下巽（风）", "上巽下艮", "上坤下艮", "上艮下震"], answer: 0, explain: "蛊上卦艮（山、少男）、下卦巽（风、长女），山下有风、风被山止而郁积成蛊；顺着序卦传「随必有事故受之以蛊」，紧接第17卦随卦。" },
        { type: "choice", q: "卦辞「先甲三日，后甲三日」想教我们什么？", options: ["改革当天一口气干完", "整治积弊要有动手前的预热（先甲三日）和实施后的巩固（后甲三日）的节奏，切忌一刀切", "甲日绝对不能做事", "三日就是正好三天"], answer: 1, explain: "甲＝事之开端；先甲三日＝动手前周密筹划，后甲三日＝落地后追踪巩固防回潮，终则有始，改革要三段走不能蛮干。" },
        { type: "choice", q: "初六「干父之蛊，有子，考无咎」和六四「裕父之蛊，往见吝」给接手烂摊子的我们什么提醒？", options: ["全盘否定前任最英明", "初六教我们继承不否定、勇于担责收拾（厉终吉）；六四警告纵容旧弊必陷困境（养痈遗患），该动手别心软", "旧毛病随它去别管", "千万别接烂摊子"], answer: 1, explain: "干父之蛊意承考＝用意是继承发扬先人遗志而非掀老底；裕父之蛊＝纵容积弊继续肥大终见吝，当断不断反受其乱。" },
        { type: "say", q: "用「干父之蛊／干母之蛊」和「先甲三日·后甲三日」说说你最近一次面对的「积弊／烂摊子」（寝室卫生、班级拖延、自己的拖延症都行）：当时你是不管它（裕父之蛊）还是动手收拾了？如果重来，你会怎么用蛊卦「先想清楚→动刀→巩固」？", model: "比如上学期我那张书桌，书堆成山、充电线缠成团，这就是我的蛊——积弊。当时我基本是裕父之蛊：每次想收拾都「明天再说」，纵容它越来越乱，找东西急出一头汗（往见吝）。如果重来，我用蛊卦三步走：先甲三日——先把「哪些该留哪些该扔」列个清单、想清楚分类（预热，不蛮干）；甲日动刀——用一个下午把书按科目上架、线用扎带理顺、桌面只留常用（干蛊，厉终吉，开头累但舒坦）；后甲三日——定个「每天睡前五分钟归位」的小规矩并真执行一周（巩固，防回潮）。曾仕强说蛊是系统给你的自我提醒：敢动手收拾，烂摊子就是翻盘机会，别等虫子把桌子蛀空才动手。" }
      ]}
    ]
  }
  ,
  {
    id: 19,
    title: "第19课 · 临卦：地泽临，亲临现场与现场领导学",
    subtitle: "曾仕强说：临卦是现场领导学——既要高瞻，又要亲下",
    review: "上节课我们认识了蛊卦——山风蛊。上面是艮（山、小儿子），下面是巽（风、大女儿），风被大山压住、闷着生虫，就是积弊。卦辞「先甲三日，后甲三日」教我们整治烂摊子要预热、动刀、巩固三段走；大象传「君子以振民育德」教我们惩罚要配上教育，否则旧虫没除新虫又生；六爻给我们六刀治蛊：干父之蛊（继承不否定、勇于担责）、干母之蛊不可贞（老习惯以柔克刚）、干父之蛊小有悔（原则问题坚决改）、裕父之蛊（纵容旧弊必陷困境）、干父之蛊用誉（整顿不抹黑前人）、不事王侯高尚其事（功成身退）。最重要的是曾仕强那句「蛊是变革前的体检与手术」——敢动手收拾，烂摊子就是翻盘机会。今天，顺着《序卦传》「蛊者事也，有事而后可大，故受之以临」，我们来到第19卦——临卦。你把蛊卦的烂摊子收拾干净了、组织焕然一新，老祖宗说：接下来不能坐回办公室，得「亲临一线、实施领导」。所以这节课，我们专门讲一件事：怎么从「遥控指挥」变成「到现场去」的好领导。",
    blocks: [
      { t: "h", s: "一、临长啥样：大地压在湖上面，居高又亲和" },
      { t: "p", s: "上节课的蛊卦是山风蛊（上艮下巽）。今天的临卦，上下又换了：上面换成坤（地），下面换成兑（泽），叫「地泽临」。它是六十四卦里的第19卦。顺着《序卦传》的逻辑：蛊是把积弊整治干净（有事），事情理清了、团队整好了，自然能「大」——要做大、要做强，就得有人来领导、来亲临，所以蛊后面跟着临。" },
      { t: "p", s: "你想象一片大湖（兑就是泽，家里的少女，小女儿，爱说爱笑、爱聚水），上面稳稳盖着一层厚实的大地（坤就是地，家里的母亲，包容、稳当）。地比泽高，是「居高临下」；可大地又温柔地罩着湖水、容纳它，不是压垮它——这就是临：既站得高看得远，又亲近下面、关心下面。" },
      { t: "p", s: "曾仕强爷爷把临卦叫「现场领导学」：领导既要「高瞻」（抬头看方向），又要「亲下」（低头进一线）；既要有权威（威），又要给实惠（惠）。你越往上走，越容易飘在半空遥控，临卦就是一道提醒：下来，到现场去。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上坤（母亲）下兑（小女儿）叠成地泽临。坤母亲在上面稳稳罩住，兑小女儿在底下欢腾聚水，地高泽低、居高又亲和。它呼应第1课那「一家八口」：坤母亲和兑小女儿一上一下。你再把上节课的蛊卦（上艮下巽、山风蛊）摆旁边一比：蛊是风被山压住闷出虫（积弊），临是泽被地罩住却容得下（亲临包容），一个讲收拾、一个讲领导，差的就是这个「临」字。" },
      { t: "p", s: "记住这张八卦图：上坤（母亲）下兑（小女儿）叠成地泽临。大地居高临下却温柔罩着湖水，正像你当上负责人后，既把方向看准、又愿意俯身进一线的样子。" },

      { t: "h", s: "二、临讲什么：亲临治事守正必通，但盛极要防衰" },
      { t: "p", s: "临卦的卦辞是：「临，元亨利贞；至于八月有凶。」元亨利贞，是只要你亲临治事、守住正道，就大通（亨）；最妙的是后半句「至于八月有凶」——曾仕强说这是盛极而衰的警钟：任何亲临领导如果长期高压、高控、高频地下去，下属迟早反弹，到「八月」（阳气转衰的时节）就该出事了。" },
      { t: "p", s: "大象传最有画面感：「泽上有地，临；君子以教思无穷，容保民无疆。」教思无穷＝持续教化、沟通不能停；容保民无疆＝包容、保障下属，让他们没有后顾之忧。曾仕强点得透：领导不是发号施令就完事，得一直教、一直容，团队才稳。" },
      { t: "p", s: "他还送了我们一句扎心的：临卦之后是观卦——你亲临现场做得好不好，别人迟早会「观其后果」、来验收。所以「光临」的反面，是「有人来验收你来了以后的成果」。任何事都有前因后果，别只图到场的热闹。" },
      { t: "p", s: "曾仕强把临的核心一句话收住：「以真诚感应他人，以合理驾驭现场」——到现场不是去耍威风，是用真心换真心，用合理的方法把局面带好。" },

      { t: "h", s: "三、临六条线：从「以诚感人」到「敦厚收官」（临场六步）" },
      { t: "p", s: "临卦六条爻，把「怎么亲临、怎么当个让人服的领导」拆成六句，曾仕强叫它「临场六步」，从下往上读是：咸临、咸临、甘临、至临、知临、敦临。" },
      { t: "p", s: "初九，咸临，贞吉：咸（鹹）和「感」只差一个「心」字，所以咸临＝「无心之感」——不是不用心，而是去掉功利心，不抱着「我对你好你就得回报我」的算计。你只是尽本分、做该做的，动机纯正、出乎真诚，自然能感应别人，吉。小象说「志行正也」——你的心智和行为都合乎人性、将心比心。曾仕强举过大地的例子：天地无私滋养万物、从不要求回报，所以万物都谢天谢地；人也是一样，尽本分、问心无愧就好。" },
      { t: "p", s: "九二，咸临，吉无不利：这一爻是卦主。你初九用真诚打开了局面，到了九二（层级更高了）要「加强信心」——继续用真诚，别因为手里有威势就改用权压人。小象「未顺命也」藏着易经的辩证：你往上走本是一帆风顺（顺），可顺的时候最容易刚愎冒进（不顺）；反过来，有威势而不用，别人反而更感动。曾仕强说：很多人基层主管时脾气好，一当高层就「官大脾气长」，就是忘了这一句。" },
      { t: "p", s: "六三，甘临，无攸利；既忧之，无咎：甘临＝靠甜言蜜语、粉饰太平来「亲临」。孔子早就警告「巧言令色，鲜矣仁」——你靠漂亮话取悦人，得到的情报可能是假的、成果可能被扭曲，一点实惠都换不来（无攸利）。但六三也留了活路：只要你能警觉、忧虑这后果并及时改（既忧之），破坏就不长久，无咎。小象「咎不长也」——及时刹车，轻微偏差也能救回来。" },
      { t: "p", s: "六四，至临，无咎：至＝亲自到、深入到位。你来了就真深入现场，不远远躲着、不拍个照就跑、不作秀。小象「位当也」——做你该做的：要么不来，要来就亲临到底。曾仕强讲过一个救灾的细节：镜头先拍谁的脚？拍你满脚泥泞、裤腿湿透，大家就感动「你是真心在」；要是镜头先拍你笑脸，反而证明你警惕不够、是来作秀的。差的就是这点真心。" },
      { t: "p", s: "六五，知临，大君之宜，吉：知＝明智。高明的领导不事必躬亲，而是「知人善任」——看清谁该去、去了该做什么，掌握全盘就好，让底下人各尽其才。小象「行中之谓也」——走中道、以合理为准，这就是「无为而治」（曾仕强说儒道合一，孔子也讲无为，不是道家的专利）。刘邦说「运筹帷幄不如张良、带兵不如韩信」，就是知临。" },
      { t: "p", s: "上六，敦临，吉无咎：敦＝敦厚、诚恳。到了高位去现场，下面人基础活都干完了，你就多关心、多肯定、多说「谢谢大家、辛苦了」，别当众挑刺（问题留到内部跟核心干部讲）。小象「志在内也」——关心是真心的，分场合表达，维护团队士气。曾仕强说：公开表扬、内部批评，千万别反过来。" },

      { t: "h", s: "四、生活案例：当社团负责人，怎么用临卦带团队" },
      { t: "case", title: "刚当上社团负责人，怎么带人不翻车？", s: "假设你这学期当上了社团负责人，这就是你的「临」。用临卦的思路就稳了：第一，初九咸临——别一上任就摆负责人架子、动不动发脾气，先把活儿干在前面、以诚待人（不抱「我对你好你就得听我的」的算计），大家自然服你，吉。第二，九二咸临——当上负责人后也别「官大脾气长」，手里有点权力就改用命令压人，继续用真诚，才无不利。第三，六三甘临——别光在群里发「大家加油冲鸭」的漂亮话，却不给场地、不给预算（甜言蜜语无实利），发现这毛病赶紧补资源，既忧之则无咎。第四，六四至临——招新摆摊、活动布置你真下去一起干，别只站旁边拍照发朋友圈（作秀），满手胶布别人都看在眼里。第五，六五知临——别啥都自己扛，把设计交给会画的、把外联交给嘴皮子利的，你只管方向和兜底，知人善任才吉。第六，敦临——活动成了，当众谢谢大家、夸团队；真有做得差的，私下跟骨干说，别当众拆台。曾仕强说：临之后是观，别人会验收你的成果。用临卦带人，你不是去耍威风，是去「心到、身到、智到」——真诚换真诚，合理带局面。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住临卦", items: [
        "画面法：默念「地泽临」——厚实的大地盖在欢腾的湖水上面，居高又亲和，就是「临」（既高瞻又亲下）；跟随卦（山风蛊·风被山压生虫）放一起想：一个收拾积弊（蛊）、一个亲临领导（临），差一个字两种活法。",
        "核心句：临核心是「亲临现场·真诚感应」——以真诚换真心、以合理带局面；记住「至于八月有凶」和「临后有观」，盛极要防衰、成果终被验收，别只图到场的热闹。",
        "行动法：记住初九「咸临（无心之感）」和六五「知临（知人善任）」——去掉功利心以诚待人，当上头也别事必躬亲、学会分活给人，这就是把临从口号变成领导力。"
      ]},
      { t: "p", s: "曾仕强说：临卦是「现场领导学」。你每在现场多蹲一次、每用真诚多换一次真心，就是在亲手把「以身作则、亲临一线」这句话，过成自己的日子。" },

      { t: "quiz", questions: [
        { type: "choice", q: "临卦的卦象「地泽临」是怎么叠出来的？", options: ["上坤（地）下兑（泽）", "上兑下坤", "上艮下兑", "上坤下艮"], answer: 0, explain: "临上卦坤（地、母亲）、下卦兑（泽、少女），泽上有地、地高泽低，居高临下又包容，所以叫地泽临；顺着序卦传「蛊者事也，有事而后可大，故受之以临」，紧接第18卦蛊卦。" },
        { type: "choice", q: "初九「咸临，贞吉」的「咸」和「感」差一个心字，想告诉我们什么？", options: ["到现场要大发雷霆", "咸＝无心之感，亲临要去掉功利心、以诚待人、动机纯正才吉，不是不用心而是不图回报", "咸就是甜言蜜语", "咸临等于不去现场"], answer: 1, explain: "咸临＝无心之感：不是不用心，是去掉「我对你好你就得回报我」的算计，尽本分、出乎真诚才能感应别人，志行正也、贞吉。" },
        { type: "choice", q: "六三「甘临，无攸利」和六五「知临，大君之宜，吉」给当负责人的我们什么提醒？", options: ["光说漂亮话不给实惠，还爱事必躬亲", "甘临＝靠甜言蜜语无实利（巧言令色鲜矣仁），要警觉改过；知临＝知人善任、不事事躬亲才是大君之宜，吉", "越凶越吉利", "别去现场"], answer: 1, explain: "甘临无攸利＝粉饰太平取悦人无实惠，既忧之则无咎；知临＝掌握全盘、知人善任走中道（无为而治），是领导的最高境界，大君之宜吉。" },
        { type: "say", q: "请用「咸临（无心之感）」和「知临（知人善任）」说说你最近一次「带人/分工/当小组长」（班级职务、社团、小组作业都行）：当时你有没有图回报才对人好、或啥都自己扛？如果重来，你会怎么用临卦既以诚待人、又把活分出去？", model: "比如上学期小组作业我当组长，一开始我犯了两样毛病：一是咸临的反面——我帮队友改格式、找资料，心里偷偷记着「我对你这么好，你下次得听我的」（这就是有心之感，动机不纯）；二是知临的反面——我怕别人做不好，PPT、数据、排版全自己扛，累到熬夜。结果队友觉得我被「绑架」了、自己也没成长，我也一肚子委屈。如果重来，我用临卦：初九咸临——去掉算计，只是尽组长本分帮人，不图回报、问心无愧，真诚反而更聚人；六五知临——看清谁擅长啥，设计给会画图的、查文献给细心的，我只把方向和兜底，知人善任才吉，团队也长本事。曾仕强说临是现场领导学：心到、身到、智到，真诚换真心、合理带局面，这才是地泽临的真本事。" }
      ]}
    ]
  },
  {
    id: 20,
    title: "第20课 · 观卦：风地观，怎么看人也被人看",
    subtitle: "曾仕强说：临是上级看下面，观是下面看上面——人生就是一场「观」的修行",
    review: "上节课我们认识了临卦——地泽临。上面是坤（地、母亲），下面是兑（泽、小女儿），大地居高临下却温柔罩着湖水，既站得高又亲近下面；卦辞「至于八月有凶」是盛极而衰的警钟，大象传「教思无穷，容保民无疆」教我们持续教化、包容下属；六爻给我们临场六步：咸临（初九·无心之感/去功利心以诚待人）、咸临（九二·有威势而不用）、甘临（六三·甜言蜜语无实利）、至临（六四·亲临深入不作秀）、知临（六五·知人善任）、敦临（上六·敦厚·公开表扬内部批评）；最重要的是曾仕强那句「临是现场领导学」——心到、身到、智到。他还留了个钩子：临之后是观，你亲临现场做得好不好，别人迟早来「观」、来验收。今天，顺着《序卦传》「临者大也，物大然后可观，故受之以观」，我们来到第20卦——观卦。你把临卦的领导做到了、成果摆出来了，老祖宗说：接下来要学习怎么「看」，也怎么「被看」。",
    blocks: [
      { t: "h", s: "一、观长啥样：风走在大地面上，把藏着的都吹出来" },
      { t: "p", s: "上节课的临卦是地泽临（上坤下兑）。今天的观卦，上下又换了：上面换成巽（风），下面还是坤（地），叫「风地观」。它是六十四卦里的第20卦。" },
      { t: "p", s: "顺着《序卦传》的逻辑：临是亲临一线、把事情做大了（物大），事情做大了、有成果了，自然要拿出来给人看、大家也要来看你，所以临后面跟着观。" },
      { t: "p", s: "你想象一阵风（巽就是风，家里的长女，大姐姐，细致、能钻进缝隙）吹过一片大地（坤就是地，家里的母亲，包容、承载）。风一吹过地面，把藏在草丛里的碎纸、落叶全掀起来，让你看得清清楚楚——这就是观：居高而察、吹拂万物、无所不察。" },
      { t: "p", s: "曾仕强把观卦叫「战略洞察与公共形象管理」课：它同时教你两件事——「观人」（你怎么看世界、看别人）和「被观」（别人也在盯着你的一举一动）。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：上巽（长女）下坤（母亲）叠成风地观。风行地上，把藏着的脏乱全吹出来让你看清；它呼应第1课那「一家八口」：巽大姐姐和坤母亲一上一下。你再把上节课的临卦（上坤下兑、地泽临）摆旁边一比：临是大地罩着湖水去亲临做事（行动），观是风把大地上的东西全吹出来给人看（展示验收），一个动手、一个用眼，差的就是这个「观」字。" },
      { t: "p", s: "记住这张八卦图：上巽（长女）下坤（母亲）叠成风地观。风在上、地在下，风一吹大地就把藏在角落的东西全显出来——正像你做出成绩后，大家都会来「观」（看、观摩、验收）你。" },

      { t: "h", s: "二、观讲什么：先诚敬观察，再开口表态（盥而不荐）" },
      { t: "p", s: "观卦的卦辞是：「观，盥而不荐，有孚颙若。」盥（guàn）是祭祀前洗手，表示诚敬；不荐，是还没开始献祭、还没急着表态。曾仕强说：这就像一个人先把手洗干净、心怀虔诚，静静看、先不急着下结论——一句话，「诚敬而不急于表态」。" },
      { t: "p", s: "「有孚颙若」＝你以诚信、庄严的样子示人，大家自然仰望你、信你。引申出一句话：领导者要先观察、再发声；而底下的人，也在观察你的一举一动。" },
      { t: "p", s: "大象传最有画面感：「风行地上，观；先王以省方观民设教。」省方＝巡察四方；观民＝洞察民情；设教＝根据百姓能接受的，推行教化。曾仕强讲了个妙例：古人想让百姓大扫除，直接下命令没人听；就说「放越长的鞭炮福气越大」「垃圾往家里扫＝聚财」，百姓为了福气主动扫，硫磺还顺带消了毒——这叫「神道设教」：不是迷信，是用大家乐意接受的方式引导，比硬说教管用一万倍。" },
      { t: "p", s: "他还点醒我们一个现代病：视而不见。我们大半是「心不在焉」——熟悉的觉得「有啥好看」，新奇的又看不懂，结果看到了跟没看到一样。真会观的人，是「先观后动」：先把情况看清楚，急什么呢？" },

      { t: "h", s: "三、观六条线：从「童观」到「观其生」的认知升级（六级洞察）" },
      { t: "p", s: "观卦六条爻，把「怎么看、看多深」拆成六级，曾仕强叫它认知升级的六步走，从下往上读是：童观、窥观、观我生、观国之光、观我生、观其生。" },
      { t: "p", s: "初六，童观，小人无咎，君子吝：童观＝像小孩看热闹，只看表面、轻信盲从。对不担责任的小人物无妨，对身负责任的君子就是遗憾（吝）。曾仕强说：你若只看销量数字、不看用户真实场景，趋势就溜走了。" },
      { t: "p", s: "六二，窥观，利女贞：窥观＝从门缝偷看，视野狭隘、只信一面之词。古代说女子守在门内偷看尚可（利女贞），男子若只会窥观就可耻（亦可丑也）。现代版：部门经理只听亲信汇报，信息偏狭，决策必错。" },
      { t: "p", s: "六三，观我生，进退：开始反观自己——观察自己团队、自己的生活状态，再决定进还是退。曾仕强说：你看不清别人，往往是因为看不清自己；观己是一切成长的起点。" },
      { t: "p", s: "六四，观国之光，利用宾于王：眼光打开，看懂时代、行业的大势，像宾客借势君王一样借势成长，吉。现代版：小企业借政策东风切入新市场。" },
      { t: "p", s: "九五，观我生，君子无咎：身居高位仍反躬自省、以身作则——要求别人做到的自己先做到，德行服人而非权力压人，所以无咎。" },
      { t: "p", s: "上九，观其生，君子无咎：不止看自己，还看「众生」、看别人怎么活，格局放大到天下，无咎。曾仕强说：最高级的观察，是洞察本质后依然坚守本心。" },

      { t: "h", s: "四、生活案例：怎么用观卦「看懂一次考试成绩」" },
      { t: "case", title: "考完试，怎么用观卦看明白？", s: "假设这次月考成绩出来了，用观卦的思路拆，比光顾着高兴或难过有用得多。第一，初六童观——别只看「总分排名」这一个数字就下结论（像小孩看热闹），得看每科错在哪、是粗心还是真不会，不然下次还踩同一个坑。第二，六二窥观——别只听同桌一个人说「这次题超难」，就觉得自己没考好很正常（门缝看人，信息偏狭），多问几个不同水平的同学、看看整体分布才客观。第三，六三观我生——最关键是回看自己：这段时间是不是手机刷多了、方法对不对、态度飘了？该坚持的坚持、该收心的收心（知进知退）。第四，九五观我生——如果你是个课代表或小组长，别光要求同学订正，自己先把错题本做出来给大家看（以身作则、德行服人）。第五，观卦还教「被观」：你考好了别急着发朋友圈炫耀（盥而不荐——先把姿态做对、不急于表态），低调稳住反而更让人服。曾仕强说：观卦是「先观后动」——看明白了再行动，比盲目自信强一百倍；人生就是阶段性的调整，这次看清了，下次就调整到位。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住观卦", items: [
        "画面法：默念「风地观」——一阵风（巽大姐姐）吹过一片大地（坤母亲），把藏着的碎纸落叶全掀起来让你看清，就是「观」（居高而察、无所不察）；跟随卦（地泽临·大地罩湖水）放一起想：临是亲临去做（行动）、观是做完让人看（展示验收），一个动手、一个用眼，差一个字两种本事。",
        "核心句：观核心是「先观后动·诚敬不躁」——盥而不荐（先洗手诚敬、不急于表态），有孚颙若（诚信庄严众人仰望）；记住「临后是观、被观也是观」，你做出成绩，别人自然来观摩验收。",
        "升级法：记住初六「童观（看热闹）」和九五「观我生（自省）」——别只看表面盲从，也别只盯别人，高位也要反躬自省、以身作则，这就是把观从「看」升级成「修行」。"
      ]},
      { t: "p", s: "曾仕强说：观卦是「观察瞻仰」的修行——临是把事做成，观是把成果摊开给人看、也借别人的眼睛看自己。你每多一分诚敬、多一次先观后动，就是在亲手把「看清世界、也看清自己」这件事，过成自己的日子。" },

      { t: "quiz", questions: [
        { type: "choice", q: "观卦的卦象「风地观」是怎么叠出来的？", options: ["上巽（风）下坤（地）", "上坤下巽", "上巽下兑", "上坤下艮"], answer: 0, explain: "观上卦巽（风、长女）、下卦坤（地、母亲），风行地上、吹拂万物无所不察；顺着序卦传「临者大也，物大然后可观，故受之以观」，紧接第19卦临卦。" },
        { type: "choice", q: "卦辞「盥而不荐，有孚颙若」想告诉我们什么？", options: ["先洗手再献祭才吉利", "盥＝诚敬洗手不急于表态，有孚颙若＝诚信庄严众人自然仰望，先观察再发声", "不洗手就不能看", "只看不做事"], answer: 1, explain: "盥而不荐＝诚敬而不急于表态（先把姿态做对再发声），有孚颙若＝以诚信庄严之姿示人、众人自然仰望；曾仕强提醒：底下的人也在观察你的一举一动。" },
        { type: "choice", q: "初六「童观，小人无咎，君子吝」和九五「观我生，君子无咎」给我们有什么提醒？", options: ["看热闹最聪明", "童观＝像小孩看表面盲从，小人物无妨、担责任者则遗憾；观我生＝高位仍反躬自省以身作则才无咎", "越不反省越好", "别看自己"], answer: 1, explain: "童观是小人（不担责）无咎、君子（担责）吝——身负责任的你若只看表象必酿错；九五观我生＝居高位也要自省、要求别人先自己做到，德行服人所以无咎。" },
        { type: "say", q: "请用「童观（看热闹）」和「先观后动（盥而不荐）」说说你最近一次「凭表面下结论/盲目自信」的经历（考试、选社团、买东西、信一条消息都行）：当时你看到的是哪层表象？如果重来，你会怎么先用观卦「看清楚再行动」？", model: "比如上个月我看同学都在抢一门「听起来超厉害」的选修课，我连大纲都没看就跟着选了（这就是童观——只看热闹、盲从），结果上课发现全是编程、我完全跟不上，白白占了一个学期。还有一次，群里疯传「某补习班押中大题」，我没核实就信了、慌慌张张去报，后来发现是营销号。如果重来，我用观卦：初六童观的反面——不急着跟风，先把课表、大纲、自己基础看清楚；卦辞盥而不荐——先诚敬地观察、不急于表态下单，问几个上过的人、查查真实评价，看明白了再行动（先观后动）。曾仕强说人生是阶段性的调整：看清楚了再动，比盲目自信强一百倍，这次看清下次就调整到位。" }
      ]}
    ]
  },
  {
    id: 21,
    title: "第21课 · 噬嗑卦：火雷噬嗑，怎么咬碎卡住你的硬骨头",
    subtitle: "曾仕强说：观是看清问题，噬嗑是动手解决——通则不痛，痛则不通",
    review: "上节课我们认识了观卦——风地观。上面是巽（风、长女），下面是坤（地、母亲），风行地上把藏着的都吹出来，既教我们「观人」也教我们「被观」；卦辞「盥而不荐，有孚颙若」是诚敬不急于表态、先看清楚再发声；六爻给我们认知升级六级：童观（看热闹）、窥观（门缝偷看）、观我生（反观自己）、观国之光（借大势）、观我生（高位自省）、观其生（看众生放大格局）；最重要的是曾仕强那句「先观后动」。他还留了个钩子：把问题看清之后，得让上下重新咬合、顺畅运转。《序卦传》说「可观而后有所合，故受之以噬嗑，嗑者，合也」——你看清了阻碍，接下来要动手把它「咬碎」。今天，我们来到第21卦——噬嗑卦。观是看清，噬嗑是动手解决，一个看、一个做，正好配成一对。",
    blocks: [
      { t: "h", s: "一、噬嗑长啥样：嘴里卡了硬东西，不咬碎就合不拢" },
      { t: "p", s: "上节课的观卦是风地观（上巽下坤）。今天的噬嗑卦，上下又换了：上面换成离（火、闪电、明察），下面换成震（雷、果断），叫「火雷噬嗑」。它是六十四卦里的第21卦。" },
      { t: "p", s: "顺着《序卦传》的逻辑：观是把问题看清了（可观），看清之后就要「合」——让卡住的东西重新咬合顺畅，所以观后面跟着噬嗑。嗑，就是合、闭上的意思；噬，是用上下牙去咬。" },
      { t: "p", s: "你想象自己正张嘴吃东西，突然牙缝里卡了一根鱼刺、一块硬骨头——上下牙合不拢，嚼不动、咽不下，难受得要命。这就是噬嗑的卦象：口腔里有东西堵着（彖传说「颐中有物，曰噬嗑」）。怎么办？不是忍着，也不是和稀泥，而是果断用力，把那块硬物咬碎、嚼烂，嘴才能重新合上、顺畅进食。" },
      { t: "p", s: "放到生活里：那根「鱼刺」就是卡住你的障碍——团队里推诿扯皮的人、心里过不去的一个结、明知不对却一直拖着的坏习惯、一段消耗你的关系。噬嗑卦说：别绕，咬碎它。" },
      { t: "diagram", key: "taiji", caption: "这是太极图：黑鱼里有白点，白鱼里有黑点。噬嗑卦最妙的地方，是「刚里有柔、柔里有刚」——上离是火、是明察（亮的一面），下震是雷、是果断（动的一面）；明罚之中要藏着宽恕，果断之中要留着教化。就像太极：惩治是阳、是雷，但雷的背后是让系统重新「合」的善意，这善是阴、是包容。曾仕强说：噬嗑不是整人，是咬合以合。" },
      { t: "p", s: "记住这张太极图：噬嗑的核心是「刚柔并济」。上离（火、明察）下震（雷、果断）叠成火雷噬嗑，雷电交加、明动相济；它要的不是把人打死，而是把障碍咬碎、让秩序重归和谐——惩治是手段，通畅才是目的。" },

      { t: "h", s: "二、噬嗑讲什么：明罚敕法，敢断才通（卦辞+大象）" },
      { t: "p", s: "噬嗑卦的卦辞只有六个字：「噬嗑，亨；利用狱。」亨，是通——只要敢校正、敢决断，路就通；利用狱，不是叫你去坐牢，而是「狱」代表一套制度、规矩、奖惩、审计的体系。曾仕强说：利用狱的关键词是三个——公开、公平、果断。" },
      { t: "p", s: "大象传最有力量：「雷电，噬嗑；先王以明罚敕法。」明罚＝把后果明明白白摆出来，让所有人看见（不藏着掖着、不徇私）；敕法＝把规矩钉在墙上，更要钉在每个人心里（不光立法，还要让规矩真落地）。曾仕强把这套叫「明德慎罚」：先教化、给人改过机会，教化不改才动刑罚。" },
      { t: "p", s: "彖传一句话点破真相：「颐中有物，曰噬嗑。噬嗑而亨。」嘴里有了东西堵着，就叫噬嗑；把它咬碎了，就亨通。引申到人生：所有的不通，都是因为不敢断、不愿断、不会断。你断得了纠结、断得了内耗、断得了烂人烂事，路就通了。" },
      { t: "p", s: "曾仕强讲过一个现代病：我们最爱「和稀泥」。团队里有刺头、规则废弛、恶习缠身，大家都装没看见，结果小刺变大刺、大刺变肿瘤。噬嗑卦最忌和稀泥——该咬碎就得咬碎，但牙齿也不能太锋利，咬过头会反噬自己（这就引出下面六爻的教训）。" },

      { t: "h", s: "三、噬嗑六条线：从「小惩大诫」到「积过招凶」的咬合六刀" },
      { t: "p", s: "噬嗑六条爻，曾仕强叫它「咬合六刀」，从最轻的小惩，到最重的反噬，刀刀对症。从下往上读：" },
      { t: "p", s: "初九，屦校灭趾，无咎：屦（jù）是鞋、这里指脚枷，灭趾是遮住脚趾。给初犯小错的人戴个脚镣、限制他行动，只痛不伤根——这叫「小惩大诫」。孔子在《系辞传》里说得好：「小惩而大诫，此小人之福也。」小错不纠，必成大患；早纠小过，反而是福。曾仕强说：孩子第一次撒谎、员工首次迟到、自己偶尔偷懒，点到为止、明确底线，纵容才是害。" },
      { t: "p", s: "六二，噬肤灭鼻，无咎：噬是咬，肤是软肉。咬软肉容易，但用力过猛连鼻子都陷进去了——比喻处理浅显问题要果断直接、快刀斩乱麻，虽显得用力猛，但彻底、不留心结，所以无咎。曾仕强说：职场小摩擦、家庭小误会，当面说清、不冷战不记仇，小事不纠结、大事不糊涂。" },
      { t: "p", s: "六三，噬腊肉，遇毒；小吝，无咎：腊肉是陈年硬肉，咬它像清理历史遗留问题，可能「遇毒」——遭人怨恨、受点委屈。小有波折，但守正道终能化解。曾仕强说：改多年陋习、修复破裂关系、清理团队老问题，过程痛苦，但熬过去就是通途。" },
      { t: "p", s: "九四，噬干胏，得金矢；利艰贞，吉：胏（zǐ）是带骨肉干，金矢是铜箭头（真金不怕火炼，象征刚直）。啃最硬的骨头（触碰红线、原则冲突），过程艰难，但坚守刚直正义就吉。曾仕强说：遇到职场小人、合作方违约、事业瓶颈，不妥协、依法依规，艰难取胜。" },
      { t: "p", s: "六五，噬干肉，得黄金；贞厉，无咎：干肉比带骨的软些，得黄金＝罚当其罪、赢得众人信服。身居高位处理问题要柔中带刚、恩威并施、以德服人，虽有风险但守正无咎。曾仕强说：管理者奖惩、父母管教、调解矛盾，不偏私不滥权，权越大越要谦卑公正。" },
      { t: "p", s: "上九，何校灭耳，凶：何是扛，校是枷锁，灭耳是遮住耳朵（听不进劝）。积恶深重、屡教不改，终酿大祸，凶。曾仕强点醒：刑罚过苛必反噬——「过而不改，是谓过矣」，一意孤行、不听忠告，终致自毁前程。这是噬嗑给「牙齿太锋利」的人的警告。" },

      { t: "h", s: "四、生活案例：怎么用噬嗑「咬碎」睡前刷手机的瘾" },
      { t: "case", title: "手机刷到停不下来，怎么用噬嗑「咬碎」这个瘾？", s: "假设你想改掉「睡前刷手机两小时」的毛病，用噬嗑的思路，比光骂自己「又玩手机」有用得多。第一，初九屦校灭趾——小惩大诫：别一上来就发狠「以后再也不碰手机」（肯定失败），而是先定个小规矩：睡前手机放客厅充电、不带上床，违一次就做个深蹲（小惩），让自己立刻疼一下、记住底线，无咎。第二，六二噬肤灭鼻——果断直接：别「再看五分钟」地磨叽，到点上床就上床，快刀斩乱麻，不留「再看一眼」的心结。第三，六三噬腊肉遇毒——清老问题会有阻力：改掉这个习惯，前三天手会不由自主摸枕头底下（遇毒、小吝），别放弃，知道这是正常反弹，熬过去就通了。第四，六五噬干肉得黄金——你坚持一周后，白天精神好了、黑眼圈淡了（得黄金、众人信服），可以把这招分享给同样熬夜的朋友，恩威并施地带他们也改。第五，千万别走到上九何校灭耳——别因为偶尔破功就自暴自弃、干脆彻底摆烂（扛着枷锁不听劝），那才真凶。曾仕强说：噬嗑不是整人，是「咬合以合」——把卡住你的坏习惯这根刺咬碎，生活重新顺畅，这才是目的。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住噬嗑卦", items: [
        "画面法：默念「火雷噬嗑」——上面离（火、二女儿、闪电·明察），下面震（雷、长子、果断），雷电交加就是「咬合除障」。想象嘴里卡了鱼刺（颐中有物），不咬碎就合不拢，果断咬碎才通畅；跟随卦（风地观·登高看清问题）放一起想：观是看清障碍（看），噬嗑是动手咬碎（做），一个看一个干，配成一对。",
        "核心句：噬嗑核心是「敢断才通·明罚敕法」——卦辞「利用狱」（建制度、明奖惩、敢决断），大象「明罚敕法」（后果透明、规矩落地）；记住「小惩大诫（初九）」和「和稀泥最误事」，该咬碎的别绕，但牙齿也别太锋利（上九凶）。",
        "阶梯法：记住初九「屦校灭趾（小惩大诫·防微杜渐）」和上九「何校灭耳（积过招凶·过而不改）」——轻轻一刀防大祸，重重一刀反噬自身；中间六二到六五是从浅到深、由软到硬、罚当其罪，把「咬合六刀」想成由轻到重的法治阶梯。"
      ]},
      { t: "p", s: "曾仕强说：噬嗑卦是「解决问题」的智慧——观是把问题看清，噬嗑是把障碍咬碎。你每多一次敢断、多一分明规则守底线，就是在亲手把「通则不痛、痛则不通」这件事，过成自己的日子。" },

      { t: "quiz", questions: [
        { type: "choice", q: "噬嗑卦的卦象「火雷噬嗑」是怎么叠出来的？", options: ["上离（火）下震（雷）", "上震下离", "上巽下坤", "上乾下坤"], answer: 0, explain: "噬嗑上卦离（火、闪电、明察）、下卦震（雷、果断），雷电交加、明动相济；顺《序卦传》「可观而后有所合，故受之以噬嗑」，紧接第20卦观卦。" },
        { type: "choice", q: "卦辞「噬嗑，亨；利用狱」里「利用狱」想告诉我们什么？", options: ["赶紧去坐牢", "狱代表制度、规矩、奖惩体系，要公开、公平、果断地校正障碍才通", "别管闲事", "只对自己人严"], answer: 1, explain: "利用狱的「狱」不是监狱，而是制度、审计、惩戒体系；曾仕强讲关键词是公开、公平、果断——敢校正、敢决断，路就亨通。" },
        { type: "choice", q: "初九「屦校灭趾，无咎」和上九「何校灭耳，凶」给我们有什么提醒？", options: ["越狠越好", "初九小惩大诫、防微杜渐（无咎），上九积恶不听劝、刑罚过苛反噬自身（凶），牙齿太锋利会反噬", "别管小错", "犯了错就完了"], answer: 1, explain: "初九屦校灭趾＝小错早纠、小惩大诫是福（孔子「小人之福」）；上九何校灭耳＝积过不改、刑罚过苛必反噬（凶）；曾仕强提醒：噬嗑不是整人，是咬合以合，该断则断、但别把牙齿磨太利。" },
        { type: "say", q: "请用「初九屦校灭趾（小惩大诫）」和「和稀泥最误事」说说你生活里一个「早该咬碎却一直拖着的小障碍」（学习习惯、一段消耗你的关系、一个明知不对的旧毛病都行）：它卡了你多久？如果用噬嗑卦，你会怎么「小惩大诫」地动手？", model: "我拖了快一学期的一个小障碍是：每天放学回家先瘫在沙发上刷短视频，一刷就一小时，作业拖到半夜才写、质量还差。这就是噬嗑说的「颐中有物」——卡在牙缝里的刺，我一直和稀泥（想着「明天再说」），结果小刺变大刺，成绩都受影响。如果用噬嗑卦，我学初九「屦校灭趾·小惩大诫」：不给自己定「再也不刷」这种必败的狠话，而是定个小规矩——回家先把书包放好、手机锁进抽屉、写完一门作业才碰手机；哪天没做到，就罚自己少看一集想看的剧（小惩，立刻疼一下记住底线）。不绕、不拖，像咬碎鱼刺一样把它处理了，学习和睡眠就重新「咬合」顺畅了。曾仕强说：所有的不通都是因为不敢断——我这次就是先断「先刷后写」这个坏习惯，路就通了。" }
      ]}
    ]
  },
  {
    id: 22,
    title: "第22课 · 贲卦：山火贲，怎么把「里子」和「面子」都做好",
    subtitle: "曾仕强说：噬嗑是咬合使其合，贲是给合以美——文质彬彬，然后君子",
    review: "上节课我们认识了噬嗑卦——火雷噬嗑。上面是离（火、闪电、明察），下面是震（雷、果断），雷电交加、明动相济，把卡住你的硬骨头咬碎；卦辞「利用狱」是建制度、明奖惩、敢决断（公开公平果断），大象「明罚敕法」是后果透明、规矩落地，六爻「咬合六刀」从初九小惩大诫到上九积过招凶，核心是「通则不痛、痛则不通」。最关键的是曾仕强那句「噬嗑不是整人，是咬合以合」——把障碍咬碎，是为了让系统重新顺畅。他还留了个钩子：咬合合拢了，可不能只勉强凑合。《序卦传》说「嗑者合也，物不可以苟合而已，故受之以贲，贲者饰也」——合了不能将就，要贲（装饰美化）让它有品质。今天，我们来到第22卦——贲卦。噬嗑是动手「合」、贲是动手「美」，一个武治、一个文饰，正好配成一对综卦。",
    blocks: [
      { t: "h", s: "一、贲长啥样：山下有火，火映山、山衬火，自然成纹" },
      { t: "p", s: "上节课的噬嗑卦是火雷噬嗑（上离下震）。今天的贲卦，上下又换了：上面换成艮（山、小儿子、安静稳重），下面换成离（火、二女儿、光明文采），叫「山火贲」。它是六十四卦里的第22卦。" },
      { t: "p", s: "顺《序卦传》的逻辑：噬嗑是咬合、把障碍咬碎使其「合」（解决不通），但合了不能「苟合」——不能勉强凑合、将就了事，要让这个合有品质、有美感，所以噬嗑之后跟着贲。贲，就是文饰、装饰、美化。曾仕强说：贲卦和噬嗑是相综的，噬嗑是「武治」（动法治的牙），贲是「文饰」（用文明礼乐去美化），一个刚、一个柔。" },
      { t: "p", s: "你想象一座山，夜里山脚燃起篝火（下离火），火光把山的轮廓、岩石纹理、草木照得分明美丽——这就是「山下有火，贲」。火不是山本身，却让山显出纹彩；贲就是在「本质」（里子）之外，加一层恰到好处的「装饰」（面子），让人舒服、让事顺遂。" },
      { t: "p", s: "生活里：贲就是你的「面子」——说话的语气、穿着打扮、PPT 排版、送礼的包装、待人接物的礼貌。里子（本质）当然重要，但面子（文饰）也重要，贲卦教我们平衡两者，别只顾一头。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：贲卦「山火贲」，上面是艮（山、小儿子），下面是离（火、二女儿），第1课我们讲过「一家八口」——艮是小儿子、离是二女儿，这一课轮到他俩搭伙。上面山（安静、稳重、守住本质），下面火（光明、文采、懂得修饰），山上山下、一止一明，正好演「用文明的火光，把本质照得更动人」的戏。曾仕强说：质是山（根本）、文是火（修饰），无质之文是浮华、无文之质显粗鄙，唯有山火相济、文质平衡，才算「贲」。" },
      { t: "p", s: "记住这张八卦图：贲卦的核心是「文质彬彬」。上艮（山、本质）下离（火、文采）叠成山火贲，山下有火、火映山纹；它要的不是把人包装成假象，而是让本质被恰当地照亮——装饰是手段，本质才是目的。" },

      { t: "h", s: "二、贲讲什么：文质彬彬，然后君子（卦辞+大象）" },
      { t: "p", s: "贲卦的卦辞：「贲，亨；小利有攸往。」亨，是通达——适度装饰让人际、办事都顺当；但只有「小利」，你只能小有前进，不能大张旗鼓。为什么？因为装饰是锦上添花、是辅助，本质（实力、品德）才是根本；把精力都花在打扮上，内在的修养就荒了，得不偿失。曾仕强提醒：「小利」二字点明——贲是配角，不是主角。" },
      { t: "p", s: "大象传最见格局：「山下有火，贲；君子以明庶政，无敢折狱。」明庶政＝把日常政务、流程、产品做得清清楚楚、明明白白、有文明美感（让制度不再是冷冰冰的牙，而是暖人心的形）；无敢折狱＝但不能用「文饰」的方式去断案审判——法治要直指本质，看证据、不听花言巧语，绝不能为好看而粉饰是非。曾仕强把这套叫「刚骨之后塑文化」：先正骨（噬嗑立规矩），再美容（贲塑文明）。" },
      { t: "p", s: "彖传一句话把贲讲到了天下高度：「观乎天文，以察时变；观乎人文，以化成天下。」看天上的纹路（日月星辰）能察四时变化；看人间的纹路（礼仪、文化、艺术）能用教化成就天下——「文化」两个字就是从这儿来的，以文教化。" },
      { t: "p", s: "孔子的解读最经典：「质胜文则野，文胜质则史。文质彬彬，然后君子。」质（里子）压过文（面子），显得粗野；文压过质，显得虚浮（史＝史官般华而不实）。两者平衡，才是君子。曾仕强点破贲的本质：「当你心里越空虚，就越需要外面的装饰，怕人家看穿你」——真正的美来自内心充实，不是外壳。" },

      { t: "h", s: "三、贲六条线：从「舍车徒步」到「白贲无咎」的贲饰六阶" },
      { t: "p", s: "贲六条爻，曾仕强叫它「贲饰六阶」，一级比一级返璞归真。从下往上读：" },
      { t: "p", s: "初九，贲其趾，舍车而徒：贲其趾＝把脚趾（最不起眼处）也装饰得体；舍车而徒＝有车不坐、宁可走路让人看见自己的讲究。这是「饰外」的起点——从细微处讲礼、不虚荣不浮夸。曾仕强说：职场新人、创业初期，不摆排场，从着装整洁、言行礼貌这些小处做起，小处得体、大处守拙。" },
      { t: "p", s: "六二，贲其须：须是胡须，长在脸上、比脚趾显眼，但胡须是「依附脸」才有的——修饰要贴着本质走，里子虚了再美的须也是假的。曾仕强说：六二是阴爻、还没真本事，适当修饰必要，但得赶紧充实自己；光有漂亮外表撑不久。" },
      { t: "p", s: "九三，贲如濡如，永贞吉：濡是润泽。装饰得温润有光、恰到好处（润而不腻），守住正道就吉。曾仕强说：这是最理想的状态——既有真本事又有好形象，但别因外在风光就忘乎所以，要「永贞」。" },
      { t: "p", s: "六四，贲如皤如，白马翰如；匪寇，婚媾：皤（pó）是素白。舍去华丽、骑白马素装疾行，不是来抢（匪寇）而是真诚结合（婚媾）——由文返质、去饰存真、以真诚消敌意。曾仕强说：真正有品位的人穿得很简单，因为不需要靠衣服证明自己；最高级的社交不是华丽包装，而是纯粹真诚。" },
      { t: "p", s: "六五，贲于丘园，束帛戋戋，吝，终吉：丘园是朴素园子，束帛戋戋（jiān，少而薄）是礼轻。把心思花在内里（丘园）、礼轻情意重，外人看着寒酸（吝），终得吉。曾仕强说：做领导的别搞形象工程，把资源用在刀刃上；对家人，贲不必奢华，真心最简。" },
      { t: "p", s: "上九，白贲，无咎：白贲＝素白无纹的装饰，最高级的装饰是不装饰。回到本质、返璞归真，无咎。曾仕强说：贲极反本——所有装饰的尽头，是「本来面目」；《论语》「素以为绚兮」，最美丽的装饰是不需要装饰。" },

      { t: "h", s: "四、生活案例：怎么用贲卦准备一场重要面试/汇报" },
      { t: "case", title: "面试/汇报前，怎么用贲卦把「里子」和「面子」都做好？", s: "假设你下周要参加一场重要面试（或工作汇报），用贲卦的思路，比只埋头准备或只纠结穿搭都高明。第一，先质后文——曾仕强说顺序不能颠倒：先把专业内容、案例数据（里子）练扎实，别本末倒置地花三天挑西装、却没空复习业务。第二，初九贲其趾——小处得体：简历排版清爽、准时到场、握手有力、衣着干净合身，这些「脚趾级」的细节最显教养，不虚荣不浮夸。第三，九三贲如濡如——润而有度：表达时语速适中、举例生动但不炫技，让形象（文）衬出实力（质），润而不腻。第四，千万别走到六二贲其须的反面——空有光鲜皮囊、一问三不知，那层「胡须」立刻露馅。第五，最高招学上九白贲：面试临近，把最花哨的配饰摘掉、回归干净本真，让面试官记住的是「你这个人」而不是「你的行头」——这就是贲的最高境界「看不出刻意修饰」。曾仕强说：贲是软实力工程，先正骨再美容；你每多一分得体、少一分浮夸，就是在把「文质彬彬」过成自己的样子。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住贲卦", items: [
        "画面法：默念「山火贲」——上面艮（山、小儿子、安静稳重），下面离（火、二女儿、光明文采），山下有火就是「文明的火光把本质照得更美」；跟噬嗑（火雷噬嗑·动法治的牙）放一起想：噬嗑把障碍咬碎使其合（武治），贲给这个合以美（文饰），一个刚一个柔、一对综卦。",
        "核心句：贲核心是「文质彬彬·适度为美」——卦辞「小利有攸往」（装饰是辅助、只小利），大象「明庶政、无敢折狱」（日常可美化、断案不能粉饰）；记住孔子「质胜文则野、文胜质则史」和曾仕强那句「越空虚越需要装饰」，里子为主、面子为辅。",
        "阶梯法：记住初九「贲其趾·舍车而徒」（饰外起点·小处得体）和上九「白贲·无咎」（返璞归真·无饰之饰）——从脚趾的刻意打扮，一路走到素白无纹的本色；中间六二到六五是从外饰到内修、由繁归简的「贲饰六阶」，把贲想成一个人从爱打扮到活通透的成长。"
      ]},
      { t: "p", s: "曾仕强说：贲卦是「软实力」的智慧——噬嗑把障碍咬碎、立住刚骨，贲给刚骨披上文明的衣。你每多一分得体、少一分浮夸，就是在亲手把「文质彬彬，然后君子」过成自己的日子。" },

      { t: "quiz", questions: [
        { type: "choice", q: "贲卦的卦象「山火贲」是怎么叠出来的？", options: ["上艮（山）下离（火）", "上离下艮", "上坎下坤", "上乾下坤"], answer: 0, explain: "贲上卦艮（山、小儿子、止而稳），下卦离（火、二女儿、明而文），叫山火贲、六十四卦第22卦；顺《序卦传》「物不可以苟合而已，故受之以贲」，紧接第21卦噬嗑。" },
        { type: "choice", q: "卦辞「贲，亨；小利有攸往」和大象「明庶政，无敢折狱」想告诉我们什么？", options: ["装饰越多越好", "装饰是辅助只「小利」、本质为主；日常政务可美化，但断案不能靠粉饰是非", "别管形象", "只要里子不要面子"], answer: 1, explain: "贲，亨——适度装饰通达；小利有攸往——装饰是锦上添花、只小利不能大张旗鼓，本质（实力品德）才是根本；大象明庶政（把日常治理做得有文明美感）、无敢折狱（法治直指本质、不粉饰），曾仕强叫「先正骨再美容」。" },
        { type: "choice", q: "初九「贲其趾，舍车而徒」和上九「白贲，无咎」给我们有什么提醒？", options: ["越华丽越好", "初九从小处得体、不虚荣（饰外起点），上九返璞归真、无饰之饰（最高境界）；从爱打扮走到活通透", "别装饰", "只穿名牌"], answer: 1, explain: "初九贲其趾＝连脚趾都装饰得体、有车不坐宁可走（小处讲礼、接地气）；上九白贲＝素白无纹、返璞归真（无咎）；曾仕强：贲饰六阶从「贲其趾」一路走到「白贲」，是每个人从注重外表到回归本真的成长，最高级的装饰是看不出装饰。" },
        { type: "say", q: "请用「质胜文则野、文胜质则史、文质彬彬然后君子」说说你生活里一个「里子和面子没平衡好」的例子（穿衣打扮、朋友圈人设、汇报 PPT、待人接物都行）：是「质不够」还是「文过头」？如果用贲卦，你会怎么调回「文质彬彬」？", model: "我有个反面例子：上个月做小组汇报，我把 PPT 做得花里胡哨——满屏动画、荧光色标题、封面还加了本人艺术照，结果讲的时候数据没吃透、被老师追问两个关键指标当场卡壳。这就是贲卦说的「文胜质则史」——外表（文）盖过了内容（质），显得浮、不踏实，像六二「贲其须」：胡须漂亮可脸（里子）是空的。如果用贲卦，我会先把汇报的核心数据、逻辑（质）啃扎实，PPT 只做干净清晰的排版（初九贲其趾·小处得体），去掉那些炫技动画和艺术照，最后学上九「白贲」——让老师和同学记住的是我的分析本身，而不是花哨的壳。曾仕强说顺序不能颠倒：先质后文。我那次就是本末倒置了，下次一定先把里子练厚，面子点到为止。" }
      ]}
    ]
  },
  {
    id: 23,
    title: "第23课 · 剥卦：山地剥，怎么在走下坡路时稳住、做减法",
    subtitle: "曾仕强说：贲极剥始，剥是系统瘦身——顺势退守、厚下安宅、剥极必复",
    review: "上节课我们认识了贲卦——山火贲。上面是艮（山、小儿子、安静稳重），下面是离（火、二女儿、光明文采），山下有火、火映山纹，教我们「文质彬彬」——里子（本质）为主、面子（装饰）为辅；卦辞「小利有攸往」点明装饰只是锦上添花、不能大张旗鼓，大象「明庶政、无敢折狱」是日常可美化、断案不能粉饰，六爻「贲饰六阶」从初九贲其趾（小处得体）一路走到上九白贲（返璞归真、看不出装饰），核心是孔子的「质胜文则野、文胜质则史」。最关键的是曾仕强那句「越空虚越需要装饰」——真正的美来自内心充实。他还留了个钩子：装饰到极致，就空了。《序卦传》说「贲者饰也，致饰然后亨则尽矣，故受之以剥，剥者，剥也」——你把外表打扮到顶了，再往前就只剩「剥落」：浮华褪去、露出里子。今天，我们来到第23卦——剥卦。贲是给合以美，剥是让美褪去、返见本质，一个文饰、一个瘦身，正好配成一对。",
    blocks: [
      { t: "h", s: "一、剥长啥样：山趴在地上，根基被一点点啃掉" },
      { t: "p", s: "上节课的贲卦是山火贲（上艮下离）。今天的剥卦，上下又换了：上面还是艮（山、小儿子、安静止住），下面换成坤（地、母亲、顺承载着），叫「山地剥」。它是六十四卦里的第23卦。" },
      { t: "p", s: "顺《序卦传》的逻辑：贲是把表面润色到极致（致饰然后亨则尽矣），再往前走就空了，于是出现剥——剥落、侵蚀、把浮华一层层扒掉，返见本质。曾仕强把剥卦叫「系统瘦身与风险出清」：不是坏事，是逼你卸掉包袱、腾地方给新生。" },
      { t: "p", s: "你想象一座山，本来高高立着，可底下的地（坤、承载）一点点被雨水冲刷、被掏空，山脚松了、山体开始往下塌——这就是「山附于地，剥」。山看着还在，根已经虚了。生活里：一段关系在变淡、一个项目在下滑、你的精力在悄悄透支，都是「剥」——不是突然崩，是慢慢掉。" },
      { t: "p", s: "剥卦最特别的地方：五个阴爻、只有一个阳爻（在最顶上、上九）。五个阴（小人居多、势头向下）包围着孤零零的一点阳（君子、仅存的正气）。这就像走下坡路时，坏人得势、好人被挤到角落——但不能慌，那一点阳要守好，等着它再长回来。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：剥卦「山地剥」，上面是艮（山、小儿子），下面是坤（地、母亲），第1课我们讲过「一家八口」——艮是小儿子、坤是母亲，这一课轮到他俩搭伙。上面山（安静、止住、守住），下面地（顺、承载、包容），山趴在地的背上，地一松山就塌——演的就是「根基不动、上面才稳」的戏。对照上节课贲卦（上艮下离＝小儿子和二女儿）：贲是山下有火（把本质照美），剥是山附于地（根基才是命）；一个讲「美」、一个讲「本」，贲极剥始，正好接上。" },
      { t: "p", s: "记住这张八卦图：剥卦的核心是「根基为本」。上艮（山）下坤（地）叠成山地剥，山附于地、地松则山崩；它要的不是扩张，而是回头看脚下——把地基护住，才是活路。" },

      { t: "h", s: "二、剥讲什么：不利有攸往，厚下安宅（卦辞+大象）" },
      { t: "p", s: "剥卦的卦辞只有五个字：「剥，不利有攸往。」不利有攸往＝这时候不适合再往前冲、再扩张、再折腾。曾仕强说：这不是叫你躺平放弃，而是衰退期不可逆，你硬着头皮上、只会加速崩——宜静守、止损、减损、固本，动则凶、守则安。" },
      { t: "p", s: "大象传最有分量：「山附于地，剥；上以厚下安宅。」上以厚下＝在上位的人（领导、长辈、也包括「现在的你」）要主动削自己、加厚基层——把资源、关心、底气给到底层（员工、孩子、自己的身体）；安宅＝地基稳了，屋子才不倒，才能扛过这一轮剥蚀。曾仕强点得直白：「一个人的身体就是他的宅啊！先把自己养好，一切才有可能。」" },
      { t: "p", s: "彖传一句话把天道说透：「剥，剥也，柔变刚也……顺而止之，观象也。君子尚消息盈虚，天行也。」柔变刚＝阴气一点点吃掉阳气（小变大事）；顺而止之＝顺着往下、该停就停；消息盈虚＝消长、盈满、空虚，本是天道的循环。曾仕强总结：盛衰是规律，没有永远的巅峰也没有永远的低谷，识势才能避险。" },
      { t: "p", s: "关键要分清：剥不是「败落」的同义词，而是「强制体检」——越早主动剥去浮华、削薄上层、加厚根基，越能把「崩山之势」变成「扫地除尘」，给下一轮复卦（一阳来复）腾空场地。曾仕强提醒：剥极必复≈否极泰来，寒冬过后必是春天。" },

      { t: "h", s: "三、剥六条线：从「剥床以足」到「硕果不食」的瘦身六阶" },
      { t: "p", s: "剥六条爻，曾仕强叫它「六步瘦身链」，侵蚀由浅入深、应对由防到守。从下往上读：" },
      { t: "p", s: "初六，剥床以足，蔑贞凶：床脚（最底层、根基）先被蛀空，你却蔑视它（不当回事）、不守正道，必凶。曾仕强说：公司的崩，常从砍基层福利开始；人的崩，常从熬夜、敷衍这些「小事」开始。防微杜渐，早固根基——千里之堤溃于蚁穴。" },
      { t: "p", s: "六二，剥床以辨，蔑贞凶：辨是床板（中层、中间关系/能力），剥到这里问题公开化、上下脱节，仍不守正，凶更重。曾仕强说：衰退期别硬扛，要顺势调整、修复关系、补上短板，孤立无援只会加速衰败。" },
      { t: "p", s: "六三，剥之，无咎：这一爻独独和上九那点阳相应——在人人都跟着往下掉的环境里，你选择主动剥去浮华、不随波逐流，反而无咎。曾仕强说：这是「做减法」的最高智慧——主动砍掉亏损项目、无效社交、坏情绪，断舍离害，反而安稳。" },
      { t: "p", s: "六四，剥床以肤，凶：剥到床面（贴着肌肤、核心利益/健康/感情），灾祸迫在眉睫，凶。曾仕强说：触及根本时，必须壮士断腕，再不舍就全盘皆输——危机临头，果断断舍。" },
      { t: "p", s: "六五，贯鱼，以宫人宠，无不利：像鱼一条接一条成串游、宫人依次受宠，有序、柔顺、不争不抢，成批而稳妥地处理冗余，转凶为利。曾仕强说：衰退期收敛锋芒、低调配合、团结众人，以柔护阳——不争是争、不退是守。" },
      { t: "p", s: "上九，硕果不食，君子得舆，小人剥庐：枝头仅存的那个大果实（唯一的阳、你的核心/初心/健康/信誉）别急着吃掉、别折腾它；君子守住它，众人像车载你一样拥护你（得舆），小人贪得无厌连屋顶都扒光（剥庐）、自毁根基。曾仕强说：衰退期最大的成功，是守住那一线生机——硕果是剥极必复的火种。" },

      { t: "h", s: "四、生活案例：怎么用剥卦面对「一个在走下坡路的小组/人缘」" },
      { t: "case", title: "你带的兴趣小组最近人气在掉，怎么用剥卦稳住房子不塌？", s: "假设你是某个兴趣小组的负责人，这学期招新惨淡、老成员也陆续退群，小组明显在「剥」。用剥卦的思路，比硬撑着办活动、刷存在感高明得多。第一，初六剥床以足——别忽视小信号：最早是两三个人开会请假、群消息没人回（床脚松了），你当时觉得「没事」没管，现在塌了才慌；防微杜渐，早一点私聊关心、把根基补上。第二，上以厚下安宅——别只顾着对外宣传（剥面子），先把还在的核心成员照顾好：多听他们的想法、把活动做精不做大，地基稳了屋子才不倒。第三，六三剥之无咎——主动做减法：砍掉没人来的「打卡水群」、那个华而不实的海报，把精力留给真正想留的人，反而轻松无咎。第四，六五贯鱼——别跟别的组恶性竞争抢人（不争），低调把现有的人团结好、有序运转，无不利。第五，千万别学小人剥庐——别为了挽留数据就乱承诺、透支信誉，那会连屋顶都掀了；要学上九硕果不食：守住小组「本来为什么聚在一起」的那个初心（硕果），等下一届招新季（剥极必复）再起来。曾仕强说：剥是系统瘦身——你每多一分顺势退守、少一分硬撑，就是在把「厚下安宅、剥极必复」过成自己的日子。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住剥卦", items: [
        "画面法：默念「山地剥」——上面艮（山、小儿子、止而稳），下面坤（地、母亲、顺而载），山趴在地背上就是「根基松了上面才塌」；跟贲卦（山火贲·山下有火照美）放一起想：贲把本质照美（文饰）、剥把浮华扒掉（瘦身），一个美一个本、一对前后卦，贲极剥始。",
        "核心句：剥核心是「顺势退守·厚下安宅」——卦辞「不利有攸往」（衰退期不冒进、宜减损固本），大象「上以厚下安宅」（上位者削自己、厚待基层、护住根基）；记住曾仕强「身体就是宅」和「剥极必复≈否极泰来」，下坡路不是终点。",
        "阶梯法：记住初六「剥床以足（根基先蚀·防微杜渐）」和上九「硕果不食（守住一线生机·待复）」——从床脚被蛀到守住枝头硕果，中间六二到六五是从浅蚀到深危、由硬扛到柔顺的「瘦身六阶」，把剥想成一个人从忽视小毛病到学会断舍离、守住本心的过程。"
      ]},
      { t: "p", s: "曾仕强说：剥卦是「止损与守根」的智慧——贲把外表打扮到顶，剥把浮华扒掉、返见本质。你每多一次顺势退守、多一分厚待根基，就是在亲手把「剥极必复、一阳来复」过成自己的日子。" },

      { t: "quiz", questions: [
        { type: "choice", q: "剥卦的卦象「山地剥」是怎么叠出来的？", options: ["上艮（山）下坤（地）", "上坤下艮", "上艮下离", "上乾下坤"], answer: 0, explain: "剥上卦艮（山、小儿子、止而稳），下卦坤（地、母亲、顺而载），叫山地剥、六十四卦第23卦；顺《序卦传》「致饰然后亨则尽矣，故受之以剥」，紧接第22卦贲卦。" },
        { type: "choice", q: "卦辞「剥，不利有攸往」和大象「上以厚下安宅」想告诉我们什么？", options: ["赶紧跑路放弃", "衰退期不宜冒进扩张，宜减损固本；上位者要削自己、厚待基层、护住根基才稳", "越衰越要猛冲", "只管自己"], answer: 1, explain: "不利有攸往＝下坡路不可逆势硬上，动则凶、守则安；上以厚下安宅＝在上的人主动让利、夯实基层（企业稳员工、家庭固感情、个人养身体这个「宅」），根基稳才能扛过剥蚀；曾仕强说身体就是宅。" },
        { type: "choice", q: "初六「剥床以足，蔑贞凶」和上九「硕果不食，君子得舆，小人剥庐」给我们有什么提醒？", options: ["小问题不用管", "初六根基从脚被蛀、忽视小恶必酿凶（防微杜渐）；上九守住枝头硕果（一线生机）得众人载覆，贪尽则自毁屋顶（剥庐）", "越贪越好", "别守底线"], answer: 1, explain: "初六剥床以足＝侵蚀从最底层开始，轻视小问题必凶，千里之堤溃于蚁穴；上九硕果不食＝衰退期守住核心/初心/健康/信誉那点阳，君子得舆（众人拥护）、小人剥庐（连屋顶都扒光自毁）；曾仕强：剥极必复，守得住硕果才有转机。" },
        { type: "say", q: "请用「不利有攸往（下坡路不硬撑）」和「厚下安宅（护住根基）」说说你生活里一个「正在走下坡路却还在硬撑」的事（一段变淡的关系、一个人气掉的小组、被你拖垮的作息/成绩都行）：它从哪个「小地方」开始剥的？如果用剥卦，你会怎么「做减法、厚下安宅」等它剥极必复？", model: "我有个反面例子：上学期我当寝室长，起初大家还一起打扫、约饭，后来有两个室友开始熬夜打游戏、不倒垃圾，我嫌麻烦没说（这就是初六剥床以足——根基从「小规矩」被蛀，我蔑视它没管），慢慢全寝室卫生崩了、关系也冷。我还硬撑着在班会上说「我们寝特团结」，其实就是贲极剥始、粉饰太平。如果用剥卦，我学「不利有攸往」——不硬撑面子，先承认在下滑；再学「上以厚下安宅」——别光对外表负责，把根基（和室友的真实沟通、轮流值日的小制度）补上，主动砍掉「装团结」的表演，私下约他俩聊聊、把值日表做简单；守住「室友本该互相照应」这颗硕果，等大家期末不忙了（剥极必复）关系自然回温。曾仕强说剥是系统瘦身：早主动剥去浮华、加厚根基，比崩了再救强一百倍。" }
      ]}
    ]
  },
  {
    id: 24,
    title: "第24课 · 复卦：地雷复，怎么在跌到谷底时绝处逢生",
    subtitle: "曾仕强说：剥极必复，复是纠错之卦、复兴之卦——不远复，一阳来复",
    review: "上节课我们认识了剥卦——山地剥。上面是艮（山、小儿子、安静止住），下面是坤（地、母亲、顺承载着），山趴在地背上、地一松山就塌，教我们「顺势退守、厚下安宅」——衰退期不硬撑、把浮华扒掉、护住根基；卦辞「不利有攸往」（下坡路不冒进），大象「上以厚下安宅」（身体就是宅），六爻「瘦身六阶」从初六剥床以足（防微杜渐）一路走到上九硕果不食（守住一线生机·剥极必复），核心是一句「剥极必复≈否极泰来」。最关键的是曾仕强那句：剥不是败落、是强制体检，守住那点阳，等它再长回来。《序卦传》说「剥穷上反下，故受之以复」——剥把上面剥到尽头，那一阳就掉回最底下，重新冒头。今天，我们来到第24卦——复卦。剥是往下掉，复是往上回；一个剥落、一个复兴，正好配成一对。",
    blocks: [
      { t: "h", s: "一、复长啥样：雷藏在地底下，一线生机冒头了" },
      { t: "p", s: "上节课剥卦是山地剥（上艮下坤）。今天的复卦，上下又换了：上面变成坤（地、母亲、顺承载着），下面换成震（雷、长子、动而新生），叫「地雷复」。它是六十四卦里的第24卦，紧接剥卦。" },
      { t: "p", s: "顺《序卦传》的逻辑：剥把上面一路剥到尽头（剥穷上反下），唯一那点阳从最顶掉回最底（初九），重新冒头——这就是「剥极必复、一阳来复」。曾仕强说：物不可以终尽，再怎么剥也剥不完，天无绝人之路。" },
      { t: "p", s: "你想象：冬天的大地，表面冰封一片、五阴（黑暗、衰败）压顶，可地底下有雷（震、阳气）在悄悄震动、一点点往上顶——雷在地中。外头看着还是冷，但你知道，春天要来了。生活里：你跌到谷底、考试崩了、项目黄了、关系凉了，看着全黑，其实最底下的那点劲（初心、体力、朋友）正在回血，这就是复。" },
      { t: "p", s: "复卦最特别：五个阴爻、一个阳爻，但阳爻在最底下（初九），不在最顶（跟剥卦正好反过来）。这一个小小的阳，是全卦的火种、唯一的希望。曾仕强把它比作「冬天的清晨，太阳还没升起，东方天边已经微微发白」——光很弱，但你知道天要亮了。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：复卦「地雷复」，上面是坤（地、母亲），下面是震（雷、长子），第1课我们讲过「一家八口」——坤是母亲、震是长子，这一课轮到他俩搭伙。上面地（顺、承载、包容），下面雷（动、新生、阳气），雷埋在地底下震动就是「一阳来复、生机暗藏」；对照上节课剥卦（上艮下坤＝小儿子和母亲）：剥是山附于地讲「本」（根基松了塌），复是雷藏于地讲「生」（阳气回底冒头），一个剥落一个复兴，剥极必复，正好接上。" },
      { t: "p", s: "记住这张八卦图：复卦的核心是「一阳来复」。上坤（地）下震（雷）叠成地雷复，雷在地中、阳藏阴下；它要的不是硬扛，而是守住那点刚冒头的生机，等它长大。" },

      { t: "h", s: "二、复讲什么：一阳来复，复兴重启（卦辞+大象）" },
      { t: "p", s: "复卦的卦辞：「复，亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往。」复，亨＝阴极阳生、生机重启，所以通达。出入无疾＝阳气一点点升、阴气一点点退，这个过程自然没毛病，别急；朋来无咎＝你走在正道上，志同道合的人自然来帮你，没过失；反复其道，七日来复＝事物循环往复有周期（一个卦六爻走完一轮、第七是新的开始，所以「六六大顺、逢七必变」），守住周期、不急不躁；利有攸往＝剥卦时「不利有攸往」，现在形势逆转，可以放心往前走了。曾仕强说：剥是收、复是放，一收一放都是天道。" },
      { t: "p", s: "大象传最有画面：「雷在地中，复；先王以至日闭关，商旅不行，后不省方。」冬至一阳生，古人在冬至这天闭关、停商旅、君王不巡视——静养、积蓄、不妄动。现代启示：低谷时先静后动，复盘反思、养精蓄锐，时机成熟再起。曾仕强说：现代人太忙，把「一阳来复」的生机都熬干了；真正的休息，是为了复。" },
      { t: "p", s: "彖传一句话点破天道：「复，其见天地之心乎！」在复卦里，你能看见天地最核心的意志——生生不息、绝处逢生。曾仕强说：老天爷是希望万物活着的，不会让你走到绝路；复卦，就是让你在绝望里看见希望。" },
      { t: "p", s: "关键要分清：复的「复」不是复仇、不是简单重复，是复兴、回复、修复——回归正道、重启新生。曾仕强特别强调：大自然不会报复你，它只是自我修复；野草烧了春天还长，树落叶了明年还发，这就是复。" },

      { t: "h", s: "三、复六条线：从「不远复」到「迷复凶」的复兴六步" },
      { t: "p", s: "复六条爻，曾仕强叫它「复兴六步」，从及时纠错一路走到执迷招灾。主角不是高高在上的君位，是最底下的初九（那点阳、复兴的火种）。从下往上读：" },
      { t: "p", s: "初九，不远复，无祗悔，元吉：走得不远就回头，没大后悔，大吉。全卦最吉、最关键。曾仕强说：犯错别等撞南墙，一看方向偏就立刻停、马上改，损失最小、生机最大；就像开车走错路，别「再走走看」，早问人、早调头。" },
      { t: "p", s: "六二，休复，吉：美好地回头、心甘情愿地回归。六二紧挨初九，受那点阳感召、见贤思齐，不再对抗、主动回归本分。曾仕强说：真正的回归不是被迫妥协，是心安的选择——放下执念、回归初心，吉。" },
      { t: "p", s: "六三，频复，厉，无咎：频繁犯错、反复回头（皱着眉头很痛苦），有危险但终无大害。曾仕强说：戒烟减肥屡败屡战、情绪时好时坏仍修身，反复不可怕，可怕的是放弃；只要每次还愿意回头，终能守住。" },
      { t: "p", s: "六四，中行独复：走在正道中、独自回归，不随波逐流。众阴都跟着往下掉，唯独六四认同那点正道、众人皆醉我独醒。曾仕强说：团队走偏你守原则、世人浮躁你静心，在乱象中守住本心，难得。" },
      { t: "p", s: "六五，敦复，无悔：敦厚诚恳地回归、踏实守正。六五是君位但偏柔，他不阻拦下面复兴、还厚道包容——领导没能力带头，至少别碍事。曾仕强说：敦厚守正、无怨无悔，最高级的回归是发自内心的真诚。" },
      { t: "p", s: "上六，迷复，凶，有灾眚；用行师，终有大败：迷失不知返、执迷不悟，凶、有灾（天灾人祸）；还想动武硬压，必大败、连累国君十年不振。曾仕强说：死不悔改最凶——迷途不返，是人生最大的灾难。" },

      { t: "h", s: "四、生活案例：怎么用复卦在「跌到谷底」时绝处逢生" },
      { t: "case", title: "你这次月考崩了，全班倒数，怎么用复卦把「一阳来复」过成翻盘？", s: "假设这次月考你考崩了，数学全班倒数，看着卷子想撕。用复卦的思路，比躲起来哭、或硬灌三天题都高明。第一，初九不远复——别等期末才改：发现某一类题（函数）一错再错，当场就回头补，不纵容小漏洞成大洞；早调头损失最小。第二，记住卦辞「出入无疾」——别急：复是慢慢回血，别指望三天冲到前几名，按「七日来复」的周期踏实复习，急反而乱。第三，六二休复——找回初心：你当初为什么想考好？把那股劲（初九那点阳）护好，别因一次崩就否定自己。第四，六三频复——允许反复：中间某次小测又掉下来，别崩，只要在改就是在复的路上，无咎。第五，六四中行独复——不随波逐流：同学都在刷短视频摆烂，你独独每天留一小时啃错题本，守住正道。第六，千万别学上六迷复——别考砸了就摔笔说「我不是读书的料」、自暴自弃，那才是真凶。曾仕强说：复是纠错之卦，你每多一次「不远复」、少一次「迷复」，就是在把「一阳来复、剥极必复」过成自己的翻盘。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住复卦", items: [
        "画面法：默念「地雷复」——上面坤（地、母亲、顺承载），下面震（雷、长子、动新生），雷埋在地底下震动就是「一阳来复、生机暗藏」；跟剥卦（山地剥·山附于地讲本）放一起想：剥把浮华扒掉（瘦身），复让阳气回底冒头（复兴），一个剥落一个重生、剥极必复，一对前后卦。",
        "核心句：复核心是「一阳来复·及时纠错」——卦辞「出入无疾，朋来无咎，七日来复，利有攸往」（自然回血别急、朋友来帮、守周期、可往前走），大象「至日闭关」（先静后动、养精蓄锐）；记住曾仕强「复不是复仇是复兴」和「不远复元吉」，低谷不是终点。",
        "阶梯法：记住初九「不远复·无祗悔·元吉」（走不远就回头、最吉）和上六「迷复·凶」（执迷不返最凶）——从刚偏就回头，一路到死不悔改招灾；中间六二到六五是从美好回归到敦厚守正的「复兴六步」，把复想成一个人从知错就改、到独守正道、到迷途知返的对照。"
      ]},
      { t: "p", s: "曾仕强说：复卦是「纠错与复兴」的智慧——剥把你剥到谷底，复让你从最底那点阳重新长起。你每多一次「不远复」、少一次「迷复」，就是在亲手把「一阳来复、万象更新」过成自己的日子。" },

      { t: "quiz", questions: [
        { type: "choice", q: "复卦的卦象「地雷复」是怎么叠出来的？", options: ["上坤（地）下震（雷）", "上震下坤", "上艮下坤", "上乾下坤"], answer: 0, explain: "复上卦坤（地、母亲、顺承载），下卦震（雷、长子、动新生），叫地雷复、六十四卦第24卦；顺《序卦传》「剥穷上反下，故受之以复」，紧接第23卦剥卦。" },
        { type: "choice", q: "卦辞「复，亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往」想告诉我们什么？", options: ["立刻猛冲大干", "阴极阳生重启通达；回血别急、朋友来帮、守周期、可往前走（与剥卦「不利有攸往」相反）", "什么都别动", "躺着等死"], answer: 1, explain: "复，亨＝阴极阳生、生机重启故通达；出入无疾＝阳气渐升自然无碍、别急；朋来无咎＝走正道则志同者自来助；七日来复＝循环有周期（逢七必变）；利有攸往＝形势逆转可放心前行；剥时不利有攸往、复时利有攸往，一收一放皆天道。" },
        { type: "choice", q: "初九「不远复，无祗悔，元吉」和上六「迷复，凶，有灾眚」给我们有什么提醒？", options: ["错了慢慢改就行", "初九走不远就回头、损失最小生机最大（最吉）；上六执迷不返、凶招灾连累他人（最凶）", "拖越久改越好", "千万别回头"], answer: 1, explain: "初九不远复＝一偏就停、立刻改，全卦最吉、纠错要趁早；上六迷复＝死不悔改、执迷不返，凶且有灾（天灾人祸）、动武则大败连累团队；曾仕强：人生不怕跌倒，怕不知回头；不远复是最高智慧，迷复是最大灾难。" },
        { type: "say", q: "请用「不远复（走不远就回头）」和「一阳来复（守住刚冒头的那点生机）」说说你生活里一个「跌到谷底或刚犯了个错」的事（一次考砸、一段凉了的关系、一个搞砸的任务都行）：你当时是「不远复」还是「迷复」？如果用复卦，你会怎么守住那点阳、等它七日来复地翻回来？", model: "我有个反面例子：上学期我和最好的朋友吵架，明明是我说话冲了点，但我赌气不先低头（这就是上六迷复——执迷不悟、不肯回头），结果一个月没说话、关系凉透，两边都难受。其实刚吵完那天，我心里就知道是我欠妥，但面子挂不住（迷复）。如果用复卦，我学初九「不远复」——别等闹了一个月，当天晚上就发条消息道个歉、把话挑明，损失最小、友情立刻回温（无祗悔元吉）。再学「一阳来复」——我们之间那点情分（初九那点阳）还在，别因为一次架就判它死刑；护住它、主动一点，按「七日来复」的节奏，过几天自然就和好了。曾仕强说复不是复仇是复兴：我不是要「赢」这次架，是要把这段关系复兴回来。早回头一天，少难过三十天。" }
      ]}
    ]
  },
  {
    id: 25,
    title: "第25课 · 无妄卦：天雷无妄，怎么守住正道、不瞎折腾",
    subtitle: "曾仕强说：复则不妄，无妄是不妄想不妄动不妄为——守正至诚，方能避灾得福",
    review: "上节课我们认识了复卦——地雷复。上面是坤（地、母亲、顺承载着），下面是震（雷、长子、动而新生），雷藏在地底下、一阳来复，教我们「一阳来复、及时纠错」——跌到谷底别慌，守住那点刚冒头的生机，不远复、剥极必复；卦辞「出入无疾，朋来无咎，七日来复，利有攸往」（回血别急、朋友来帮、守周期、可往前走），大象「至日闭关」（先静后动、养精蓄锐），六爻「复兴六步」从初九不远复（走不远就回头、最吉）一路走到上六迷复（执迷不返、最凶），核心是曾仕强那句「复不是复仇是复兴」。最关键的是：复卦让你从最底那点阳重新长起、长出正道来了，那下一步怎么守住它、别又跑偏？《序卦传》说「复则不妄矣，故受之以无妄」——你回到了正道，就不再瞎折腾了，这时候就轮到无妄。今天，我们来到第25卦——无妄卦。复是回归正道，无妄是守住正道、不滋生妄念；一个回头、一个守成，正好配成一对。",
    blocks: [
      { t: "h", s: "一、无妄长啥样：雷在天下轰隆隆，谁还敢乱来" },
      { t: "p", s: "上节课复卦是地雷复（上坤下震）。今天的无妄卦，上下又换了：上面变成乾（天、爸爸、刚健天道），下面还是震（雷、长子、动而新生），叫「天雷无妄」。它是六十四卦里的第25卦，紧接复卦。" },
      { t: "p", s: "顺《序卦传》的逻辑：复让你回到正道（复则不妄矣），正道走顺了，最怕的就是「得意忘形、又开始瞎折腾」——无妄卦就是给你一本「安全驾驶手册」：循正道、守天时，别乱动。曾仕强说：复是回归，无妄是守住，一个人若能不远复，自然就走上无妄。" },
      { t: "p", s: "你想象：天上（乾）雷声轰隆隆地滚过整片大地（震），到处都是雷在响、在动——「天下雷行」。地上万物一听雷响，全都吓住了，谁还敢乱跑乱动？就像军事禁区外围布满了地雷，你敢到处乱闯吗？这种卦象告诉我们：此时此地都有规矩、有警戒，做事得小心翼翼、不能胡来。曾仕强讲得很形象：无妄就是「到处是雷的禁区」，提醒你——别妄动。" },
      { t: "p", s: "无妄卦最特别：它五个阳爻、只有一个阴爻（六三），阳多阴少、刚健为主。跟复卦（一阳在底、阴盛阳微）正好反着来——复是「生机刚冒头要护住」，无妄是「阳气已经旺了、最怕你飘」。这一个孤零零的阴（六三），就是全卦的「漏洞」：你守正守得好，它没事；你一放松，灾就从这儿来。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：无妄卦「天雷无妄」，上面是乾（天、爸爸），下面是震（雷、长子），第1课我们讲过「一家八口」——乾是父/爸爸、震是长男/长子，这一课轮到父子搭伙。上面天（刚健、天道、规矩），下面雷（动、震惧、行动），雷在天下轰隆隆震动就是「万物不敢妄为、动必循理」；对照上节课复卦（上坤下震＝母亲和长子）：复是雷藏于地讲「生」（一阳来复、生机回底），无妄是雷行于天讲「正」（雷在天下震、万物不敢妄动）；一个复兴一个守正，复则不妄，正好接上。" },
      { t: "p", s: "记住这张八卦图：无妄的核心是「守正不妄」。上乾（天）下震（雷）叠成天雷无妄，天下雷行、雷震万物；它要的不是硬闯，而是守住正道、不妄想不妄动，雷声响着你反而更稳。" },

      { t: "h", s: "二、无妄讲什么：守正就通，不正就灾（卦辞+大象）" },
      { t: "p", s: "无妄卦的卦辞：「无妄，元亨利贞；其匪正有眚，不利有攸往。」元亨利贞＝只要你守正、动机纯、不胡来，就四德俱全、诸事顺遂、大可畅通。其匪正有眚＝「匪正」就是偏离正道，只要有那么一点点不正当的念头或做法，立刻就有灾（眚＝人祸、毛病）；不利有攸往＝不正的时候还要硬往前走、妄动冒进，必撞南墙。曾仕强说：无妄卦最狠的地方是「零容忍」——别人卦还讲点变通，它是一偏就灾，逼你时刻守正。" },
      { t: "p", s: "大象传最有分量：「天下雷行，物与无妄；先王以茂对时，育万物。」茂对时＝茂盛生长必须对准天时（你种庄稼得看节气，不能冬天硬要插秧）；育万物＝先王只负责顺时培育、不揠苗助长。曾仕强点得直白：雷声顺时而发、万物顺势而生，做人做事就要安分守己、顺应天时、不贪求不造作——该动时动、该停时停。" },
      { t: "p", s: "彖传把天道说透：「刚自外来而为主于内，动而健……大亨以正，天之命也。」无妄的内卦震（动）配上外卦乾（健），动而能健、刚中而应，所以大亨以正——这是天命。曾仕强总结：无妄不是叫你「什么想法都别有」，而是叫你「别存妄念」——不妄想不劳而获、不妄动逆势而为、不妄求非分之利、不妄语乱讲话。" },
      { t: "p", s: "关键要分清：无妄之「妄」，不是「想法」，是「虚妄、不正当、偏离正道」。曾仕强特别提醒三种最隐蔽的妄：一是不知不觉做坏事（自己都没意识到偏了），二是好心做坏事（出发点是好意、一出手却惹祸），三是狂妄——舍本逐末、用奇装异服狂言乱语博眼球。所以无妄卦一上来就劝你「修口德、不妄语」，人最大的毛病就是乱讲话。" },

      { t: "h", s: "三、无妄六条线：从「无妄往吉」到「无妄行灾」的守正六检" },
      { t: "p", s: "无妄六条爻，曾仕强叫它「无妄六检」——每一步都在问你：你动得正不正？从下往上读：" },
      { t: "p", s: "初九，无妄，往吉：出发点纯正、毫无妄念，一动机就吉祥。全卦最吉。曾仕强说：创业动机纯粹、踏实做事不投机，起步就顺；做人内心真诚、待人坦荡不虚伪，关系就和谐——无妄之始，贵在真诚无伪，初心纯正，动则吉祥。" },
      { t: "p", s: "六二，不耕获，不菑畬，则利有攸往：不耕而想收、不开荒就想要熟田，必无所获；反过来，只管踏实耕耘、不图非分回报，就利有攸往。曾仕强说：这是「只管耕耘、莫问收获」——工作认真履职不急着求回报、学习日积月累不偷懒、感情真诚付出不控制，不妄求非分，反而得长远之利。" },
      { t: "p", s: "六三，无妄之灾，或系之牛，行人之得，邑人之灾：这爻最扎心——你明明守正无过，却遭意外牵连之灾，像有人把别家的牛拴在路边、被路人牵走，无辜的村民倒被怀疑是贼。这就是成语「无妄之灾」的出处。曾仕强说：世事无常，即便守正也难免飞来横祸；守正之余要谨言慎行、防患未然，坦然面对——无妄之灾是上天的考验，守正不变就是最好的应对。" },
      { t: "p", s: "九四，可贞，无咎：位置得当，坚守正道、不随波逐流，守正自持、不妄动，可免灾祸。曾仕强说：诱惑面前坚守底线不贪不义之财、乱象之中保持清醒不盲从跟风、困境之时稳守本心不急躁冒进——无妄之要，贵在坚守正道不动摇。" },
      { t: "p", s: "九五，无妄之疾，勿药有喜：守正之人偶有小疾（意外小麻烦），不必刻意强求、盲目应对，静养自愈、自有转机。曾仕强说：偶有小不适不必乱吃药过度治疗、遇小挫折不必焦虑盲目调整——至诚能化小灾，静养自有转机；无妄之疾，忌妄治、忌急躁。" },
      { t: "p", s: "上九，无妄，行有眚，无攸利：虽守正无妄，但时位已极、大势已过，此时还妄动必招灾祸、无利可图。曾仕强说：巅峰已过、盛极将衰，仍盲目扩张折腾必遭损失；时机错过、大势已去还逆势强进，徒劳无功——时止则止，知止不殆；无妄之终，贵在识势知止、不妄行。" },

      { t: "h", s: "四、生活案例：怎么用无妄卦面对「飞来横祸」和「想瞎折腾」" },
      { t: "case", title: "你踏实上班，却被同事甩锅背了黑锅，怎么用无妄卦既认栽又不崩？", s: "假设你在公司踏踏实实干活，从不惹事，结果有个项目出了问题，明明是另一个同事的疏漏，领导却误以为是你负责的，当众把你批了一顿、奖金也扣了。你冤得要死。用无妄卦的思路，比当场拍桌子吵架、或赌气摆烂都高明。第一，先认下「无妄之灾」——六三这爻说的就是：你守正无过，却遭意外牵连，像牛被路人牵走、村民背锅。这不是你的错，但你得先坦然接住，别急着喊冤叫屈、越描越黑（妄动反而招更多灾）。第二，继续「可贞无咎」（九四）——你还是守住本分、把活干好、不跟着别人一起甩锅或摆烂，时间一长领导自然看清谁是谁。第三，别学上九「无妄行有眚」——别因为委屈就冲动辞职、或在群里发飙泄愤，时位不对、你硬动只会增加损失。第四，用「茂对时」的智慧——等合适的时机（比如月度复盘）再平平静静把事实摆出来，不抢不闹、顺时而为。第五，回到初心——你本来就是想好好做事的人（初九无妄往吉），别因为一次冤枉就变成自己也瞎折腾的人。曾仕强说：无妄之灾是上天的考验，守正不变就是最好的应对；你每多一分「不妄动、守正待时」，就是在把「元亨利贞、无灾无难」过成自己的日子。还有一个对照：如果你正相反——是自己飘了、想走捷径搞点「小动作」捞好处，那无妄卦的警钟就是「其匪正有眚」：偏一点点，灾就来了，趁早收手。" },

      { t: "h", s: "五、记忆妙招（三招就够）" },
      { t: "mnemonic", title: "三招记住无妄卦", items: [
        "画面法：默念「天雷无妄」——上面乾（天、爸爸、刚健天道），下面震（雷、长子、动而震惧），雷在天下轰隆隆滚过、万物不敢乱动就是「守正不妄、动必循理」；跟复卦（地雷复·雷藏地底讲生）放一起想：复把阳气护回底、无妄把正道守在天，一个复兴一个守正、复则不妄，一对前后卦。",
        "核心句：无妄核心是「守正至诚·不妄想不妄动不妄为」——卦辞「元亨利贞，其匪正有眚，不利有攸往」（守正则通、偏一点就灾、不正莫妄动），大象「茂对时育万物」（对准天时、不揠苗助长）；记住曾仕强「无妄之灾是上天考验、守正就是最好应对」，以及「修口德不妄语」。",
        "阶梯法：记住初九「无妄往吉」（初心纯正一动机就吉）和上九「无妄行有眚」（时位已极仍妄动必灾），中间六二到九五是「只管耕耘（不耕获）」「飞来横祸坦然接（无妄之灾）」「坚守不盲从（可贞）」「小毛病静养（无妄之疾）」的守正六检，把无妄想成一个人从纯正出发、到识势知止、不瞎折腾的全程。"
      ]},
      { t: "p", s: "曾仕强说：无妄卦是「守正与止妄」的智慧——复让你回到正道，无妄让你守住正道、不滋生妄念。你每多一次「守正不妄」、少一次「妄动招灾」，就是在亲手把「元亨利贞、无灾无难」过成自己的日子。" },

      { t: "quiz", questions: [
        { type: "choice", q: "无妄卦的卦象「天雷无妄」是怎么叠出来的？", options: ["上乾（天）下震（雷）", "上震下乾", "上乾下坤", "上坤下震"], answer: 0, explain: "无妄上卦乾（天、爸爸、刚健天道），下卦震（雷、长子、动而新生），叫天雷无妄、六十四卦第25卦；顺《序卦传》「复则不妄矣，故受之以无妄」，紧接第24卦复卦。" },
        { type: "choice", q: "卦辞「无妄，元亨利贞；其匪正有眚，不利有攸往」想告诉我们什么？", options: ["守正则通、偏一点就灾、不正莫妄动", "怎么都行随便动", "越偏越旺", "什么都不做最安全"], answer: 0, explain: "元亨利贞＝守正动机纯就四德俱全通顺；其匪正有眚＝偏离正道哪怕一点点立刻有灾（眚＝人祸）；不利有攸往＝不正时还硬往前妄动必撞南墙；曾仕强说无妄卦零容忍、逼你时刻守正。" },
        { type: "choice", q: "六三「无妄之灾，或系之牛，行人之得，邑人之灾」给我们什么提醒？", options: ["守正也难免飞来横祸，坦然接住、守正不变", "守正就绝对安全", "赶紧报复回去", "干脆别守正了"], answer: 0, explain: "六三＝你守正无过却遭意外牵连（牛被路人牵走、村民背锅），成语「无妄之灾」出处；曾仕强：世事无常即便守正也难免飞来横祸，要谨言慎行防患未然、坦然面对，守正不变就是最好应对；它不是叫你放弃守正，而是叫你不被横祸带偏。" },
        { type: "say", q: "请用「不妄动、守正待时」和「无妄之灾要坦然接住」说说你生活里一个「飞来横祸或想走捷径」的事（被冤枉背锅、考试失常、想抄近道投机都行）：当时你是妄动了还是守住了？如果用无妄卦，你会怎么「守正不妄、识势知止」把这一关过成元亨利贞？", model: "我有个反面例子：去年我想快点攒钱，朋友拉我搞一个「稳赚」的副业，说是投一点就能翻倍。我心里其实知道这不太对（这就是其匪正有眚——偏了一点），但贪心作祟还是投了，结果平台跑路、钱没了，还连累我那阵子上课都心不在焉（妄动招灾）。其实当初只要守住「不妄求非分之利」这一条，根本不会踩坑。如果用无妄卦，我学初九「无妄往吉」——出发前先问初心：这钱来得正不正？不正就别动，纯正好奇也不碰。再学九四「可贞无咎」——哪怕周围人都说「错过这村没这店」，我也坚守底线不盲从。还有一次正面例子：有回小组作业，队友把锅甩给我，我被老师点名批评（这就是六三无妄之灾——守正无过却背锅）。当时我差点当场翻脸，但忍住了、事后私下找老师把事实说清（茂对时、顺时而为），没妄动、没撒谎，最后老师反而更信任我。曾仕强说无妄之灾是上天考验：你守正不变，就是最好的应对。两次对照让我记住——妄念一动，灾就近；守正不动，福自来。" }
      ]}
    ]
  },
  {
    id: 26,
    title: "第26课 · 蓄势待发：山天大畜",
    subtitle: "曾仕强说：小畜积财，大畜积德",
    review: "上节课我们学了无妄卦（天雷无妄），核心就四个字——守正不妄。复卦让你回到正道，无妄卦让你守住正道、不滋生妄念；不妄动、守正待时，连飞来横祸（无妄之灾）也要坦然接住。今天顺着《序卦传》「有无妄然后可畜，故受之以大畜」往下走，来学六十四卦里的第26卦——大畜。守正之后，就该老老实实把力量「蓄厚」了。",
    blocks: [
      { t: "h", s: "一、大畜卦长啥样：天被山兜住了" },
      { t: "p", s: "大畜卦，上卦是艮（山），下卦是乾（天）。" },
      { t: "p", s: "你看它的卦象——上艮下乾，叫『山天大畜』，是六十四卦里的第26卦。" },
      { t: "p", s: "山在上、天在下，天那么大，却被山稳稳兜住，这就是『天在山中』。" },
      { t: "p", s: "天代表刚健、想往前冲的那股劲；山代表停止、稳重、能装东西。" },
      { t: "p", s: "刚健的劲头被大山涵养住，不急着往外冒——这叫『止健』，正是大畜的核心。" },
      { t: "p", s: "曾仕强说：大畜不是把力量憋死，而是把力量养厚，等最好的时机再放出来。" },

      { t: "h", s: "二、卦辞在说什么：先存够本，再谈大动作" },
      { t: "p", s: "卦辞就几个字：『大畜，利贞；不家食，吉；利涉大川』。" },
      { t: "p", s: "『利贞』——蓄得正，才能蓄得久。动机歪了，囤再多也是个雷。" },
      { t: "p", s: "『不家食吉』——别让有本事的人闲在家里白吃饭，把人才放出去施展，反而吉祥。" },
      { t: "p", s: "放到今天就是：别囤着才华不输出，去用、去分享，越用越旺。" },
      { t: "p", s: "『利涉大川』——等仓库真正满了，一抬脚就能跨过任何大河大坎。" },
      { t: "p", s: "大象传补了一句特别要紧：『君子以多识前言往行，以畜其德』。" },
      { t: "p", s: "意思是：多读前人的言行，把知识、德行也囤进你的『仓库』里。" },
      { t: "p", s: "曾仕强一句话点透：小畜卦（第9课）是攒钱，大畜卦是攒德——德厚，才载得动后面的福。" },

      { t: "h", s: "三、大畜六步：从收敛到天开大道" },
      { t: "p", s: "大畜卦的六个爻，像六个『仓库』，一级一级把根基做厚。曾仕强叫它『大畜六库』。" },
      { t: "p", s: "初九『有厉，利已』——刚起步看似危险，收敛自守、先别冒进，反而利己。慢就是快。" },
      { t: "p", s: "九二『舆说輹』——车轮和车厢脱开，主动停下来。该止就止，止损就是保命。" },
      { t: "p", s: "九三『良马逐，利艰贞』——像好马一样想跑，但先苦练耐力、守住正道，准备好再往前。" },
      { t: "p", s: "六四『童牛之牿，元吉』——给小牛角套上横木，防它伤人。毛病刚冒头就管住，大吉。" },
      { t: "p", s: "六五『豮豕之牙，吉』——把公猪阉了、钝了獠牙，化刚为柔。收起锋芒、以柔克刚，吉祥。" },
      { t: "p", s: "上九『何天之衢，亨』——蓄到极处，天开一条大路，畅通无阻。厚积沉潜，终有这一天。" },

      { t: "case", title: "学习上的『憋大招』", s: "小明初三，想冲重点高中。他没天天喊『我要逆袭』，而是按大畜六库一步步来：初九先收心、不盲目刷难题，把基础漏洞补上（有厉利已）；九二遇到偏科严重，暂停题海、回头抓课本（舆说輹，止损）；九三成绩稳了，才加码刷压轴题、练应试节奏（良马逐，利艰贞）；六四一有松懈苗头，立刻定规矩锁住手机（童牛之牿）；六五性子急，学会对同学谦和、不抢风头（豮豕之牙）。等到中考前，知识、心态、习惯都囤足了，上九『何天之衢』——正常发挥就考上了。这就是大畜：不张扬、不冒进，把根基养厚，时机一到自然通。" },

      { t: "mnemonic", title: "一招记住大畜卦", items: [
        "上艮下乾＝山天大畜，天被山兜＝『天在山中』藏力量。",
        "序卦口诀：『无妄之后方可畜』——先守正，再蓄力。",
        "卦辞三件宝：利贞（蓄得正）、不家食（别闲着）、利涉大川（满仓好渡河）。",
        "六库顺口溜：有厉利已、舆说輹、良马逐、童牛牿、豮豕牙、何天衢。",
        "曾仕强一句话：小畜攒钱，大畜攒德；德厚，才载得动福。"
      ]},

      { t: "diagram", key: "bagua", caption: "大畜卦 = 上艮（山·小儿子·停止笃实）下乾（天·爸爸·刚健）。天被山容，止健相生，蓄势待发。呼应第1课一家八口：爸爸的刚健被小儿子的稳重兜住，不急不躁，把力气养厚了再出手。" },

      { t: "quiz", questions: [
        { type: "choice", q: "大畜卦的卦象『山天大畜』是怎么叠出来的？", options: ["上艮（山）下乾（天）", "上乾下艮", "上艮下震", "上乾下坤"], answer: 0, explain: "大畜上卦艮（山、小儿子、停止），下卦乾（天、爸爸、刚健），叫山天大畜、六十四卦第26卦；顺《序卦传》「有无妄然后可畜，故受之以大畜」，紧接第25卦无妄卦，是序卦顺承而非综卦。" },
        { type: "choice", q: "卦辞『大畜，利贞；不家食，吉；利涉大川』的核心意思？", options: ["蓄得正才蓄得久、别闲着才华、满仓好渡大坎", "怎么囤都行随便来", "越张扬越旺", "啥都不做最安全"], answer: 0, explain: "利贞＝守正动机纯才能长久蓄；不家食＝别让有本事的人闲家里白吃饭，放出去施展反而吉；利涉大川＝仓库满了就能跨过任何大风险；曾仕强说大畜是『战略蓄能』，先做大仓库再谈大动作。" },
        { type: "choice", q: "上九『何天之衢，亨』在告诉我们什么？", options: ["蓄到极处天开大路、厚积沉潜终通达", "一开始就该横冲直撞", "永远别动", "囤着别用"], answer: 0, explain: "何天之衢＝肩负天道、天开一条大道，蓄极而通、畅通无阻；它是大畜六库最后一库，提醒你止健蓄势到最后，时机一到自然『何天之衢』一跃而过，不是叫你一直憋着不动。" },
        { type: "say", q: "请用「止健蓄势、厚积薄发」和「小畜攒钱大畜攒德」说说你生活里一个『该慢下来沉淀』或『想一步登天』的事（备考、学技能、攒钱、追人设都行）：当时你是急着冒进还是按大畜六库一步步蓄？如果用大畜卦，你会怎么『收敛自保→储备实力→何天之衢』把这一程走通？", model: "我有个反面例子：去年我想一个月练出腹肌，头三天狂练两小时，结果拉伤躺了一周（这就是初九『有厉』——刚起步就冒进，反而伤己；九二『舆说輹』该停不停）。其实大畜教我『慢就是快』：先收心、把动作做对（有厉利已），再循序渐进加量（良马逐，利艰贞）。还有正面例子：我打算考营养师证，没急着报班刷题，而是先用半年把教材啃透、把基础概念囤厚（多识前言往行，以畜其德），中间一有想偷懒的苗头就定个晨读规矩锁住（童牛之牿），性子急了就提醒自己以柔克刚别焦躁（豮豕之牙）。等到报名时，知识、心态都满了，上九『何天之衢』——正常发挥就过了。曾仕强说小畜攒钱、大畜攒德，我这次是真把『德（能力加定力）』囤厚了，才载得动这张证。两次对照让我记住——急着冒进必栽，止健蓄势才通。" }
      ]}
    ]
  },

  {
    id: 27,
    title: "第27课 · 颐养之道：山雷颐",
    subtitle: "曾仕强说：养正自养，慎言节欲",
    review: "上节课我们学了大畜卦（山天大畜），核心就四个字——止健蓄势。守正之后把力量「养厚」，小畜攒钱、大畜攒德。今天顺着《序卦传》「物畜然后可养，故受之以颐」往下走，来学六十四卦里的第27卦——颐。等资源囤够了，就该学学「怎么把日子过好、把人养正」了。",
    blocks: [
      { t: "h", s: "一、颐卦长啥样：山下有雷，嘴在吃东西" },
      { t: "p", s: "颐卦，上卦是艮（山），下卦是震（雷）。" },
      { t: "p", s: "你看它的卦象——上艮下震，叫「山雷颐」，是六十四卦里的第27卦。" },
      { t: "p", s: "上艮下震，山在上、雷在下。山代表停止、安静；雷代表震动、生机。" },
      { t: "p", s: "这个卦形特别有意思——它像个张开的嘴巴：上嘴唇不动，下嘴唇动着嚼东西。" },
      { t: "p", s: "所以「颐」本来就是下巴、脸颊，引申为「养」——吃东西养身体，就叫颐养。" },
      { t: "p", s: "曾仕强说：山雷颐是「外静内动」，就像我们吃饭，上唇不动、下唇忙——这卦专讲饮食和养生。" },

      { t: "h", s: "二、卦辞在说什么：求人不如求己" },
      { t: "p", s: "卦辞就这么几个字：「颐，贞吉；观颐，自求口实」。" },
      { t: "p", s: "「贞吉」——养得正才吉祥；动机歪了，养再多也是病。" },
      { t: "p", s: "「观颐」——看看别人是怎么养身、养德的，借别人的经验照照自己。" },
      { t: "p", s: "「自求口实」——凭自己的本事挣自己的饭，不吃嗟来之食。" },
      { t: "p", s: "放到今天就是：求人不如求己，自食其力最踏实——真正的滋养靠自己创造，不依赖、不攀附。" },
      { t: "p", s: "彖传还补了一句大格局：「天地养万物，圣人养贤以及万民」——养不只是养自己，还要养贤、照顾天下。" },

      { t: "h", s: "三、颐养六步：从戒贪自立到养大成德" },
      { t: "p", s: "颐卦六个爻，像养生的六个台阶，曾仕强叫它「颐养六阶」。" },
      { t: "p", s: "初九「舍尔灵龟，观我朵颐，凶」——你本有灵龟般的天赋，却丢掉它眼巴巴盯着别人碗里的肉看。放弃自己、羡慕别人，必凶。" },
      { t: "p", s: "六二「颠颐，拂经于丘颐，征凶」——颠倒了养育常理：该靠自己的，偏去攀附高位求养；本末倒置，盲目前行必凶。" },
      { t: "p", s: "六三「拂颐，贞凶；十年勿用」——完全违背养生正道（纵欲、算计、伤德），即便表面守正也凶，长期翻不了身。" },
      { t: "p", s: "六四「颠颐，吉；虎视眈眈，其欲逐逐，无咎」——看似反常（上位反而虚心向下求养），但动机纯、目标专注，像猛虎盯食、欲望受控，吉祥无咎。" },
      { t: "p", s: "六五「拂经，居贞吉；不可涉大川」——柔弱居上、需人辅助，但守正安分就吉；此时别冒险扩张（不可涉大川）。" },
      { t: "p", s: "上九「由颐，厉吉，利涉大川」——把养道学到家，虽历艰险终吉；蓄积深厚、德行圆满，便能担当大任、涉险成大业。" },

      { t: "case", title: "带团队的「颐养学」", s: "小刚刚升主管，带五人小队。他不摆架子，用餐时间把最好的位子让给组员、自己最后吃（曾仕强：用餐时老板最小，皇帝不差饿兵）；组员有想法他先听、虚心纳谏（六四「颠颐」——上位反而向下求养）；有人想靠拍马屁混日子，他按规矩办、不纵容（「拂颐贞凶」的反面教材）；团队焦虑时他提醒大家「少熬夜、定时定量吃饭」（节饮食）。半年过去，队伍从「靠主管喂」变成「自求口实」各顶一摊——这就是颐卦：先把人养正、养成能自立，再一起涉大川。反过来，他若像初九「舍尔灵龟观我朵颐」，放着本职不深耕、整天眼红别组风光，只会越带越散。" },

      { t: "mnemonic", title: "一招记住颐卦", items: [
        "上艮下震＝山雷颐，山在上雷在下＝嘴在嚼东西，「颐」就是下巴＋养。",
        "序卦口诀：「畜而后养」——大畜（第26课）攒够本，颐卦（第27课）学「怎么养」，顺承而下。",
        "卦辞三件套：贞吉（养正才吉）、观颐（看别人怎么养）、自求口实（求人不如求己）。",
        "六阶顺口溜：舍灵龟凶→颠拂征凶→拂颐十年凶→颠颐虎视吉→拂经居贞→由颐厉吉涉川。",
        "大象一句话：慎言语（祸从口出）、节饮食（病从口入）——曾仕强叫它「可持续滋养学」。"
      ]},

      { t: "diagram", key: "bagua", caption:   "颐卦 = 上艮（山·小儿子·停止）下震（雷·长子·动）。山静雷动，像嘴巴上唇不动、下唇开合在咀嚼——外静内动、养而不纵。呼应第1课一家八口：小儿子的「止」兜住长子的「动」，动而有止才养得久；与第26课大畜上艮下乾对照：大畜是「蓄」（把劲藏山里）、颐是「养」（雷在山下慢慢生），畜而后养。" },

      { t: "quiz", questions: [
        { type: "choice", q: "颐卦的卦象「山雷颐」是怎么叠出来的？", options: ["上艮（山）下震（雷）", "上震下艮", "上艮下乾", "上乾下震"], answer: 0, explain: "颐是六十四卦第27卦，上艮（山·小儿子·停止）下震（雷·长子·动），叫山雷颐；顺《序卦传》「物畜然后可养，故受之以颐」紧接第26卦大畜卦，是序卦顺承而非综卦；卦形像张开的嘴，上唇不动下唇动＝咀嚼，所以颐＝下巴、养生。" },
        { type: "choice", q: "卦辞「颐，贞吉；观颐，自求口实」中「自求口实」在说什么？", options: ["求人不如求己，自食其力最踏实", "靠别人养最省心", "吃得越多越旺", "啥都别干等喂"], answer: 0, explain: "自求口实＝凭自己的本事换来自己的食物、不吃嗟来之食；曾仕强说真正的滋养靠自己创造、不依赖不攀附；初九「舍尔灵龟观我朵颐」就是反面——丢掉自身灵龟（天赋）去羡慕别人碗里的肉，凶。" },
        { type: "choice", q: "大象传「君子以慎言语，节饮食」对应今天什么道理？", options: ["祸从口出、病从口入——说话小心、饮食节制", "想说就说、想吃就吃", "多吃补品才养身", "少说话多熬夜"], answer: 0, explain: "慎言语＝不妄言不恶语、言多必失、养德；节饮食＝定时定量、不贪饱纵欲、养身；曾仕强叫它「可持续滋养学」：既要喂饱又不能喂撑，养身先养德。" },
        { type: "say", q: "请用「自求口实」和「慎言语节饮食」说说你生活里一个「该靠自己还是老想靠别人」或「熬夜暴食、管不住嘴」的事（备考、工作、健身、带团队都行）：当时你是「舍尔灵龟观我朵颐」（放弃专长羡慕别人）还是「自求口实」（守住自己深耕）？如果按颐卦，你会怎么「养正自养」把这一程走通？", model: "我有个对照：去年考研，同学天天晒「副业月入过万」，我一度想放下专业课去搞自媒体赚快钱——这就是初九「舍尔灵龟观我朵颐」，把自己的灵龟（本专业底子）丢掉，眼红别人碗里的肉，差点栽。后来按颐卦「自求口实」想通：凭本事吃自己的饭最踏实，于是回到专业课深耕，每天定时定量复习、晚上十一点准时睡（节饮食、养身），焦虑时少刷朋友圈、不跟人比进度（慎言语、少内耗）。半年下来，专业课稳住、人也通透了，上九「由颐厉吉」——守正养足，该涉的「大川」（考场）也就过去了。曾仕强说颐是「可持续滋养学」，我这才懂：不是一下子冲多猛，而是先把人养正、养久，自然走得远。" }
      ]}
    ]
  },
  {
    id: 28,
    title: "第28课 · 非常之道：泽风大过",
    subtitle: "曾仕强说：大过大悟，独立不惧",
    review: "上节课我们学了颐卦（山雷颐），核心就四个字——养正自养。资源囤够了、人也养好了，就该懂得『慎言语、节饮食』，把日子和团队养得久、养得正。今天顺着《序卦传》『颐者养也，不养则不可动，故受之以大过』往下走：养着养着人就容易『动』——乱动、过头动，于是就闯出了六十四卦里的第28卦——大过。",
    blocks: [
      { t: "h", s: "一、大过卦长啥样：泽在上、风在下，泽水淹了树" },
      { t: "p", s: "大过卦，上卦是兑（泽），下卦是巽（风，也代表木）。" },
      { t: "p", s: "上兑下巽，叫「泽风大过」，是六十四卦里的第28卦。" },
      { t: "p", s: "你看它的卦形——中间四条阳爻、上下各一条阴爻，像一根大梁：中间粗、两头细。" },
      { t: "p", s: "中间太刚太重，两头太虚太弱，这就叫「大过」。" },
      { t: "p", s: "为什么叫「大过」？《易经》里阳叫「大」，这个卦阳爻比阴爻多（四阳二阴），阳「大」太过头了，所以叫大过——说白了就是「太过分了、超载了、失衡了」。" },
      { t: "p", s: "上兑是泽、是水，下巽是木、是风。泽水把树木整个淹没了，叫「泽灭木」。" },
      { t: "p", s: "大水漫过树梢，这是很不常见的反常景象——就像你肩上的担子，重到不正常了。" },

      { t: "h", s: "二、卦辞在说什么：梁弯了别慌，敢动就能通" },
      { t: "p", s: "卦辞就一句：「大过，栋桡，利有攸往，亨。」" },
      { t: "p", s: "「栋桡（ráo）」——栋梁弯了。你家的房梁如果弯了，说明上面压的东西太多，结构快撑不住了。" },
      { t: "p", s: "这是给你亮红灯：超载了！" },
      { t: "p", s: "「利有攸往，亨」——可是别怕，只要你肯主动去矫正、去加固、去找新的承重支点，反而能化险为夷、最终亨通。" },
      { t: "p", s: "彖传补了一句大格局：「大过之时大矣哉！」——大过这种非常时刻，意义大得很：非常之时，就要行非常之道。" },
      { t: "p", s: "曾仕强讲得特别透：我们一听「大过」，就想起学校给调皮学生记「大过」处分，心里一紧。" },
      { t: "p", s: "其实大过不等于坏！「太过分了」一定不好吗？不见得。" },
      { t: "p", s: "有些事开头觉得太过分，后来却让人直呼「简直太伟大了」。关键在于——你是不是「非常人物」，处在「非常时期」，做的是「非常之事」。是，就去做。" },

      { t: "h", s: "三、大象传：独立不惧，遯世无闷" },
      { t: "p", s: "大象传：「泽灭木，大过；君子以独立不惧，遯世无闷。」" },
      { t: "p", s: "「独立不惧」——大水淹树、梁都弯了，这种重压下，你更不能跟着慌、跟着躲，要挺住、敢担当。" },
      { t: "p", s: "「遯（dùn）世无闷」——万一世人看不惯你、不认同你做的非常之举，你退下来、躲开热闹，心里也不憋屈、不抱怨。" },
      { t: "p", s: "这一句其实是人生两件套：该上时独立不惧（有担当），该退时遯世无闷（能抽身）。" },
      { t: "p", s: "曾仕强说，能做到这八个字，你就不是普通人了。" },

      { t: "h", s: "四、大过六测：从垫白茅到涉灭顶" },
      { t: "p", s: "大过卦六个爻，曾仕强叫它「大过六测」，每一步都在问：梁还能撑多久？该撑，还是该撤？" },
      { t: "p", s: "初六「藉用白茅，无咎」——用洁白的茅草把祭品垫起来再摆上去。意思是：非常时期刚开始，你还没那个实力硬扛，先柔软、先谨慎、先借力，像垫层缓冲一样，就没祸。" },
      { t: "p", s: "九二「枯杨生稊，老夫得其女妻，无不利」——枯死的杨树冒出新芽，老汉娶了年轻媳妇。反常吗？反常。但衰里头藏着重生的生机，打破常规反而处处有利。" },
      { t: "p", s: "九三「栋桡，凶」——梁明显弯了还硬撑，刚愎自用、不找人帮，必折必凶。这是告诉你：过刚易折，该撤就撤，别蛮干。" },
      { t: "p", s: "九四「栋隆，吉；有它吝」——把弯了的梁往上托、托直了，吉！但要是分心去管别的事，又出问题。专注核心、刚柔相济，才能稳住。" },
      { t: "p", s: "九五「枯杨生华，老妇得其士夫，无咎无誉」——枯杨开花、老妇嫁少夫。表面风光，其实根基空了，撑不了多久。高位顺境，最忌虚名虚火。" },
      { t: "p", s: "上六「过涉灭顶，凶，无咎」——为了该做的事渡河，水没过了头顶，凶；但因为是守正、是担当、是舍身取义，问心无愧，所以「无咎」。结果危险，志向可敬。" },

      { t: "case", title: "备考的「大过」时刻", s: "小宇离考研只剩两个月，专业课还没啃完，每天焦虑到失眠——这就是「栋桡」，梁快弯了。他有两个选法。选错：像九三「栋桡凶」，硬扛到底，白天灌咖啡熬通宵、晚上继续刷题到凌晨，身体垮了、效率归零（过刚易折）。选对：先用初六「藉用白茅」——把计划砍一半，先保睡眠和心态这个「缓冲垫」，不急着全面突击；再用九二「枯杨生稊」——捡自己最熟的章节先拿分，老树发新芽，信心回来；关键是九四「栋隆吉」——把弯了的梁托直：果断停掉无效的社交和刷题量，聚焦真题和错题这一根核心梁，不节外生枝（有它吝）。等到上考场，虽没百分百准备好（过涉灭顶），但每一步都守正、尽了力，结果再险也「无咎」。曾仕强说大过不是必败、是超载警报——梁弯了先垫白茅、再托栋隆，比硬扛到折断聪明太多。" },

      { t: "mnemonic", title: "一招记住大过卦", items: [
        "上兑下巽＝泽风大过，泽水淹木（非常之境）；四阳夹二阴＝中间刚过头、两头撑不住，像一根弯梁。",
        "序卦口诀：「养而动则过」——颐卦（第27课）养正，养着养着乱动就到大过（第28课），顺承而下。",
        "卦辞三件套：栋桡（梁弯亮红灯）＋利有攸往（敢矫正才通）＋亨（化险为夷）。",
        "大象八字：独立不惧（该上敢担）＋遯世无闷（该退不怨）。",
        "六测顺口溜：白茅慎始→枯杨生稊→栋桡凶（别硬扛）→栋隆吉（托直专注）→枯杨生华（戒虚名）→过涉灭顶（守正无咎）。"
      ]},

      { t: "diagram", key: "bagua", caption: "大过卦 = 上兑（泽·小女儿·悦）下巽（风·长女·入）。泽水淹木，是非常之境；小女儿的「悦」盖过长女的「入」，柔在外、刚（四阳）壅塞在中——呼应第1课一家八口：小女儿和长女这俩「阴」被夹在四阳之外，看似柔能克刚，实则要懂得「独立不惧、遯世无闷」才能破局；与第27课颐卦上艮下震对照：颐是「养」（山静雷动、嘴在嚼）、大过是「动」（泽灭木、非常之举），养而动则过。" },

      { t: "quiz", questions: [
        { type: "choice", q: "大过卦的卦象「泽风大过」是怎么叠出来的？", options: ["上兑（泽）下巽（风/木）", "上巽下兑", "上兑下震", "上乾下巽"], answer: 0, explain: "大过是六十四卦第28卦，上兑（泽·小女儿·悦）下巽（风·长女·入），叫泽风大过；顺《序卦传》「颐者养也，不养则不可动，故受之以大过」紧接第27卦颐卦，是序卦顺承；四阳夹二阴、泽灭木，主超载失衡、非常之境。" },
        { type: "choice", q: "卦辞「大过，栋桡，利有攸往，亨」中「栋桡」在说什么？", options: ["房梁弯了＝结构超载亮红灯", "房子塌了没法救", "梁越直越凶", "啥都别动最安全"], answer: 0, explain: "栋桡＝栋梁弯曲，比喻上面压的东西太多、结构快撑不住，是「超载警报」；但「利有攸往，亨」——主动矫正、加固、找新支点，仍可化险为夷、终得亨通；曾仕强说大过不是必败，是超载警报。" },
        { type: "choice", q: "大象传「君子以独立不惧，遯世无闷」对应今天什么道理？", options: ["该上敢担当、该退不抱怨——刚柔有度的非常人物", "啥都躲着走最安全", "硬扛到底才有面子", "别人不认同就急眼"], answer: 0, explain: "独立不惧＝重压下挺住、敢担当；遯世无闷＝世人看不惯、不认同也能抽身退隐、心里不憋屈；曾仕强说做到这八个字就不是普通人——大过是非常之卦，非常之时需非常担当，也需能进能退的清醒。" },
        { type: "say", q: "请用「栋桡（梁弯了）」和「独立不惧、遯世无闷」说说你生活里一个「压力超载、该撑还是该撤」或「太过分了反而是伟大」的事（备考、带团队、创业、一段关系都行）：当时你是像九三「栋桡凶」硬扛，还是像初六「藉用白茅」先垫缓冲、九四「栋隆吉」托直专注？如果按大过卦，你会怎么「独立不惧去担当、遯世无闷能抽身」把这一程走通？", model: "我有个对照：去年带社团办活动，报名人数暴涨三倍，我像九三「栋桡凶」硬扛——一个人包揽策划、对接、现场，连轴转两周，结果活动当晚累到发烧、环节还出了岔子（过刚易折、刚愎自用必凶）。后来按大过卦重来：先初六「藉用白茅」——把任务拆给五个副组长，自己只抓核心节点，像垫层缓冲不硬接；再九四「栋隆吉」——把弯了的梁托直，砍掉华而不实的灯光秀（戒九五「枯杨生华」的虚名），专注「流程顺、人安全」这一根梁，不节外生枝（有它吝）。新活动办下来虽没那么炫（过涉灭顶，没百分百完美），但稳稳落地、团队也没散，问心无愧（无咎）。至于「太过分了反是伟大」——我们当时打破校规惯例搞跨校区联办，开头被质疑「太过分」，后来却成了年度标杆。曾仕强说大过是非常之卦，我现在懂了：梁弯了先垫白茅、托栋隆，比硬扛到折断聪明；真到该担当的非常时刻，独立不惧上，世人不解时遯世无闷退，才是完整的大过智慧。" }
      ]}
    ]
  },
  {
    id: 29,
    title: "第29课 · 处险不惊：坎为水",
    subtitle: "曾仕强说：习坎、有孚，把深渊变跳板",
    review: "上节课我们学了大过卦（泽风大过），核心一句话——大过大悟、独立不惧。大过是「太过分了、超载了」，梁弯了先垫白茅、再托栋隆，该担当敢担当、该抽身能抽身。今天顺着《序卦传》「物不可以终过，故受之以坎」往下走：凡事太过分之后，往往就要跌进「深渊」——六十四卦里的第29卦，坎卦。",
    blocks: [
      { t: "h", s: "一、坎卦长啥样：上坎下坎，水叠水，险中有险" },
      { t: "p", s: "坎卦，上卦是坎（水），下卦也是坎（水）。上下都是坎，叫「坎为水」，是六十四卦里的第29卦。" },
      { t: "p", s: "它是八纯卦之一：乾☰坤☷震☳巽☴坎☵离☲艮☶兑☱，坎为水上下都是自己，像水一层叠一层，也叫「习坎」。" },
      { t: "p", s: "坎是什么意思？《说文》里「坎，陷也」——坑、陷阱、深潭。坎卦就是「险、陷、深水区」。" },
      { t: "p", s: "你看它的卦形——中间一条阳爻（实），上下各夹着阴爻（虚），叫「坎中满」：一阳陷在二阴之间，像人掉进水里，外头全是危险的波涛，中间那点阳气就是心里不肯灭的光。" },
      { t: "p", s: "两个坎叠一起，是「重险」——一个坑后面还有另一个坑，险上加险。曾仕强说，人生祸不单行，福很少两个一起来，祸是一而再来的；坎卦就是要你学会「跟险难相处」。" },

      { t: "h", s: "二、卦辞在说什么：习坎、有孚、维心亨、行有尚" },
      { t: "p", s: "卦辞：「习坎，有孚，维心亨，行有尚。」" },
      { t: "p", s: "「习坎」——重重的险。「习」不是复习，是「练习、熟悉」：你要反复练习跟危险相处，练到精通，就像学会游泳一样。" },
      { t: "p", s: "「有孚」——诚信、信念。坎卦中实外虚：心里那点阳气（孚）是实的，外面随环境变来变去是虚的。内要方、外要圆，守住心里的诚信，外面灵活变通。" },
      { t: "p", s: "「维心亨」——只要心里诚信不乱，终能通、能亨。曾仕强说信心最重要：心正，就不溺。" },
      { t: "p", s: "「行有尚」——既然心里有底，就别畏畏缩缩，谨慎往前走，会受人尊重、走得有功。" },
      { t: "p", s: "彖传补了一句大格局：「水流而不盈，行险而不失其信。」水遇到再大的坑，它不滞留、不满出来，一路往前流——你处险也要像水：不被困境困死，流过去。" },

      { t: "h", s: "三、大象传：水洊至，常德行，习教事" },
      { t: "p", s: "大象传：「水洊（jiàn）至，习坎；君子以常德行，习教事。」" },
      { t: "p", s: "「洊至」——水一而再、再而三地流来，越流越深，提醒你：这世界充满重重的险难，因为到处都可能「缺土」（坎＝欠土＝陷阱）。" },
      { t: "p", s: "「常德行」——常保美德。人昧良心很快、凭良心很难，越是险境越要守住善良。" },
      { t: "p", s: "「习教事」——把应对困难当成日常练习，该做的事一件件做完、该坚持的原则不动摇。曾仕强说：把「险」当常态，让团队「都会游泳」。" },
      { t: "p", s: "彖传还讲「王公设险以守其国」——险也能当盾牌用（国防、边界），所以「险之时用大矣哉」：险不是只有坏，用对时候、顺时而为，它能护你。" },

      { t: "h", s: "四、坎卦六爻：从入坎窞到系用徽纆的脱险链" },
      { t: "p", s: "坎卦六个爻，曾仕强叫它「涉水六要」，一步一检，步步保命。" },
      { t: "p", s: "初六「习坎，入于坎窞（dàn），凶」——一脚踩空掉进深水坑，凶。小象说「失道凶」：你临时才练游泳，来不及了。提醒：习坎要提前，别等祸来了抱佛脚。" },
      { t: "p", s: "九二「坎有险，求小得」——身已在险中，但九二刚中，先求「小得」（局部止血），不贪大，先稳住。" },
      { t: "p", s: "六三「来之坎坎，险且枕，入于坎窞，勿用」——来也是坎、去也是坎，前后皆险，只能「枕险而息」稳住别乱动；妄动就又掉坑，所以「勿用」。" },
      { t: "p", s: "六四「樽酒簋贰，用缶，纳约自牖（yǒu），终无咎」——一樽酒、两盒饭、用瓦器，从窗口递进去（简朴诚心去求援），处险中以诚待人，终无咎。" },
      { t: "p", s: "九五「坎不盈，祗（qí）既平，无咎」——水还没满、险还没到顶，及时抽身、把坑填平，就无咎。九五中正，险将平。" },
      { t: "p", s: "上六「系用徽纆（mò），寘于丛棘，三岁不得，凶」——用绳索捆、关进荆棘牢狱，三年不得脱，凶。处险之极还执迷不悟，越陷越深，最凶。" },

      { t: "case", title: "备考遇上连环坑（坎卦教你怎么脱险）", s: "小航考研最后三个月，先是专业课换参考书（第一坑），接着室友考研失利情绪崩影响他（第二坑），这就是「习坎」——一个坎后面还有坎，险上加险。他有两个选法。选错：像初六「入于坎窞凶」，每个坑都临时慌乱抱佛脚，越陷越深（祸不单行，因为应对乱了）。选对：先稳住「有孚维心亨」——心里告诉自己「坑是常态、我练过」，不被焦虑淹没；再用九二「求小得」——不贪全，先把新参考书最熟的章节拿下，局部止血；六三「枕险而息」——环境变动时暂停盲目加买资料，静观其变；六四「纳约自牖」——坦诚跟导师、研友说困难，用简朴的小请求换帮助，不硬撑；等到九五「坎不盈祗既平」——趁心态还没崩（水未满），赶紧调整作息把坑填平；最后上考场哪怕还有没复习完的（上六险极），但一路守正、没执迷硬扛，已「无咎」。曾仕强说坎卦不是凶卦是「必修课」——心存诚信、行动谨慎、制度牢固，深渊也能变跳板。" },

      { t: "mnemonic", title: "一招记住坎卦", items: [
        "上坎下坎＝坎为水，水叠水，险上有险（重险）；坎中满＝一阳陷二阴，像心里那点光不肯灭。",
        "序卦口诀：「过则入坎」——大过（第28课）太过分就跌进深渊，坎（第29课）教你处险不惊，顺承而下。",
        "脱险三句：习坎（练跟险相处）· 有孚维心亨（心里守诚信）· 常德行习教事（把应对困难当日常）。",
        "坎字拆开＝欠土＝陷阱；凡欠土处水必流去，所以「习坎」＝练习与险难共存，像水一样流过去不滞留。"
      ]},

      { t: "diagram", key: "bagua", caption: "坎为水 = 上坎（水·中男·陷）下坎（水·中男·陷）——八纯卦之一，上下同一个中男。坎中满：一阳陷在二阴之间，像心里藏着一点不肯灭的光（呼应太极「阳陷阴中、心中一点光明」）；呼应第1课一家八口：中男自己叠自己，险中藏信。与第28课大过（泽风大过·四阳夹二阴）对照：大过是「刚太过」亮红灯（梁弯），坎是「阳陷阴中」藏着信、等水流出——大过讲担当、坎讲处险。" },

      { t: "quiz", questions: [
        { type: "choice", q: "坎卦的卦象「坎为水」是怎么叠出来的？", options: ["上坎（水）下坎（水）", "上坎下离", "上兑下坎", "上乾下坎"], answer: 0, explain: "坎为水是六十四卦第29卦，上下皆坎（水），属八纯卦；坎＝陷＝险，两坎相重叫「重险」、险上加险；《序卦传》「物不可以终过，故受之以坎」，紧接第28卦大过，是序卦顺承。" },
        { type: "choice", q: "卦辞「习坎，有孚，维心亨，行有尚」中「习坎」在说什么？", options: ["反复练习跟险难相处，练到精通像会游泳", "复习功课考试", "习惯就好不用管", "赶紧逃跑最安全"], answer: 0, explain: "「习坎」的「习」是练习、熟悉，不是复习；人生的险阻躲不掉，就要练到跟它共存、精通应对，像学会游泳；有孚＝心里守诚信，维心亨＝心正则通，行有尚＝谨慎前行受人敬。" },
        { type: "choice", q: "大象传「水洊至，习坎；君子以常德行，习教事」给你什么提醒？", options: ["把德行当常态、把应对困难当日常练习", "啥都别管先躺平", "越险越要狠", "对外人全说实话"], answer: 0, explain: "洊至＝水一再来、越流越深，提醒险是常态；常德行＝险境也守善良，习教事＝把应对困难当日常演练、该做的事不疏漏；曾仕强说让团队「都会游泳」，把险当成必修课。" },
        { type: "say", q: "请用「习坎（练跟险相处）」「有孚维心亨（心里守诚信）」「常德行习教事（应对困难当日常）」说说你生活里一段「连环坑」——可能是备考、工作、一段关系或家里的事：当时你是像初六「入于坎窞凶」临时抱佛脚乱了，还是像九二「求小得」先稳住小利、六四「纳约自牖」坦诚求援？如果按坎卦，你会怎么「心里守孚、把坑当日常练习」一步一步走出来？", model: "我对照一下：去年同时撞上论文盲审不过、工作转正答辩、家人生病三件事叠一起，就是「习坎」——一个坎后面还有坎。我当时像初六「入于坎窞凶」：每来一个坑就慌，论文改得乱、答辩准备敷衍、家里事也硬扛，越陷越深（祸不单行，因为应对全乱了）。后来按坎卦重来：先「有孚维心亨」——跟自己说「坑是常态、我练过」，不被焦虑淹掉，心里那点阳气（孚）守住；再九二「求小得」——不贪全，论文先改评审最在意的第三章，答辩先背核心三页，局部止血；六三「枕险而息」——家人生病那阵不强行兼顾所有，暂停非必要的社交，稳住别乱动；六四「纳约自牖」——坦诚跟导师说难处、用简朴的小请求换延期，不硬撑。等九五「坎不盈祗既平」——趁心态还没崩，赶紧把作息调回正轨、把坑填平。三件事后来虽没十全十美（上六险极），但一路守正、没执迷硬扛，问心无愧（无咎）。曾仕强说坎卦不是凶卦是必修课——现在再遇到连环坑，我先深吸口气：心里守孚、把应对当日常练习，反而比从前稳。" }
      ]}
    ]
  },
  {
    id: 30,
    title: "第30课 · 附丽光明：离为火",
    subtitle: "曾仕强说：离者丽也、明两作、重明以丽乎正",
    review: "上节课我们学了坎卦（坎为水），核心一句话——习坎、有孚，把深渊变跳板。坎是「陷」，教你在重重险难里守诚信、练跟险相处（曾仕强：坎是智慧的卦、诚意）。今天顺着《序卦传》「陷必有所丽，故受之以离。离者，丽也」往下走：人从险坑里爬出来，第一件事就是「找个光亮依附上去」——六十四卦上经收官的第30卦，离卦。",
    blocks: [
      { t: "h", s: "一、离卦长啥样：上离下离，火叠火，上经收官" },
      { t: "p", s: "离卦，上卦是离（火），下卦也是离（火）。上下都是离，叫「离为火」，是六十四卦里的第30卦，也是上经最后一卦。" },
      { t: "p", s: "它是八纯卦之一：乾☰坤☷震☳巽☴坎☵离☲艮☶兑☱，离为火上下都是自己，像火一层叠一层，也叫「明两作」——光明一个接一个冒出来。" },
      { t: "p", s: "离是什么意思？《序卦传》「离者，丽也」——丽=附丽、附着、依附。火不能凭空烧，必附在柴上才亮；人不能孤立活，必有所依附才立。坎是「陷」（水淹），离是「附」（火靠物），坎离是一对——坎教诚意，离教明理。" },
      { t: "p", s: "你看它的卦形——中间一条阴爻（虚），上下各夹着阳爻（实），叫「离中虚」：一阴陷在二阳之间，像火光外边旺、里头空，外刚内柔。这跟坎卦正好反过来：坎中满（一阳陷二阴）、离中虚（一阴陷二阳），坎离是相错（阴阳互换），不是上下翻。" },

      { t: "h", s: "二、卦辞在说什么：离，利贞，亨；畜牝牛，吉" },
      { t: "p", s: "卦辞：「离，利贞，亨；畜牝牛，吉。」" },
      { t: "p", s: "「利贞」——光明必须守正。火守正道是灯、是温暖；不守正就是野火燎原，烧完自己还伤别人，转瞬即灭。曾仕强说：有知识有才能的人，越要把它用在正道上。" },
      { t: "p", s: "「畜牝牛，吉」——畜=培养，牝牛=母牛，忍辱负重、默默载物。意思是：你的光明要有「母牛那样的德行」来涵养——温和、包容、不张扬、能扛事。越有才华越要低调蓄力，这样才吉祥。曾仕强点破：离卦不是教你耀眼夺目，是教你「明而能柔、光而不耀」。" },
      { t: "p", s: "彖传补了格局：「离，丽也。日月丽乎天，百谷草木丽乎土。重明以丽乎正，乃化成天下。」日月靠天才亮、草木靠土才长、火靠柴才燃——万物都要依附。而且有功劳的人常被忽略，所以才要忍辱负重；依附在正道上，光明才能化成天下。" },

      { t: "h", s: "三、大象传：明两作，离；大人以继明照于四方" },
      { t: "p", s: "大象传：「明两作，离；大人以继明照于四方。」" },
      { t: "p", s: "「明两作」——光明要能持续，一个接一个，像日月交替、昼夜相继，不是一下闪完。曾仕强讲「两」是连续：不争一时，只争千秋；三忘（忘食、忘忧、忘老），三明（重明、大明、长明）。" },
      { t: "p", s: "「大人以继明照于四方」——品德好、才能高的人，要持续用德行和知识去造福百姓，照亮四面八方。真正光明不是一人独亮，而是点亮别人、代代相传：培养后辈、传递经验、成就团队。独明是一时，众明是永恒。" },
      { t: "p", s: "曾仕强还有一句扎心的：坎代表智慧，离代表知识；聪明误用比不聪明更可怕。知识要附在伦理道德上、发挥中道精神，才造福人群——否则越有知识危害越大。所以「所丽正，两方都好；所丽不正，两个都倒霉」。" },

      { t: "h", s: "四、离卦六爻：从履错敬行到继明济世的发光链" },
      { t: "p", s: "离卦六个爻，曾仕强叫它「离附六阶」，一步一光，步步守明。" },
      { t: "p", s: "初九「履错然，敬之，无咎」——刚起步步履错乱（摸索期难免走错），把事情「看重」（敬=看重不是恭敬）、敬畏规律，就能避咎。新人入局，「敬」是第一护身符。" },
      { t: "p", s: "六二「黄离，元吉」——黄是中央正色，柔顺居中位，中正守柔、依附正道，全卦最吉。所有文明知识都不能离开品德；温和中正是最高级的吉祥。" },
      { t: "p", s: "九三「日昃之离，不鼓缶而歌，则大耋之嗟，凶」——太阳西斜、盛极转衰，该顺势知命却强撑享乐或哀叹衰老，就凶。知识爆炸时代，最要紧是选对知识、知止不凶。" },
      { t: "p", s: "九四「突如其来如，焚如，死如，弃如」——光明骤盛、刚猛暴烈、德不配位，像野火转瞬焚尽、被人抛弃。过刚易焚，暴起必亡；发光忌过猛。" },
      { t: "p", s: "六五「出涕沱若，戚嗟若，吉」——居尊位却泪下忧叹、常怀忧患自省，守柔居下、不骄不傲，化忧为吉。越在高处越要低头，越有光芒越要谦卑。" },
      { t: "p", s: "上九「王用出征，有嘉折首，获匪其丑，无咎」——光明大成，从追光者变成光源本身；正道讨伐、首恶必办胁从不问、除恶无咎，然后培养后辈、传承光明。" },

      { t: "case", title: "新人入行该怎么「附丽」（离卦教你怎么扎根）", s: "小文刚毕业进一家大公司，就是「离卦」的情境——火要找柴附、人要找平台落。他有两个选法。选错：像九四「突如其来如焚如死如弃如」，一进来就抢风头、贬低同事、急着证明自己，看似光芒万丈实则根基浅、德不配位，很快被团队孤立、试用期都没过。选对：先初九「履错然敬之无咎」——承认自己是摸索期，步子乱就多看多问、把每件事当回事、敬畏规则，不乱来就无咎；再六二「黄离元吉」——不挑三拣四，安心依附这个靠谱平台、跟对 mentor，中正柔顺把根基扎稳，全卦最吉；平时畜牝牛之德——温和包容、多扛事少张扬，把才华用正道；等站稳了，六五「出涕沱若戚嗟若吉」——居安思危、常自省哪里不足，不飘；最后上九——自己成了光源，带新人、把经验传下去。曾仕强说：所丽正，两方都好；找对平台、用对德行，火才烧得久。" },

      { t: "mnemonic", title: "一招记住离卦", items: [
        "上离下离＝离为火，火叠火，上经收官（第30卦）；离中虚＝一阴陷二阳，外刚内柔，跟坎中满（一阳陷二阴）正好相错。",
        "序卦口诀：「陷必有所丽」——坎（第29课）掉坑里，离（第30课）爬出来先找个光亮依附；坎教诚意、离教明理，一对。",
        "附丽三句：利贞（光明守正·否则野火）· 畜牝牛（柔顺蓄力·光而不耀）· 继明照四方（点亮别人·独明一时众明永恒）。",
        "离字本义＝丽＝附着；火附柴、日月附天、草木附土、人附正道——所丽正两好，所丽不正两倒霉；坎是智慧、离是知识，聪明误用比不聪明更可怕。"
      ]},

      { t: "diagram", key: "bagua", caption: "离为火 = 上离（火·中女·附丽）下离（火·中女·附丽）——八纯卦之一，上下同一个中女。离中虚：一阴陷在二阳之间，像火光外旺内空、外刚内柔（呼应太极「阳中含阴、柔丽乎中正」）；呼应第1课一家八口：中女自己叠自己，光明相继。与第29课坎（坎为水·坎中满·一阳陷二阴）对照：坎离相错（阴阳互换），坎是陷中藏信、离是附中守柔——坎教诚意、离教明理，上经以离收官。" },

      { t: "quiz", questions: [
        { type: "choice", q: "离卦的卦象「离为火」是怎么叠出来的？", options: ["上离（火）下离（火）", "上离下坎", "上兑下离", "上乾下离"], answer: 0, explain: "离为火是六十四卦第30卦、上经最后一卦，上下皆离（火），属八纯卦；离＝丽＝附丽、火必附柴才燃；卦形离中虚（一阴陷二阳），与坎中满相错（阴阳互换）。" },
        { type: "choice", q: "卦辞「离，利贞，亨；畜牝牛，吉」中「畜牝牛，吉」在说什么？", options: ["培养母牛般柔顺忍辱负重的德行来涵养光明，光而不耀才吉", "养真牛能发财", "牛比火重要", "越快越吉祥"], answer: 0, explain: "畜＝培养，牝牛＝母牛，柔顺忍辱负重、默默载物；曾仕强点破：离不是教人耀眼，是教「明而能柔、光而不耀」，越有才华越要低调蓄力，依附正道才吉祥。" },
        { type: "choice", q: "大象传「明两作，离；大人以继明照于四方」给你什么提醒？", options: ["光明要持续、更要点亮别人代代相传，不只自己亮", "一下闪完最亮", "只顾自己优秀", "离火不用附物"], answer: 0, explain: "明两作＝光明连续相继（不争一时只争千秋）；大人以继明照于四方＝品德才能高的人持续用德行知识造福百姓；独明是一时、众明是永恒，培养后辈、传递经验才是终极价值。" },
        { type: "say", q: "请用「利贞（光明守正）」「畜牝牛（柔顺蓄力·光而不耀）」「继明照于四方（点亮别人）」说说你生活里一段「附丽」——可能是刚进新平台/团队、找 mentor、或依附某个目标：当时你是像九四「突如其来如焚如死如弃如」急着抢风头根基浅，还是像初九「履错然敬之无咎」先敬慎扎根、六二「黄离元吉」中正柔顺把根扎稳？如果按离卦，你会怎么「找对依附、守正发光、再点亮别人」？", model: "我对照一下：三年前从学校跳到一家创业公司，就是「离卦」——火要找柴附。我当时有点像九四「突如其来如焚如死如弃如」：一进来就想证明自己，抢着在会上发言、暗贬同事、把功劳往自己身上揽，看似光芒万丈，其实根基浅、德不配位，两个月就被团队边缘化、差点走人。后来按离卦重来：先初九「履错然敬之无咎」——承认自己是 newcomer，步子乱就多看多问、把每件事当回事、敬畏公司规矩和前辈经验，不乱抢就稳住了；再六二「黄离元吉」——不挑平台挑 mentor，安心依附这个靠谱团队、跟对带我的前辈，中正柔顺把根扎下来，这步是全卦最吉；平时畜牝牛之德——温和包容、多扛琐碎事少张扬，把那点才华用在正道上；等站稳了，六五「出涕沱若戚嗟若吉」——每次小成都自省哪里还不够、居安思危，不飘；再后来自己也成了光源，带新人、把踩过的坑写成文档传下去。曾仕强说「所丽正，两方都好」——找对平台、用对德行，这把火才烧得久。现在再进新环境，我先想清楚：我依附的是不是正道、我有没有母牛那份柔顺，再谈发光。" }
      ]}
    ]
  },
  {
    id: 31,
    title: "第31课 · 无心之感：泽山咸",
    subtitle: "曾仕强说：咸者感也、山泽通气、虚怀受物",
    review: "上节课我们学了离卦（离为火），核心一句话——附丽（丽也）、利贞、畜牝牛、继明照于四方。离是『附』，教你在爬出坎卦的险坑后，找对平台、守正发光：利贞（光明守正，否则变野火）、畜牝牛（柔顺蓄力·光而不耀）、继明照于四方（点亮别人·独明一时众明永恒）。今天《序卦传》说『有天地然后有万物，有万物然后有男女，有男女然后有夫妇』——上经讲完天地乾坤，下经要从『人与人怎么相处』开始。第31卦，咸卦。",
    blocks: [
      { t: "h", s: "一、咸卦长啥样：上兑下艮，山上有泽" },
      { t: "p", s: "上节课我们刚讲完上经最后一卦『离为火』。从这一课起，易经进入下经——专门讲人间的感情、家庭和相处。" },
      { t: "p", s: "第31卦叫『咸卦』（泽山咸）。它的名字很有意思：『咸』就是『感』字去掉了『心』。" },
      { t: "p", s: "去掉心，是在说：最好的感应，是不带目的、不刻意、自然生发的『无心之感』。" },
      { t: "p", s: "看卦象：上面是兑（泽·少女·喜悦），下面是艮（山·少男·稳重）。山托着水、水润着山，山泽通气，阴阳自然交感。" },
      { t: "p", s: "兑为悦、艮为止。一个温柔、一个稳重；一个想靠近、一个不乱动。止而能悦，这就是关系该有的样子。" },
      {  t: "p", s: "它是下经的第一卦，跟上经的坎离正好接上：上经讲天地，下经讲人伦；从『天地』走到『男女交感』，人就出场了。" },

      { t: "h", s: "二、卦辞：咸，亨，利贞；取女吉" },
      { t: "p", s: "卦辞说：『咸，亨，利贞；取女吉。』" },
      { t: "p", s: "『亨』——有感就通，心诚则灵，关系自然顺畅。" },
      { t: "p", s: "『利贞』——感应必须守正：发乎情、止乎礼，不强迫、不越界，这才是长久之利。" },
      { t: "p", s: "『取女吉』——用男女成婚来打比方：以柔感刚、以礼相待、尊重对方，关系才吉祥。" },
      { t: "p", s: "曾仕强说：天地感而万物化生，人心感而天下和平。所有关系的起点，都是这份『无心』的真诚——不带算计，只是心意相通。" },

      { t: "h", s: "三、大象传：君子以虚受人" },
      { t: "p", s: "大象传：『山上有泽，咸；君子以虚受人。』" },
      { t: "p", s: "山很高、泽很低，高下相感；你要先把自己放空，才能装下对方的需求和情绪。" },
      { t: "p", s: "心不空就满了，满了就装不下别人，也就感不了、通不了。" },
      { t: "p", s: "翻译成今天的话：少说教、多倾听；少推销、多共情。你越虚心，越能包容别人；你若真诚，知己自来。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：兑（泽·少女）与艮（山·少男）是其中两个卦。咸卦＝上兑下艮（山上有泽）——兑为悦、艮为止，刚下柔上、二气交感。曾仕强说：山泽通气，不是山去讨好泽，也不是泽去依附山，而是自然交融、双向滋养。呼应第1课一家八口：少男（艮）与少女（兑）的相感，正是『无心之感』最生动的画面。" },

      { t: "h", s: "四、六爻：从脚趾到脊背的「情感六触」" },
      { t: "p", s: "咸卦六个爻，曾仕强叫它『情感六触』，一层比一层深入，讲透一段关系怎么从心动走到真心。" },
      { t: "p", s: "初六『咸其拇』——感应到脚趾，只是初萌微动。像刚认识、刚有好感，点到为止、不冒进，守住本心别乱动。" },
      { t: "p", s: "六二『咸其腓，凶；居吉』——感应到小腿，一冲动就往前凑，凶；稳住不动、守本位反而吉。感情和关系，最忌一个『急』字。" },
      { t: "p", s: "九三『咸其股，执其随，往吝』——感应到大腿，就盲目跟着别人走、丢了主见，往前必有遗憾。关系里，先做好自己，再谈共鸣。" },
      { t: "p", s: "九四『贞吉，悔亡；憧憧往来，朋从尔思』——心正、真诚、不功利，来回摇摆的人心也就定了，同频的人自然被你吸引。" },
      { t: "p", s: "九五『咸其脢，无悔』——感应到脊背（靠近心），默契到不用说出口，信任早建好，无怨无悔。" },
      { t: "p", s: "上六『咸其辅颊舌』——只停在嘴唇舌头，只剩甜言蜜语，全是表面功夫，说得再好听也终会散。" },

      { t: "case", title: "新人进社团，怎么『感应』才不翻车", s: "小宇刚加入学校的辩论社，就是『咸卦』的情境——山要通气、人要找同伴。他有两个选法。选错：像六二『咸其腓』——刚加完群就疯狂发言、急着表现、硬要拉人组队，结果大家都觉得他太冲、把他屏蔽，关系还没开始就黄了。选对：先初六『咸其拇』——先安静观察、点点头、聊两句，不急着深交，守住本心不冒进；再『君子以虚受人』——多听学长学姐怎么说、少抢话，把杯子倒空才能装下团队的规则；接着九四『贞吉悔亡』——真诚负责、不耍心机，慢慢大家就信他、拉他进核心；等默契到了九五『咸其脢』，一个眼神就知道该谁上场。曾仕强说：最好的关系不是追来的，是真诚吸引来的；你若盛开，清风自来。" },

      { t: "mnemonic", title: "一招记住咸卦", items: [
        "咸＝感去心：无心之感最真——不刻意、不功利、自然生发；『感』字去掉心，才是真感。",
        "卦象：上兑（泽·少女·悦）下艮（山·少男·止）＝山上有泽；止而能悦，稳重为基、柔和为用。",
        "六步感应链：拇（脚趾初感·不急）→腓（小腿·急则凶、居则吉）→股（盲从·吝）→四（心正·朋来）→脢（默契·无悔）→辅颊（口舌·虚浮）。由浅入深，急不得。",
        "君子以虚受人：先空杯、再装人；少说教多倾听、少推销多共情——你越谦卑，越能感应世界。"
      ]},

      { t: "quiz", questions: [
        { type: "choice", q: "咸卦的卦象「泽山咸」是怎么叠出来的？", options: ["上兑（泽）下艮（山）", "上艮下兑", "上乾下坤", "上离下坎"], answer: 0, explain: "咸为下经第31卦，上兑（泽·少女·悦）下艮（山·少男·止），山上有泽、山泽通气；兑为悦、艮为止，刚下柔上、二气交感，是『无心之感』的生动画面。" },
        { type: "choice", q: "大象传「君子以虚受人」在说什么？", options: ["先放空自己，才能接纳他人", "虚心接受别人请客", "虚心接受礼物", "空着肚子待客"], answer: 0, explain: "山上有泽，高下相感；心不虚则满，满则不纳。翻译成今天的话：少说教多倾听、少推销多共情，你越虚心越能包容、越真诚越有感力。" },
        { type: "choice", q: "六二「咸其腓，凶；居吉」给你的提醒是？", options: ["一深入就急进会凶，稳住不动才吉", "小腿容易受伤要注意", "少走路多坐着", "越热情越好"], answer: 0, explain: "腓=小腿，稍一深入就躁进必凶；『居』=安居不进，守住本位、耐心等待反而吉祥。关系升温最忌急功近利，慢一点水到渠成。" },
        { type: "say", q: "请用「无心之感（不刻意·自然真诚）」「君子以虚受人（先空杯多倾听）」「由浅入深（拇→腓→脢，急不得）」说说你的一段经历——比如刚进新团队/社团、刚认识一个朋友：你是像六二「咸其腓」急着表现被冷落，还是像初六「咸其拇」先静观、再虚受人、最后靠真诚吸引同频的人？如果按咸卦，你会怎么「放空自己、守正感应、慢慢交心」？", model: "我对照一下：去年刚转到一个新班级，就是『咸卦』——山要通气、人要找同伴。我一开始有点像六二『咸其腓』：刚认识就急着表现，抢着回答问题、硬要拉人吃饭，结果几个同学觉得我太黏、有点躲着我。后来按咸卦重来：先初六『咸其拇』——不急着深交，点头微笑、简单聊两句，守住本心不冒进；再『君子以虚受人』——多听同学聊什么、少抢话，把杯子里的水倒空，才装得下这个新集体的节奏；接着九四『贞吉悔亡』——真诚待人、不耍小聪明，慢慢大家愿意约我组队；等默契到了『咸其脢』，不用多说，一个眼神就知道谁该顶上。曾仕强说『你若盛开，清风自来』——不带目的、不功利，真诚自然会有回声。现在再进新环境，我先想清楚：我有没有把杯子倒空、有没有守住正道，再谈交心。" }
      ]}
    ]
  },
  {
    id: 32,
    title: "第32课 · 长长久久：雷风恒",
    subtitle: "曾仕强说：恒不是死守，是方向不变、方法可改",
    review: "上节课我们学了咸卦（泽山咸），核心一句话——无心之感、山泽通气、虚怀受物。咸是「感」字去掉心，最好的感应是不带目的、不刻意、自然生发；卦象上兑（泽·少女·悦）下艮（山·少男·止），山上有泽、二气交感；大象「君子以虚受人」——先空杯、多倾听，你若盛开清风自来。今天《序卦传》说「夫妇之道不可以不久也，故受之以恒」——咸是两性相感（恋爱开始），恒是长相厮守（婚姻长久）。第32卦，恒卦。",
    blocks: [
      { t: "h", s: "一、恒卦长啥样：上震下巽，雷风相与" },
      { t: "p", s: "上节课咸卦讲完「感应」，下经接着讲「长久」。第32卦叫「恒卦」（雷风恒）。" },
      { t: "p", s: "「恒」就是长久、恒常、持之以恒。它紧接咸卦而来——《序卦传》说：夫妇之道不可以不久也，故受之以恒。咸是两人相恋，恒是结了婚长相厮守；一个讲「速」（来得快），一个讲「久」（过得长）。" },
      { t: "p", s: "看卦象：上面是震（雷·长男·动），下面是巽（风·长女·入/顺）。雷一响风就到，雷动风随、风助雷威，刚上柔下、雷风相与，恒常不息——这就是「恒」。" },
      { t: "p", s: "曾仕强说：恒卦的重点是「要动才能恒」。雷也在动、风也在动，不是说死守不动才叫恒；没变化大家就厌倦，厌倦就长久不了。所以恒不是一潭死水，是雷风一样日日更新、又生生不息。" },

      { t: "h", s: "二、卦辞：恒，亨，无咎，利贞，利有攸往" },
      { t: "p", s: "卦辞说：『恒，亨，无咎，利贞，利有攸往。』" },
      { t: "p", s: "「亨」——节拍对了，自然畅通。你方向正、节奏稳，事情就顺。" },
      { t: "p", s: "「无咎」——持之以恒、不犯大错，就没有灾祸。" },
      { t: "p", s: "「利贞」——贞就是正道，它是你的「节拍器」：偏离正道，再用力也失速。" },
      { t: "p", s: "「利有攸往」——守正持恒，就利于往前走、成大事。" },
      { t: "p", s: "曾仕强一句话点破：恒卦的「恒」，不是死守错误，而是坚守正道。方向不正的坚持，那是愚昧，不是长久。" },

      { t: "h", s: "三、大象传：君子以立不易方" },
      { t: "p", s: "大象传：『雷风，恒；君子以立不易方。』" },
      { t: "p", s: "「方」是方针、原则、方向。君子看到雷风恒常相随，就立定一个不变的正道——做人有底线、做事有准则、处世有初心，不随风倒、不因难弃。" },
      { t: "p", s: "曾仕强把它翻成现代人听得懂的话：把原则钉死，把流程做活。战略不动摇，战术可微调。这叫「持经达变」——不能变的原则坚持，其他随时变通。我们叫「以不变应万变」：不变的是原则，变的是方法。" },
      { t: "p", s: "比如我们中华民族——「中」是不变的（立场、根），「华」是变的（面貌、形式）。有所不变、有所变，跟易经的「不易」和「变易」一模一样。" },
      { t: "diagram", key: "bagua", caption: "这是八卦图：震（雷·长男）与巽（风·长女）是其中两个卦。恒卦＝上震下巽（雷风相与）——雷动风随、刚上柔下、二气恒常相生。曾仕强说：要动才能恒，雷风都在动，所以恒不是死守。呼应第1课一家八口：长男（震）与长女（巽）已成家室、担起责任，正是「夫妇之道不可以不久」最生动的画面——从咸卦的少男少女相感，走到恒卦的长子长女持家，感情由「速」入「久」。" },

      { t: "h", s: "四、六爻：恒律六检，从急进到专一" },
      { t: "p", s: "恒卦六个爻，曾仕强叫它「恒律六检」，一层层告诉你：怎么把一件事、一段关系，长久地守住，又不守死。" },
      { t: "p", s: "初六『浚恒，贞凶，无攸利』——浚是深挖，一上来就拼命深挖、求快求深，凶。恒忌起步太猛：减肥读书健身，第一天就高强度打卡，多半两周就崩。慢就是稳，稳就是久。" },
      { t: "p", s: "九二『悔亡』——居中守正、刚柔适度，悔恨自己消掉。节奏调对了，不偏不倚，自然顺。" },
      { t: "p", s: "九三『不恒其德，或承之羞，贞吝』——德行不恒、三心二意、见异思迁，必招羞辱（「不恒其德」这成语就从这儿来）。像吕布，谁强跟谁，最后没人容他。做人最忌三天打鱼两天晒网。" },
      { t: "p", s: "九四『田无禽』——在错的地方打猎，再久也打不到鸟。恒的前提是选对正道：方向错了，盲守十年也是白费。先选对路，再谈坚持。" },
      { t: "p", s: "六五『恒其德，贞；妇人吉，夫子凶』——柔顺守正，女子吉；男子若一味顺从、没主见则凶。恒德要分角色：处低位谦逊执行、处高位果断担当，刚柔相济才久。" },
      { t: "p", s: "上六『振恒，凶』——到了顶还频繁折腾、为变而变，前功尽弃。恒极忌「振」：小有成就了别瞎折腾，沉住气守成，才是长久之终。" },

      { t: "case", title: "想练好一项本事，怎么用恒卦不翻车", s: "小雅想每天练半小时吉他，就是『恒卦』的情境——持之以恒才能从入门到熟练。她有两个走法。走错：像初六『浚恒』——第一天就练三小时、硬啃高难度曲子，手都起茧还硬撑，结果一周就厌了、琴蒙了灰，这就是『始求深也』的凶；也别像九三『不恒其德』——练两周换尤克里里、再两周又想学钢琴，三分钟热度，哪样都浅尝辄止，同学提起她只说「这人样样半吊子」；更别像九四『田无禽』——方法根本错了（只顾死记和弦图、从不听音练耳），练一年也弹不出一首完整的歌，白费功夫。走对：先初六反着来——每天就半小时、从最简单的爬音阶开始，慢就是稳；再『立不易方』——把「每周练五次、每次半小时」这个原则钉死，但练什么曲子随进度微调（持经达变）；等到了九二『悔亡』，形成习惯、不觉得苦了；遇到瓶颈别像上六『振恒』乱换老师乱换教材，沉住气打磨，半年后真能上台弹一首。曾仕强说：恒不是死守，是方向不变、方法可改——你把原则钉死、把流程做活，琴技就雷风一样，日日新又久久成。" },

      { t: "mnemonic", title: "一招记住恒卦", items: [
        "恒＝久：雷风恒（第32卦）接咸卦——咸是「感」（恋爱开始·速），恒是「久」（长相厮守·久）；《杂卦传》「咸，速也；恒，久也」。",
        "卦象：上震（雷·长男·动）下巽（风·长女·入）＝雷风相与；雷动风随、刚上柔下，要动才能恒，不是死水一潭。",
        "立不易方：把原则钉死、把流程做活（持经达变·以不变应万变）；不变的是初心底线，变的是方法节奏。",
        "恒律六检：浚恒（急进凶）→悔亡（守中）→不恒其德（三心二意招羞）→田无禽（方向错白费）→恒其德（刚柔适配）→振恒（瞎折腾凶）。先选对路，再谈坚持。"
      ]},

      { t: "quiz", questions: [
        { type: "choice", q: "恒卦的卦象「雷风恒」是怎么叠出来的？", options: ["上震（雷）下巽（风）", "上巽下震", "上兑下艮", "上乾下坤"], answer: 0, explain: "恒为下经第32卦，上震（雷·长男·动）下巽（风·长女·入），雷动风随、刚上柔下、雷风相与，恒常不息。它紧接咸卦（泽山咸）而来，讲由「感」入「久」。" },
        { type: "choice", q: "大象传「君子以立不易方」，曾仕强怎么解？", options: ["把原则钉死、把流程做活（持经达变）", "站着别动、别换方向", "方是方块、要摆整齐", "不易方=不容易的方法"], answer: 0, explain: "「方」是方针、原则。立不易方=把不能变的原则钉死、把方法流程做活，即「持经达变、以不变应万变」：不变的是初心底线，变的是方法节奏。" },
        { type: "choice", q: "九四「田无禽」给你的提醒是？", options: ["方向错了，再坚持也白费，先选对路", "田里没有鸟要去抓", "打猎才能让人恒久", "禽类不能养"], answer: 0, explain: "田无禽=在错的地方打猎，久非其位、再久也打不到鸟。恒的前提是选对正道：方向不对，盲守十年也是白费；先选对路，再谈坚持。" },
        { type: "say", q: "请用「立不易方（原则钉死、流程做活）」「浚恒凶（别一上来太猛）」「不恒其德（别三心二意）」「田无禽（先选对路再坚持）」说一段你的经历——比如你坚持过或放弃过的一件事（健身/背单词/学乐器/一段友谊）：你是像初六「浚恒」一上来猛冲后崩了，还是像九三「不恒其德」半途而废，还是像九四「田无禽」方向错了白忙？如果按恒卦，你会怎么把原则钉死、把方法做活、久久为功？", model: "我对照一下：去年我信誓旦旦要每天背50个单词，就是『恒卦』——持之以恒才能攒出词汇量。但我一开始像初六『浚恒』：第一天就背200个、还给自己定「三个月通关雅思」，结果第三天就累瘫、APP再没打开过，这就是『始求深也』的凶。后来换方法，像九二『悔亡』——每天就20个、只求稳，慢慢竟坚持下来了。但中间我也犯过九三『不恒其德』：背两周又去练口语、练两周又刷语法，样样都碰一下，同学笑我「样样通样样松」。现在按恒卦重来：先『立不易方』——把「每天20词、睡前复习」这个原则钉死（这是我的节拍器），但背哪些词、用什么APP随进度微调（流程做活，持经达变）；再避开九四『田无禽』——先确认方法对（听力加拼写一起上，不是死记中文释义），方向对了才坚持。半年下来词汇量真的上来了。曾仕强说「先选对路，再谈坚持」——恒不是死守，是方向不变、方法可改，日日新又久久成。" }
      ]}
    ]
  },
  {
    id: 33,
    title: "第33课 · 急流勇退：天山遁",
    subtitle: "曾仕强说：遁不是逃跑，是高级止损学",
    review: "上节课我们学了恒卦（雷风恒），核心一句话——立不易方，把原则钉死、把流程做活（持经达变）。恒是长长久久：方向不正的坚持是愚昧，方向对了就雷风一样日日新又久久成；初六『浚恒』一上来太猛会崩，九三『不恒其德』三心二意招羞，九四『田无禽』方向错了白费。今天《序卦传》说「物不可以久居其所，故受之以遁」——一切都久居不变是不可能的，长久到了头，就要懂得退。第33卦，遁卦。",
    blocks: [
      { t: "h", s: "一、遁卦长啥样：上乾下艮，天下有山" },
      { t: "p", s: "上节课恒卦讲完「长久」，下经接着讲「退避」。第33卦叫「遁卦」（天山遁）。「遁」就是退、隐退、转身离开。" },
      { t: "p", s: "看卦象：上面是乾（天·父·刚健），下面是艮（山·少男·止）。天下有山——天那么高，山那么稳，天主动往后退，留出空间给山。这不叫怂，叫「让」。" },
      { t: "p", s: "曾仕强讲过一个画面特别妙：云雾遮住山顶时，天和山连成一片，看着山好像很高；天一退避，大家才看清——原来山是矮的，真正高的是天。君子退一步，格局反而显出来。" },
      { t: "p", s: "而且你看，遁卦底下已经有两个阴爻（初六、六二），阴在长、阳在退。这就像小暑到大暑的节气，阴湿渐重、人和动物都躲起来避暑——时机要转，你得跟着调。" },

      { t: "h", s: "二、卦辞：遁，亨；小利贞" },
      { t: "p", s: "卦辞说：『遁，亨；小利贞。』" },
      { t: "p", s: "「亨」——退得对，反而通。不是逃跑才叫输，退错了方向才叫输。退对了，路反而打开。" },
      { t: "p", s: "「小利贞」——退要退得有节制、不乱阵脚（贞=正）。小利也吉：退不是大赢，是先把命保住、把火种留下，小赚就是赢。" },
      { t: "p", s: "曾仕强一句话点破：遁卦是「高级止损学」。不是害怕才退，是看明白了、主动退场，保存实力，等风头过去再回来。这跟消极逃避完全两码事。" },

      { t: "h", s: "三、大象传：君子以远小人，不恶而严" },
      { t: "p", s: "大象传：『天下有山，遁；君子以远小人，不恶而严。』" },
      { t: "p", s: "「远小人」= 拉物理距离，也拉心理边界。不是跟他吵、跟他斗。曾仕强说：你跟小人斗，你就变成小人；退让如果是为了同流合污，那也是小人——所以唯一正解是「远」，保持距离。" },
      { t: "p", s: "「不恶而严」= 面子上不失礼貌（不恶，不摆厌恶的脸色），原则上寸步不让（严，庄重有底线）。小人给你好处你别接，小人闹事你别掺和，但该守的规矩一步不退。" },
      { t: "p", s: "这背后是「功成不必在我」：小人暂时得势，君子就给他舞台去表现，他改邪归正好、把事办好，谁来治理都行；弄不好，你再转回来，照样有生机。这才叫进退裕如。" },

      { t: "diagram", key: "bagua", caption: "这是八卦图：乾（天·父）与艮（山·少男）是其中两个卦。遁卦＝上乾下艮（天下有山）——天主动退避、让出空间给山，正是「遁者，退也」最生动的画面。曾仕强说：天一退，大家才看清山是矮的、天才是高的——呼应第1课一家八口：父亲（乾）与少男（艮）同在，父亲懂得退后一步、把舞台留给后辈，格局反而显出来；也正好接上第32课恒卦的「立不易方」——该进时立定原则长久做，该退时主动转身保存火种。" },

      { t: "h", s: "四、六爻：遁退六阶，从遁尾到肥遁" },
      { t: "p", s: "遁卦六个爻，曾仕强叫它「遁退六阶」，一级比一级优雅——看你退得是狼狈还是从容。" },
      { t: "p", s: "初六『遁尾，厉，勿用有攸往』——退在最后面（尾巴），危险；别再往前冲了。但曾仕强补一句妙招：既然落在尾巴上跑不掉，干脆不跑（勿用有攸往），反而可能有转机。就像纸伞被淘汰，有人死守「我就做纸伞」，结果变成装饰纪念品，卖得更贵——不往，何灾也。" },
      { t: "p", s: "六二『执之用黄牛之革，莫之胜说』——用黄牛皮绳把核心（六二与九五）绑牢，谁也解不开。退之前先把核心客户、人才、口碑「锁仓」，稳住基本盘再收外围。" },
      { t: "p", s: "九三『系遁，有疾厉；畜臣妾，吉』——心被感情拴住（系遁），舍不得老团队老地盘，退得慢，危险；但把身边资源（臣妾）养好、做小事，吉。不可逞大事，先活下来。" },
      { t: "p", s: "九四『好遁，君子吉，小人否』——潇洒退场，君子吉、小人倒霉。好遁=舍得放下曾经最爱的东西、主动转型。小人舍不得，就被套牢。" },
      { t: "p", s: "九五『嘉遁，贞吉』——退得时机、方式、分寸都漂亮，正大光明地退（比如卖掉边缘业务、聚焦主业），贞吉。" },
      { t: "p", s: "上九『肥遁，无不利』——带着「肥肉」（资金、技术、品牌）全身而退，无所不利。功成身退，留得青山，再开新局。这是遁卦的最高段位。" },

      { t: "case", title: "想从一段消耗你的关系或项目里抽身，怎么用遁卦不狼狈", s: "小柯在一家公司干了五年，团队氛围越来越差、领导爱甩锅，这就是『遁卦』的情境——该退了。他有两个走法。走错：像初六『遁尾』——明明半年前就发现苗头不对，却总说『再熬熬』，等公司大规模裁员他才慌忙投简历，这时候好岗位早被抢光，落在尾巴上最危险；也别像九三『系遁』——放不下『毕竟待了五年』的情分、舍不得老同事，迟迟不肯动，结果被拖进更多烂摊子，天天内耗；更别像小人那样闹翻脸拍桌子走人，把口碑搞臭。走对：先九四『好遁』——认清该走了，潇洒转身不拖泥带水，舍得放下『元老』的身份；退之前像六二『执之用黄牛之革』——先把核心能力（行业人脉、作品集、证书）这头『黄牛』锁牢，再慢慢收外围；退的时候『不恶而严』——不跟前领导撕破脸、面上客气，但该结的账照结、底线不退；最好能走到上九『肥遁』——带着积累的经验口碑（你的『肥肉』）体面离开，下家反而更看重你。曾仕强说：遁不是逃跑是高级止损——懂得在山顶转身的人，才能把火种带到下一个春天。" },

      { t: "mnemonic", title: "一招记住遁卦", items: [
        "遁＝退：天山遁（第33卦）接恒卦——恒是久、遁是退；《序卦传》「物不可以久居其所，故受之以遁。遁者，退也」。",
        "卦象：上乾（天·父·刚健）下艮（山·少男·止）＝天下有山；天主动退避让出空间，曾仕强：天一退，大家才看清山矮天高——退一步格局显。",
        "远小人，不恶而严：拉距离不撕破脸（不恶）、守底线寸步不让（严）；跟小人斗你就变小人，所以正解是『远』，功成不必在我。",
        "遁退六阶：遁尾（落尾危险·不往反有转机）→黄牛革（锁核心）→系遁（舍不得慢凶）→好遁（潇洒吉）→嘉遁（正大光明退）→肥遁（带肥肉全身而退·最高段位）。"
      ]},

      { t: "quiz", questions: [
        { type: "choice", q: "遁卦的卦象「天山遁」是怎么叠出来的？", options: ["上乾（天）下艮（山）", "上艮下乾", "上乾下坤", "上坎下艮"], answer: 0, explain: "遁为第33卦天山遁，上乾（天·父·刚健）下艮（山·少男·止），天下有山、天高山远，天主动退避让出空间，正是「遁者，退也」。" },
        { type: "choice", q: "大象传「君子以远小人，不恶而严」，曾仕强怎么解？", options: ["拉距离不撕破脸、守底线寸步不让", "要狠心讨厌小人", "严是严厉打骂小人", "远=断联永远不理"], answer: 0, explain: "「远小人」=物理+心理边界；「不恶而严」=面子上不失礼（不恶）、原则上寸步不让（严）。曾仕强说跟小人斗你就变小人，正解是「远」——功成不必在我，给小人舞台看他表现。" },
        { type: "choice", q: "上九「肥遁，无不利」的「肥」指什么？", options: ["带着资金、技术、品牌等「肥肉」全身而退", "吃胖了再走", "肥是错误要改", "肥肉指累赘"], answer: 0, explain: "肥遁=高飞而走的退避，带着「肥肉」（资金、技术、品牌、口碑）全身而退，无所不利、无所疑。是遁卦最高段位：功成身退、留得青山再开新局。" },
        { type: "say", q: "请用「天下有山（天主动退一步）」「远小人·不恶而严（拉距离不撕破脸、守底线）」「遁尾（退晚了危险）」「肥遁（带成果体面离开）」说一段你的经历——比如你有没有该退不退、拖到『遁尾』的事（一段消耗你的关系/一份没前途的工作/一个该止损的项目）？如果按遁卦，你会怎么『不恶而严』地划清界限、又怎么走到『肥遁』带着收获体面抽身？", model: "我对照一下：前年我在一个社团待了三年，后来核心成员陆续走、新来的只混不干，气氛越来越消耗，这就是『遁卦』——该退了。但我像初六『遁尾』：明明早看出苗头，还总说『再帮一帮』，结果等社团名存实亡、我也身心俱疲才走，落在尾巴上最狼狈，简历上还不好写这段。后来另一个项目也类似，我犯了九三『系遁』——放不下『毕竟是我一手带起来的』这份情，迟迟不肯交棒，把自己拖进烂摊子。现在按遁卦重来：先认清『天下有山』——天都主动退一步让出空间，我何必死撑；再学『远小人，不恶而严』——对那个总甩锅的人，我不吵不闹（不恶）、面上客气，但该划的边界一寸不让，该拒绝的活照拒（严）；退的时候像六二『黄牛之革』先把核心人脉作品锁牢，再走；最好能走到上九『肥遁』——带着这几年攒的能力和人脉（我的『肥肉』）体面离开，下一站反而更认可我。曾仕强说遁不是逃跑是高级止损：懂得在山顶转身，才能把火种带到下一个春天。" }
      ]}
    ]
  }
];
